window.WGER_EXERCISES = [{"id":"wger-9","source":"https://wger.de/en/exercise/9/view/","name":"Swing com kettlebell","portuguese":true,"instructions":["Swing russo com kettlebell executado com as duas mãos: o peso é impulsionado pelo quadril e sobe até a altura do peito, sem passar da cabeça."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["hamstrings","glutes"],"secondaryMuscles":["quadriceps","abdominals"],"equipment":"kettlebells"},{"id":"wger-12","source":"https://wger.de/en/exercise/12/view/","name":"Seated Hip Adduction","portuguese":false,"instructions":["Starting Position: Sit on the machine with your knees inward and against the pads. Pull the pin to release the pads. Grab the handles on the sides.b"],"credit":{"author":"flori","license":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"},"images":[],"primaryMuscles":["glutes"],"secondaryMuscles":[],"equipment":"","video":{"url":"https://wger.de/media/exercise-video/12/5148c579-5df2-4618-9a7b-a2e29ac4dd7d.MOV","size":60138928,"credit":{"author":"Goulart","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}},{"id":"wger-20","source":"https://wger.de/en/exercise/20/view/","name":"Desenvolvimento Arnold","portuguese":true,"instructions":["Sentado em um banco com as costas apoiadas, segure os halteres na altura dos ombros com as palmas voltadas para você. Empurre os halteres para cima girando as mãos durante a subida, até que as palmas fiquem voltadas para a frente no topo, e desça pelo mesmo caminho de forma controlada."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["shoulders"],"secondaryMuscles":["triceps"],"equipment":"dumbbell"},{"id":"wger-31","source":"https://wger.de/en/exercise/31/view/","name":"Isometria lateral com halteres","portuguese":true,"instructions":["Segure dois halteres e estenda os braços para as laterais, na altura dos ombros, mantendo a posição o máximo de tempo que conseguir."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":"dumbbell"},{"id":"Barbell_Ab_Rollout","source":"https://wger.de/en/exercise/41/view/","name":"Rollout abdominal com barra","portuguese":true,"instructions":["Coloque uma barra no chão, aos seus pés.","Inclinando o tronco pela cintura, segure a barra com as mãos na largura dos ombros em pegada pronada.","Com um movimento lento e controlado, role a barra para a frente mantendo as costas retas.","Role de volta subindo o quadril e o glúteo até retornar à posição inicial."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}},{"id":"wger-43","source":"https://wger.de/en/exercise/43/view/","name":"Agachamento hack com barra","portuguese":true,"instructions":["Execute o agachamento com a barra posicionada atrás das pernas, segurando-a com os braços estendidos para trás."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["quadriceps"],"secondaryMuscles":["hamstrings","glutes"],"equipment":"barbell"},{"id":"wger-46","source":"https://wger.de/en/exercise/46/view/","name":"Afundo em pé com barra","portuguese":true,"instructions":["Apoie a barra sobre a parte de trás dos ombros. Fique em pé e dê o primeiro passo à frente, de modo que o joelho da perna de apoio possa tocar o chão. Depois, volte a ficar em pé e repita com a outra perna.","Mantenha sempre uma boa postura."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["quadriceps"],"secondaryMuscles":["glutes"],"equipment":"barbell","video":{"url":"https://wger.de/media/exercise-video/46/d45df7af-586b-42d0-bc56-d1e028812f12.MOV","size":23571954,"credit":{"author":"Goulart","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}},{"id":"wger-48","source":"https://wger.de/en/exercise/48/view/","name":"Rosca de punho inversa com barra","portuguese":true,"instructions":["Sentado em um banco, segure uma barra com as palmas das mãos voltadas para baixo e as mãos na largura dos ombros. Apoie os antebraços sobre as coxas e deixe os punhos pendurados além dos joelhos.","Flexione os punhos em direção ao rosto, levantando a barra. Faça uma breve pausa na posição do topo e retorne lentamente a barra à posição inicial."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":"barbell"},{"id":"wger-50","source":"https://wger.de/en/exercise/50/view/","name":"Extensão de tríceps com barra","portuguese":true,"instructions":["Posicione a barra acima da cabeça com pegada pronada fechada.","Desça o antebraço para trás do braço, mantendo os cotovelos apontados para cima. Estenda o antebraço sobre a cabeça. Desça e repita."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["triceps"],"secondaryMuscles":["shoulders","chest"],"equipment":"barbell"},{"id":"wger-51","source":"https://wger.de/en/exercise/51/view/","name":"Flexão de Punho com Barra","portuguese":true,"instructions":["Sentado em um banco, pegue uma barra com as palmas das mãos voltadas para cima e as mãos afastadas na largura dos ombros. Descanse os antebraços nas coxas e deixe os pulsos pendurados sobre os joelhos. Execute o movimento curvando as palmas das mãos e os pulsos em direção ao rosto.","Faça uma pausa por um momento na posição superior e, em seguida, retorne lentamente a barra à posição inicial."],"credit":{"author":"burenl","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":["biceps"],"equipment":"barbell"},{"id":"wger-57","source":"https://wger.de/en/exercise/57/view/","name":"Caminhada do urso 2","portuguese":true,"instructions":["- Apoie o peso nas palmas das mãos e na ponta dos pés, numa posição parecida com a da flexão de braço.","- Desloque-se dando um passo com a mão direita e o pé esquerdo, depois com a mão esquerda e o pé direito, caminhando como um urso pesado.","- Mova-se o mais rápido que conseguir e meça as repetições e séries por distância (por exemplo, 40 jardas) ou por tempo (por exemplo, 45 segundos).","- Trabalha peitorais, deltoides, tríceps, trapézios, dorsais, abdominais e lombar, flexores do quadril, quadríceps, glúteos e panturrilhas."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["shoulders","calves","chest","abdominals","triceps"],"secondaryMuscles":["glutes","lats","quadriceps"],"equipment":""},{"id":"wger-73","source":"https://wger.de/en/exercise/73/view/","name":"Supino reto","portuguese":true,"instructions":["Deite-se em um banco com a barra diretamente acima dos olhos, os joelhos levemente angulados e os pés firmes no chão. Concentre-se, respire fundo e segure a barra com as mãos um pouco além da largura dos ombros. Desça a barra lentamente até que ela toque de leve o peito, na altura dos mamilos. Empurre a barra para cima.","Se você treina com carga alta, é recomendável ter um *ajudante* que possa auxiliar caso não consiga levantar o peso sozinho.","A largura da pegada também controla qual parte do peito é mais trabalhada:","- Pegada aberta enfatiza a parte externa dos músculos peitorais","- Pegada fechada enfatiza a parte interna e o tríceps"],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"equipment":"barbell","video":{"url":"https://wger.de/media/exercise-video/73/2bdb390c-312c-4497-a722-5eed2c823e5a.MOV","size":1108545,"credit":{"author":"Goulart","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}},{"id":"wger-75","source":"https://wger.de/en/exercise/75/view/","name":"Supino com halteres","portuguese":true,"instructions":["O movimento é muito semelhante ao supino com barra; no entanto, o peso é abaixado até o peito em um ponto mais baixo.","Segure dois halteres e deite-se em um banco. Mantenha os pesos próximos ao peito, na altura dos mamilos, e empurre-os para cima até que os braços fiquem estendidos. Abaixe o peso de forma lenta e controlada."],"credit":{"author":"Jhonatan","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"equipment":"dumbbell","video":{"url":"https://wger.de/media/exercise-video/75/080c799b-8afd-4130-8d72-9cef0cd79f54.MOV","size":4543158,"credit":{"author":"Goulart","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}},{"id":"wger-76","source":"https://wger.de/en/exercise/76/view/","name":"Supino com pegada fechada","portuguese":true,"instructions":["- **Preparação:** deite-se no banco e segure a barra na largura dos ombros (mais fechado do que no supino convencional).","- **Descida:** desça a barra com controle até a parte inferior do peito.","- **Técnica:** mantenha os cotovelos junto ao tronco, sem deixá-los abrir para os lados.","- **Subida:** empurre a barra de volta para cima em linha reta, contraindo o tríceps no topo."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["triceps"],"secondaryMuscles":["shoulders","chest"],"equipment":"barbell"},{"id":"wger-79","source":"https://wger.de/en/exercise/79/view/","name":"Puxada alta curvado com halteres","portuguese":true,"instructions":["Incline levemente o tronco à frente segurando dois halteres. Puxe os halteres até o peito, mantendo os cotovelos o mais alto possível."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":"dumbbell"},{"id":"wger-81","source":"https://wger.de/en/exercise/81/view/","name":"Remada curvado com halteres","portuguese":true,"instructions":["Com um halter em cada mão, incline o tronco pelo quadril até que as mãos fiquem penduradas logo abaixo dos joelhos, como na posição inicial do levantamento terra com pernas estendidas. Mantenha o ângulo do tronco constante enquanto contrai os dorsais para puxar os cotovelos para trás, aproximando as escápulas no topo. Procure não se levantar a cada repetição e confira se as mãos passam abaixo dos joelhos em todas as repetições."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["lats"],"secondaryMuscles":[],"equipment":"dumbbell"},{"id":"wger-82","source":"https://wger.de/en/exercise/82/view/","name":"Elevação lateral curvado","portuguese":true,"instructions":["Sente-se em um banco segurando os pesos. Incline o tronco à frente o máximo possível, com os braços ligeiramente flexionados nos cotovelos. Execute uma elevação lateral mantendo a flexão dos cotovelos."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":"dumbbell","video":{"url":"https://wger.de/media/exercise-video/82/28b53647-27e7-47cf-8852-2ee666c8b628.MOV","size":13386307,"credit":{"author":"Goulart","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}},{"id":"wger-83","source":"https://wger.de/en/exercise/83/view/","name":"Remada Curvada","portuguese":true,"instructions":["1. Segurando uma barra com pegada pronada (palmas das mãos voltadas para baixo), dobre ligeiramente os joelhos e incline o tronco para a frente, flexionando a cintura, mantendo as costas retas até que fiquem quase paralelas ao chão. Dica: Certifique-se de manter a cabeça erguida. A barra deve ficar pendurada diretamente à sua frente, com os braços perpendiculares ao chão e ao tronco. Esta é a sua posição inicial.","2. Agora, mantendo o tronco imóvel, expire e levante a barra em sua direção. Mantenha os cotovelos próximos ao corpo e use apenas os antebraços para sustentar o peso. Na posição de contração máxima, contraia os músculos das costas e mantenha a posição por uma breve pausa.","3. Em seguida, inspire e abaixe lentamente a barra de volta à posição inicial.","4. Repita o número de repetições recomendado."],"credit":{"author":"br_Orion","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["lats"],"secondaryMuscles":["shoulders","biceps"],"equipment":"barbell"},{"id":"wger-84","source":"https://wger.de/en/exercise/84/view/","name":"Remada curvada inversa","portuguese":true,"instructions":["É a mesma remada convencional, mas com pegada invertida (palmas das mãos voltadas para a frente).","Segure a barra com pegada aberta, um pouco além da largura dos ombros, e incline o tronco à frente; o tronco não fica totalmente paralelo ao chão, mas forma um leve ângulo. Mantenha o peito aberto durante todo o exercício.","Puxe a barra com movimento rápido em direção ao umbigo, sem ir além disso. Desça devagar até a posição inicial. Não balance o corpo e mantenha os braços junto ao tronco."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["lats"],"secondaryMuscles":["shoulders","biceps"],"equipment":"barbell"},{"id":"wger-91","source":"https://wger.de/en/exercise/91/view/","name":"Rosca direta com barra reta","portuguese":true,"instructions":["Segure a barra na largura dos ombros, pois as costas estão retas, os ombros ligamente para trás e os braços estão armazenados. Dobre os braços, levantando o peso, com um movimento rápido. Sem fazer uma pausa, baixar a barra com um movimento lento e controlado.","Não dê seu corpo equilibrar durante o exercício, todo o trabalho é feito pelos bíceps, que são os humanos múltiplos que devem se mover (preste atenção aos cotovelos)."],"credit":{"author":"roneydya","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["biceps"],"secondaryMuscles":[],"equipment":"barbell","video":{"url":"https://wger.de/media/exercise-video/91/483f4bff-e108-41f1-8e7b-0caf24952552.MOV","size":22680665,"credit":{"author":"Goulart","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}},{"id":"wger-92","source":"https://wger.de/en/exercise/92/view/","name":"Rosca direta com halteres","portuguese":true,"instructions":["Segure dois halteres com os braços estendidos, as mãos ao lado do corpo e as palmas voltadas para dentro. Flexione os braços e leve o peso para cima com um movimento rápido. Ao mesmo tempo, gire os braços 90 graus logo no início do movimento. No ponto mais alto, gire um pouco mais os pesos para fora. Sem pausa, desça lentamente.","Não deixe o corpo balançar durante o exercício: todo o trabalho é do bíceps, o único músculo que deve se mover, com atenção aos cotovelos."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["biceps"],"secondaryMuscles":[],"equipment":"dumbbell","video":{"url":"https://wger.de/media/exercise-video/92/8bfb917c-3d0d-49b9-8073-5d7e01c1b894.MOV","size":31753930,"credit":{"author":"Goulart","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}},{"id":"wger-94","source":"https://wger.de/en/exercise/94/view/","name":"Rosca direta com barra SZ (variação)","portuguese":true,"instructions":["Segure a barra SZ na largura dos ombros, com as costas retas, os ombros ligeiramente para trás e os braços estendidos. Flexione os braços trazendo o peso para cima com um movimento rápido. Sem pausar, desça a barra com movimento lento e controlado.","Não deixe o corpo balançar durante o exercício: todo o trabalho é do bíceps, o único músculo que deve se mover, com atenção aos cotovelos."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["biceps"],"secondaryMuscles":[],"equipment":"e-z curl bar"},{"id":"wger-95","source":"https://wger.de/en/exercise/95/view/","name":"Rosca direta na polia","portuguese":true,"instructions":["Fique em pé a cerca de 30 a 40 cm da polia, com os pés firmes no chão. Segure a barra e levante o peso com movimentos rápidos. Desça o peso de forma lenta e controlada, como na rosca com halteres."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["biceps"],"secondaryMuscles":[],"equipment":"","video":{"url":"https://wger.de/media/exercise-video/95/ab770931-47d3-44fd-aef0-ac7a64c3b794.MOV","size":34233084,"credit":{"author":"Goulart","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}},{"id":"wger-112","source":"https://wger.de/en/exercise/112/view/","name":"Elevação do corpo na prancha","portuguese":true,"instructions":["1. Assuma a posição de prancha no chão, apoiando o peso do corpo na ponta dos pés e nos antebraços, com o tronco reto e os antebraços na largura dos ombros. Essa é a posição inicial.","2. Pressione as palmas das mãos com firmeza contra o chão e estenda os cotovelos para elevar o corpo. Mantenha o tronco rígido durante o movimento.","3. Desça lentamente os antebraços de volta ao chão, flexionando os cotovelos.","4. Repita conforme necessário."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["triceps"],"secondaryMuscles":["shoulders","abdominals"],"equipment":""},{"id":"wger-124","source":"https://wger.de/en/exercise/124/view/","name":"Agachamento com Anilha à Frente","portuguese":true,"instructions":["Fique em pé com os pés um pouco mais afastados que a largura dos ombros, mantendo o tronco o mais alto possível.","Segure uma anilha e estenda os braços à frente do corpo, na altura do peito. Mantenha o core firme e a coluna com a curvatura natural.","Em seguida, leve o quadril para trás e flexione os joelhos até descer o máximo que conseguir no agachamento. Pause por alguns instantes e volte à posição inicial."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["quadriceps"],"secondaryMuscles":["glutes"],"equipment":""},{"id":"wger-132","source":"https://wger.de/en/exercise/132/view/","name":"Flexão burpee","portuguese":true,"instructions":["Posição inicial:","Fique de pé reto, com os pés afastados alinhados ao quadris.","Passos:","1. Se agache e se apoie com as mãos no chão entre os joelhos e a frente de seus pés, mantendo as costas retas.","2. Mantendo as mãos no chão, pule jogando as pernas para trás para a posição de prancha altas.","3. Faça uma flexão de braços.","4. Pule os pés para frente para voltar à posição de agachamento.","5. Repita."],"credit":{"author":"er0355","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":""},{"id":"wger-137","source":"https://wger.de/en/exercise/137/view/","name":"Voador com Pegada Fechada","portuguese":true,"instructions":["O movimento é o mesmo do voador tradicional, apenas com a pegada fechada:","Sente-se na máquina voador com os pés bem apoiados no chão e os braços paralelos ao chão. Aproxime os braços até que as alças fiquem praticamente juntas (mas sem se tocar). Volte devagar. Os pesos devem permanecer no ar o tempo todo."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["chest"],"secondaryMuscles":[],"equipment":""},{"id":"wger-142","source":"https://wger.de/en/exercise/142/view/","name":"Rotação Externa na Polia","portuguese":true,"instructions":["**Passos:**","1. Comece prendendo um elástico em um poste ou em um ponto seguro, de onde ele não vá soltar, na altura do cotovelo.","2. Posicione-se de lado para o elástico e, com a mão oposta a ele, estique o braço e pegue a alça.","3. Traga o elástico até o peito mantendo o cotovelo flexionado a 90 graus e, em seguida, gire lentamente o braço num movimento de backhand, de modo que o elástico gire para fora.","4. Continue o movimento o máximo que puder, até sentir um alongamento nos ombros; segure por uma contagem e volte à posição inicial.","5. Repita pelo número de repetições e séries que desejar."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["shoulders"],"secondaryMuscles":[],"equipment":""},{"id":"wger-145","source":"https://wger.de/en/exercise/145/view/","name":"Lenhador na Polia","portuguese":true,"instructions":["Ajuste a polia um pouco abaixo da altura do peito. Mantenha o corpo voltado para a frente e o quadril estável. Pegue a alça da polia, estenda totalmente os braços e traga-os para a frente, cruzando o corpo. Segure por 1 segundo no final do movimento e retorne lentamente à posição inicial."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":""},{"id":"wger-146","source":"https://wger.de/en/exercise/146/view/","name":"Panturrilha no Leg Press","portuguese":true,"instructions":["Apoie a parte da frente dos pés na plataforma do leg press, com as pernas estendidas. Use as panturrilhas para empurrar o peso, flexionando os pés e os dedos até a posição de ponta, e depois volte à posição relaxada.","Este exercício constrói massa e força nos músculos gastrocnêmio e sóleo tanto quanto — se não melhor que — qualquer outro exercício de panturrilha."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["calves"],"secondaryMuscles":[],"equipment":""},{"id":"wger-148","source":"https://wger.de/en/exercise/148/view/","name":"Elevação de Panturrilha no Hack","portuguese":true,"instructions":["Posicione-se na máquina com as costas bem apoiadas no encosto e os pés na plataforma de panturrilha. Verifique se os pés estão com metade para fora da plataforma, de modo que você consiga alongar completamente a panturrilha para baixo.","Com os joelhos estendidos, eleve o peso o máximo que puder. Desça com movimento fluido até alongar completamente as panturrilhas. Repita."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["calves"],"secondaryMuscles":[],"equipment":""},{"id":"Chin-Up","source":"https://wger.de/en/exercise/152/view/","name":"Barra Fixa Supinada","portuguese":true,"instructions":["A barra fixa supinada é um exercício de treinamento de força. As pessoas costumam fazê-lo com o objetivo de fortalecer músculos como o latíssimo do dorso e o bíceps, que estendem o ombro e flexionam o cotovelo, respectivamente. Nesse movimento, as palmas das mãos ficam voltadas para o corpo. É uma variação da barra fixa em que a amplitude do movimento é definida em relação ao queixo da pessoa."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}},{"id":"wger-158","source":"https://wger.de/en/exercise/158/view/","name":"Puxada Alta com Pegada Fechada","portuguese":true,"instructions":["Segure a barra da puxada com as mãos mais próximas que a largura dos ombros e as palmas voltadas para longe de você. Incline o tronco levemente para trás. Puxe a barra em direção ao peito, mantendo os cotovelos próximos às laterais do corpo durante o movimento. Leve os ombros para trás no final do movimento."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["lats"],"secondaryMuscles":[],"equipment":""},{"id":"wger-161","source":"https://wger.de/en/exercise/161/view/","name":"Pullover com Halter no Banco Transversal","portuguese":true,"instructions":["Segure um halter de peso moderado com as palmas apoiadas na parte de baixo das anilhas superiores e os polegares envolvendo a barra. Deite-se de costas sobre um banco reto, de modo que apenas a parte superior das costas e os ombros fiquem em contato com o banco. Os pés devem ficar afastados na largura dos ombros e a cabeça deve pender levemente para baixo. Com o halter sustentado com os braços estendidos diretamente sobre o peito, flexione os cotovelos cerca de 15 graus e mantenha-os flexionados durante todo o movimento. Abaixe lentamente o halter para trás e para baixo num arco de semicírculo, até a posição mais baixa confortável. Eleve-o novamente devagar pelo mesmo arco até o ponto inicial e repita o número de repetições necessário."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["lats","chest"],"secondaryMuscles":[],"equipment":"dumbbell"},{"id":"Crunches","source":"https://wger.de/en/exercise/167/view/","name":"Abdominal","portuguese":true,"instructions":["1. Deite-se de barriga para cima no chão com os joelhos dobrados.","2. Curve os ombros em direção a pélvis. As mãos podem ficar atrás ou do lado do pescoço ou cruzadas sobre o peito.","3. Repita"],"credit":{"author":"wger.de","license":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"}},{"id":"wger-171","source":"https://wger.de/en/exercise/171/view/","name":"Abdominal no Banco Inclinado","portuguese":true,"instructions":["Deite-se de costas em um banco inclinado, com os pés em uma das extremidades do banco. Peça a um parceiro, ou use algum apoio (barra, etc.), para mantê-los fixos; as mãos ficam atrás da cabeça. A partir dessa posição, eleve a parte superior do corpo até que a cabeça ou os cotovelos toquem os joelhos. Faça o movimento enrolando a coluna."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["abdominals"],"secondaryMuscles":[],"equipment":""},{"id":"wger-172","source":"https://wger.de/en/exercise/172/view/","name":"Abdominal na Máquina","portuguese":true,"instructions":["O procedimento é muito parecido com o do abdominal tradicional, apenas com o peso adicional da máquina. Sente-se na máquina e apoie bem os dois pés no chão. Segure no peso, nas alças ou nos cabos e faça um movimento de enrolamento para a frente (idealmente a coluna deve perder o contato com o apoio vértebra por vértebra). Volte lentamente à posição inicial."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["abdominals"],"secondaryMuscles":[],"equipment":""},{"id":"wger-173","source":"https://wger.de/en/exercise/173/view/","name":"Abdominal na Polia","portuguese":true,"instructions":["Pegue o cabo com as mãos e segure-o ao lado das têmporas. Ajoelhe-se, mantenha a parte superior do corpo reta e flexione o tronco para a frente. Desça com movimento rápido, enrolando as costas (os cotovelos apontam para os joelhos). Depois de descer, volte lentamente à posição inicial."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["abdominals"],"secondaryMuscles":[],"equipment":""},{"id":"wger-174","source":"https://wger.de/en/exercise/174/view/","name":"Abdominal com Pernas Elevadas","portuguese":true,"instructions":["Deitado de costas, com as pernas estendidas na vertical, leve as mãos em direção aos dedos dos pés, tirando as escápulas do chão e voltando."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["abdominals"],"secondaryMuscles":[],"equipment":""},{"id":"wger-177","source":"https://wger.de/en/exercise/177/view/","name":"Ciclismo","portuguese":true,"instructions":["Ajuste o selim da bicicleta na altura do quadril e pedale com o tronco estável e as mãos no guidão. Mantenha a cadência constante e regule a marcha ou a resistência conforme a intensidade desejada, com os joelhos alinhados com os pés durante a pedalada."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":["hamstrings","glutes","lats","quadriceps"],"equipment":""},{"id":"Dead_Bug","source":"https://wger.de/en/exercise/178/view/","name":"Dead Bug","portuguese":true,"instructions":["Deite-se de costas com quadris e joelhos flexionados a 90 graus. Eleve os dois braços em direção ao teto. Puxe a lombar contra o chão para eliminar o espaço entre ela e o solo. Comece estendendo uma das pernas e tocando o calcanhar no chão. Ao estender uma perna, expire o máximo que puder, mantendo a lombar colada ao chão. Quando não conseguir mais expirar, traga o joelho de volta à posição inicial. Aumente a dificuldade segurando peso nas mãos ou estendendo o braço e a perna opostos."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}},{"id":"wger-182","source":"https://wger.de/en/exercise/182/view/","name":"Suspensão na Barra","portuguese":true,"instructions":["Suspensão executada em uma barra, com ou sem peso adicional (ajuste a espessura da barra ou o peso para ajustar a dificuldade)."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":""},{"id":"wger-184","source":"https://wger.de/en/exercise/184/view/","name":"Levantamento terra","portuguese":true,"instructions":["Fique firme, com os pés ligeiramente mais afastados do que os ombros. Fique diretamente atrás da barra, onde ela mal deve tocar sua canela, com os pés apontando um pouco para fora. Curve-se com as costas retas, os joelhos também apontando um pouco para fora. Agarre a barra com uma pegada na largura dos ombros, uma pegada por baixo e uma pegada reversa.","Puxe o peso para cima. No ponto mais alto, faça uma leve depressão para trás e puxe a barra para trás. Segure 1 ou 2 segundos nessa posição. Desça, certificando-se de que as costas não estão dobradas. Depois de descer, você pode voltar assim que os pesos tocarem o chão ou fazer uma pausa, dependendo do peso."],"credit":{"author":"wger.de","license":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"},"images":[],"primaryMuscles":["lats"],"secondaryMuscles":["glutes"],"equipment":"barbell"},{"id":"wger-185","source":"https://wger.de/en/exercise/185/view/","name":"Supino Declinado com Barra","portuguese":true,"instructions":["Deite-se em um banco declinado; a barra deve ficar diretamente acima dos olhos, os joelhos levemente angulados e os pés firmes no chão. Concentre-se, respire fundo e pegue a barra com as mãos mais afastadas que a largura dos ombros. Desça lentamente até que ela toque rapidamente o peito na altura dos mamilos. Empurre a barra para cima."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["chest"],"secondaryMuscles":[],"equipment":"barbell"},{"id":"wger-186","source":"https://wger.de/en/exercise/186/view/","name":"Supino Declinado com Halteres","portuguese":true,"instructions":["Pegue dois halteres e sente-se em um banco declinado, com os pés firmes no chão e a cabeça apoiada no banco. Segure os halteres junto ao peito, na altura dos mamilos, e empurre-os para cima até estender os braços. Desça o peso lenta e controladamente."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["chest"],"secondaryMuscles":[],"equipment":"dumbbell"},{"id":"Deficit_Deadlift","source":"https://wger.de/en/exercise/189/view/","name":"Terra com Déficit","portuguese":true,"instructions":["**Preparação:** fique em pé sobre uma anilha, um disco ou uma plataforma levemente elevada, com a barra carregada acima dos pés. Agache e pegue a barra com pegada pronada na largura dos ombros ou um pouco mais aberta, ou com pegada mista.","**Execução:** levante a barra estendendo quadris e joelhos até a extensão completa. Leve os ombros para trás no topo do movimento caso estejam arredondados. Volte o peso ao chão dobrando o quadril para trás e permitindo que os joelhos se flexionem para a frente, mantendo as costas retas e os joelhos apontados na mesma direção dos pés. Repita.","**Comentários:** durante todo o levantamento, mantenha o quadril baixo, os ombros altos e os braços e as costas retos. Os joelhos devem apontar na mesma direção dos pés em todo o movimento. Mantenha a barra próxima ao corpo para melhorar a alavancagem mecânica. A força de pegada e a resistência de força muitas vezes limitam a capacidade de fazer várias repetições com cargas pesadas. Giz de academia, straps, trabalho de pegada e pegada mista podem ser usados para melhorar a pegada. Pegada mista significa uma mão segurando com pegada pronada e a outra com pegada supinada. Um macaco de alavanca pode ser usado para levantar a barra do chão, facilitando a colocação e a retirada das anilhas.","O terra com déficit com barra enfatiza a construção de força na porção mais baixa do levantamento terra. O músculo-alvo é trabalhado isometricamente. O terra pesado com barra recruta significativamente o latíssimo do dorso. Veja também a análise do levantamento terra."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}},{"id":"wger-193","source":"https://wger.de/en/exercise/193/view/","name":"Desenvolvimento diagonal","portuguese":true,"instructions":["Você se senta no aparelho de supino, com as costas levemente inclinadas para trás. A barra deve ficar a cerca de 20 cm à sua frente. Então você empurra a barra e a traz de volta, como faria em um supino.","Nessa posição você solicita bem menos os músculos do peitoral, o que é útil se você quer treinar, mas o peito ainda não se recuperou.","Segue um link com uma pessoa em um aparelho específico para este exercício, para descrever melhor do que as minhas palavras falhas acima","http://www.schnell-online.de/db_imgs/products/img/t-80400.jpg"],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":""},{"id":"wger-194","source":"https://wger.de/en/exercise/194/view/","name":"Fundos Para Tríceps","portuguese":true,"instructions":["Levante-se em barras paralelas mantenha pressionado por 1 segundo, abaixe lentamente e controle por 4 segundos, depois volte sem descanso"],"credit":{"author":"BFad07","license":"CC0","url":"http://creativecommons.org/publicdomain/zero/1.0/"},"images":[],"primaryMuscles":["chest","triceps"],"secondaryMuscles":[],"equipment":"","video":{"url":"https://wger.de/media/exercise-video/194/dd9a663f-d8ba-4621-823b-13788ccb66bc.MOV","size":4418928,"credit":{"author":"Goulart","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}},{"id":"wger-197","source":"https://wger.de/en/exercise/197/view/","name":"Mergulho entre dois bancos","portuguese":true,"instructions":["Coloque dois bancos afastados o suficiente para que você consiga se apoiar com as mãos em um deles e apenas alcançar o outro com os pés. Durante todo o exercício as pernas ficam completamente esticadas. Com os cotovelos apontando para trás, flexione-os o máximo que puder. Empurre o corpo para cima, mas sem estender totalmente os braços."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["triceps"],"secondaryMuscles":[],"equipment":""},{"id":"wger-202","source":"https://wger.de/en/exercise/202/view/","name":"Rosca concentrada com halter","portuguese":true,"instructions":["Sente-se no banco. Segure o halter entre os pés. Apoie a parte de trás do braço na parte interna da coxa. Incline-se sobre a perna para elevar um pouco o cotovelo."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":["biceps"],"equipment":"dumbbell"},{"id":"wger-203","source":"https://wger.de/en/exercise/203/view/","name":"Agachamento taça com halter","portuguese":true,"instructions":["Segure o halter com as duas mãos pelas laterais das anilhas superiores. Mantenha o halter à frente do peito, próximo ao tronco. Afaste os pés na largura dos ombros e mantenha os joelhos levemente flexionados.","Agache até as coxas ficarem paralelas ao chão. Mantenha as costas retas, flexione e leve o quadril para trás para manter os joelhos acima dos pés. Retorne mantendo os joelhos levemente flexionados. Repita.","Mantenha o peso sobre os calcanhares e olhe à frente ou um pouco acima para manter as costas retas."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["quadriceps"],"secondaryMuscles":[],"equipment":"dumbbell"},{"id":"wger-204","source":"https://wger.de/en/exercise/204/view/","name":"Rosca inclinada com halteres","portuguese":true,"instructions":["- **Preparação:** Prepare um banco ajustável com inclinação de aproximadamente 45 a 60 graus.","- **Posição inicial:** Sente-se encostado no banco com um halter em cada mão. Deixe os braços caírem retos em direção ao chão, com as palmas voltadas para a frente (pegada supinada).","- **A rosca:** Mantendo os braços parados e os ombros firmes contra o banco, expire e faça a rosca levando os pesos em direção aos ombros.","- **Pico de contração:** No topo do movimento, contraia bem o bíceps, garantindo que os cotovelos não avancem para a frente.","- **A descida:** Inspire e desça lentamente os halteres até a posição inicial, mantendo o controle total e sentindo o alongamento no bíceps."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["biceps"],"secondaryMuscles":[],"equipment":"dumbbell"},{"id":"wger-205","source":"https://wger.de/en/exercise/205/view/","name":"Afundo estacionário com halteres","instructions":["Dê um passo à frente e mantenha essa posição com um halter em cada mão. Flexione os dois joelhos para descer e empurre o chão com o pé da frente para voltar. Troque a perna após a série."],"portuguese":true,"images":[],"primaryMuscles":["quadriceps"],"secondaryMuscles":["glutes"],"equipment":"dumbbell","video":{"url":"https://wger.de/media/exercise-video/205/c167ac34-ddbc-4e1b-8edf-1192e9d00e22.MOV","size":49889363,"credit":{"author":"Goulart","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}},{"id":"wger-206","source":"https://wger.de/en/exercise/206/view/","name":"Afundo caminhando com halteres","portuguese":true,"instructions":["Pegue um halter em cada mão e fique ereto, com os pés na largura dos ombros. Dê um passo longo de modo que o joelho da frente forme aproximadamente um ângulo reto. A perna de trás fica esticada, com o joelho baixo, mas sem tocar o chão. Complete o passo levantando-se e repita o movimento com a outra perna."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["quadriceps"],"secondaryMuscles":["glutes"],"equipment":"dumbbell","video":{"url":"https://wger.de/media/exercise-video/206/47a65c45-6fd1-4181-b71a-3a6c882e516b.MOV","size":23850769,"credit":{"author":"Goulart","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}},{"id":"wger-211","source":"https://wger.de/en/exercise/211/view/","name":"Extensão de tríceps com halter","portuguese":true,"instructions":["Posicione um halter acima da cabeça com as duas mãos por baixo da anilha interna (pegada em forma de coração).","Com os cotovelos acima da cabeça, desça o antebraço atrás do braço flexionando os cotovelos. Flexione os punhos na parte de baixo para não bater o halter na nuca. Suba o halter acima da cabeça estendendo os cotovelos e hiperestendendo os punhos. Retorne e repita."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["triceps"],"secondaryMuscles":["shoulders","chest"],"equipment":"dumbbell","video":{"url":"https://wger.de/media/exercise-video/211/85f6eb25-a76c-409e-9af9-497794ac0dfb.MOV","size":11837332,"credit":{"author":"Goulart","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}},{"id":"Face_Pull","source":"https://wger.de/en/exercise/222/view/","name":"Puxada para o rosto na polia","portuguese":true,"instructions":["Prenda uma corda em uma polia ajustada na altura do peito.","Afaste-se para trás até sustentar o peso com os braços completamente estendidos e adote uma base escalonada, com um pé à frente. Flexione levemente os joelhos para uma base estável.","Retraia as escápulas, como se apertasse o dedo de alguém entre as omoplatas, e puxe o centro da corda levemente para cima, em direção ao rosto. Uma boa referência é pensar em afastar as pontas da corda, e não apenas puxar para trás.","Ao se aproximar do rosto, faça a rotação externa de modo que os nós dos dedos fiquem voltados para o teto.","Segure por um segundo na posição final e desça lentamente."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"video":{"url":"https://wger.de/media/exercise-video/222/eea93fcc-6a3c-4783-8f70-0234c791a001.MOV","size":20624981,"credit":{"author":"Goulart","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}},{"id":"Flutter_Kicks","source":"https://wger.de/en/exercise/235/view/","name":"Tesoura de pernas","portuguese":true,"instructions":["- Deitado de costas, eleve as pernas esticadas do chão em um ângulo de 45 graus.","- Enquanto o pé esquerdo desce e quase toca o chão, o pé direito deve buscar um ângulo de 90 graus, ou o mais próximo disso possível.","- Leve o pé direito para baixo até quase tocar o chão e suba o esquerdo. Mantenha as pernas rígidas durante todo o exercício. A cabeça deve permanecer fora do chão, sustentada pela contração do abdômen superior.","- Uma sequência de esquerda sobe e direita desce, seguida de esquerda desce e direita sobe, repetida duas vezes, equivale a 1 repetição.","- Trabalha principalmente o reto abdominal, os flexores do quadril e a lombar, e secundariamente os oblíquos, com ênfase na porção inferior do abdômen."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}},{"id":"wger-237","source":"https://wger.de/en/exercise/237/view/","name":"Crucifixo na polia","portuguese":true,"instructions":["Na máquina de polia, dê dois passos à frente, mantendo as costas retas."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["chest"],"secondaryMuscles":[],"equipment":""},{"id":"wger-238","source":"https://wger.de/en/exercise/238/view/","name":"Crucifixo com halteres","portuguese":true,"instructions":["Pegue dois halteres e deite-se no banco, certificando-se de que os pés estão firmes no chão e que as costas não estão arqueadas, mas bem apoiadas no banco. Os braços ficam estendidos à frente, na largura dos ombros. Flexione então um pouco os braços e desça-os com um movimento de semicírculo para as laterais. Sem alterar o ângulo do cotovelo, traga-os de volta para cima em um movimento fluido."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["chest"],"secondaryMuscles":[],"equipment":"dumbbell"},{"id":"wger-239","source":"https://wger.de/en/exercise/239/view/","name":"Crucifixo declinado com halteres","portuguese":true,"instructions":["O exercício é o mesmo do banco reto:","Pegue dois halteres e deite-se em um banco declinado, certificando-se de que os pés estão firmes no chão e que as costas não estão arqueadas, mas bem apoiadas no banco. Os braços ficam estendidos à frente, na largura dos ombros. Flexione então um pouco os braços e desça-os com um movimento de semicírculo para as laterais. Sem alterar o ângulo do cotovelo, traga-os de volta para cima em um movimento fluido."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["chest"],"secondaryMuscles":[],"equipment":"dumbbell"},{"id":"wger-245","source":"https://wger.de/en/exercise/245/view/","name":"Tríceps testa com halteres","portuguese":true,"instructions":["Semelhante à extensão de tríceps, os halteres descem perto da cabeça e são empurrados de volta para cima. Diferentemente da extensão de tríceps convencional, procure estender os braços o máximo possível para trás."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["triceps"],"secondaryMuscles":[],"equipment":"dumbbell","video":{"url":"https://wger.de/media/exercise-video/245/c253303e-9160-4f1f-b4fe-daf1e6c8661d.MOV","size":5813842,"credit":{"author":"Goulart","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}},{"id":"wger-246","source":"https://wger.de/en/exercise/246/view/","name":"Tríceps testa com barra EZ","portuguese":true,"instructions":["Segure a barra EZ e deite-se em um banco reto de modo que cerca de 1/4 da cabeça fique para fora da borda. Estenda os braços com a barra e flexione-os para descer a barra. Pouco antes de tocar a testa, empurre-a de volta para cima.","Preste atenção aos cotovelos e aos braços: só o tríceps faz o trabalho, o resto dos braços não deve se mover."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["triceps"],"secondaryMuscles":[],"equipment":"e-z curl bar","video":{"url":"https://wger.de/media/exercise-video/246/2a194d11-ff5d-4bdf-849e-1c441cf7b0b1.MOV","size":3211377,"credit":{"author":"Goulart","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}},{"id":"wger-254","source":"https://wger.de/en/exercise/254/view/","name":"Elevação frontal com anilha","portuguese":true,"instructions":["A elevação frontal com anilha é uma variação da elevação frontal com halteres em que o praticante segura uma anilha entre as duas mãos, em vez de usar halteres, barra ou outro peso. Ela traz variedade a um treino de ombros focado em hipertrofia, ou pode fazer parte de um circuito de membros superiores ou de corpo inteiro.","1. Em pé e ereto, segure uma anilha com as duas mãos nas posições de 3 e 9 horas. As palmas devem estar voltadas uma para a outra, os braços estendidos e travados com uma leve flexão nos cotovelos, e a anilha deve ficar o mais baixo possível, perto da cintura, à sua frente. **Dica**: os braços permanecem nessa posição durante todo o exercício. Esta é a posição inicial.","2. Suba a anilha lentamente enquanto expira, até ficar um pouco acima da altura dos ombros. Segure a contração por um segundo. Ao inspirar, desça a anilha lentamente de volta à posição inicial.","3. Repita o número recomendado de repetições."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["shoulders"],"secondaryMuscles":[],"equipment":""},{"id":"wger-257","source":"https://wger.de/en/exercise/257/view/","name":"Agachamento frontal","portuguese":true,"instructions":["Esta variação do agachamento trabalha os isquiotibiais e o glúteo máximo. Também solicita os extensores da coluna e os abdutores."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["glutes"],"secondaryMuscles":["abdominals"],"equipment":"barbell","video":{"url":"https://wger.de/media/exercise-video/257/93145935-29db-4e52-9d2d-174b1c30c098.MOV","size":27090822,"credit":{"author":"Goulart","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}},{"id":"wger-260","source":"https://wger.de/en/exercise/260/view/","name":"Prancha com rotação e passagem de perna","portuguese":true,"instructions":["Fique na posição de prancha alta, apoiado nas mãos e nos pés.","Desloque o peso para a mão esquerda enquanto gira o corpo para a direita; flexione a perna direita atrás de você e estenda o braço direito para cima. Volte ao centro e repita do lado oposto. Continue alternando os lados.","**Para facilitar:** não eleve o braço depois de flexionar a perna atrás de você.","**Para dificultar:** equilibre-se com o braço e a perna estendidos por dois tempos."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["glutes","abdominals"],"secondaryMuscles":[],"equipment":""},{"id":"Hammer_Curls","source":"https://wger.de/en/exercise/272/view/","name":"Biceps Martelo","portuguese":true,"instructions":["Segure dois halteres e sente-se em um banco com as costas retas, os ombros estão ligados rolados para trás. Seus amigos apostam para seu corpo. Dobre os braços e levante o peso com um movimento rápido. Não gire como homens, como acontece com os cachos. Sem nenhuma pausa, baixar o haltere com um movimento lento e controlado.","Não balance o corpo durante o exercício, o bíceps deve fazer todo o trabalho aqui. Os cotovelos estão ao seu lado e não se movem."],"credit":{"author":"roneydya","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"video":{"url":"https://wger.de/media/exercise-video/272/df069052-2173-4f24-855f-a0eebe729f24.MOV","size":30154182,"credit":{"author":"Goulart","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}},{"id":"wger-275","source":"https://wger.de/en/exercise/275/view/","name":"Rosca martelo na polia","portuguese":true,"instructions":["Segure a polia com as mãos (palmas paralelas, apontando uma para a outra), com o corpo reto. Flexione os braços e suba o peso em um movimento rápido. Sem pausa, desça com um movimento lento e controlado, mas não estenda completamente os braços.","Não balance o corpo durante o exercício: o bíceps deve fazer todo o trabalho. Os cotovelos ficam junto ao corpo e não se movem."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["biceps"],"secondaryMuscles":[],"equipment":"","video":{"url":"https://wger.de/media/exercise-video/275/af1fff93-eb58-4ba7-97a4-b38ee67853b4.MOV","size":38048587,"credit":{"author":"Goulart","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}},{"id":"wger-279","source":"https://wger.de/en/exercise/279/view/","name":"Preensão manual","portuguese":true,"instructions":["Aparelho de preensão manual com mola, usado para fortalecer os músculos do antebraço."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":""},{"id":"wger-282","source":"https://wger.de/en/exercise/282/view/","name":"Flexão em parada de mãos","portuguese":true,"instructions":["A flexão em parada de mãos, também chamada de flexão vertical ou flexão invertida, é um tipo de flexão em que o corpo fica na posição de parada de mãos. Na versão verdadeira, o exercício é feito sem apoio, sustentado no ar. Para desenvolver força até ter equilíbrio adequado, os pés costumam ser apoiados na parede, segurados por um parceiro ou fixados de alguma outra forma para evitar a queda. As flexões em parada de mãos exigem força considerável, além de equilíbrio e controle quando feitas sem apoio."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["shoulders","triceps"],"secondaryMuscles":[],"equipment":""},{"id":"wger-283","source":"https://wger.de/en/exercise/283/view/","name":"Elevação de pernas suspenso","portuguese":true,"instructions":["Suspenso em uma barra ou em alças, eleve as pernas com os joelhos estendidos ou flexionados."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["abdominals"],"secondaryMuscles":[],"equipment":"body only"},{"id":"wger-284","source":"https://wger.de/en/exercise/284/view/","name":"Isometria entre duas polias","portuguese":true,"instructions":["Segure duas polias e fique no meio delas, de modo que ambas fiquem tensionadas, e mantenha a posição."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["biceps","triceps"],"secondaryMuscles":["shoulders"],"equipment":""},{"id":"wger-285","source":"https://wger.de/en/exercise/285/view/","name":"Salto com joelhos altos","portuguese":true,"instructions":["- Comece com as pernas um pouco mais afastadas que a largura dos ombros.","- Desça em um agachamento com o peso do corpo.","- Ao chegar ao fundo do agachamento, exploda para cima em um salto, recolhendo ao mesmo tempo os joelhos em direção ao peito no ar. Mantenha os joelhos recolhidos até o ponto mais alto do salto.","- Aterrisse com os dois pés, garantindo que os joelhos não fiquem travados, para evitar sobrecarga nas articulações. Reorganize-se para a próxima repetição o mais rápido possível, mas com controle."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["hamstrings","calves","quadriceps"],"secondaryMuscles":["abdominals"],"equipment":""},{"id":"wger-289","source":"https://wger.de/en/exercise/289/view/","name":"Remada alta explosiva","portuguese":true,"instructions":["Use uma barra leve e faça uma puxada explosiva começando na altura abaixo da patela. Puxe e eleve explosivamente usando o quadril até a altura dos ombros. Tempo: 2111."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["shoulders"],"secondaryMuscles":["glutes"],"equipment":""},{"id":"wger-291","source":"https://wger.de/en/exercise/291/view/","name":"Agachamento hindu","portuguese":true,"instructions":["Comece com os pés afastados na largura dos ombros e os braços um pouco atrás das costas.","Ao descer em direção ao chão, eleve os calcanhares, mantendo as costas o mais vertical possível.","Ao chegar à posição mais baixa, toque as mãos nos calcanhares.","Depois, levante-se terminando com os calcanhares no chão e os braços estendidos à frente do peito, fazendo um movimento de remada até a posição inicial."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["quadriceps"],"secondaryMuscles":["glutes"],"equipment":""},{"id":"wger-292","source":"https://wger.de/en/exercise/292/view/","name":"Elevação de quadril deitado","portuguese":true,"instructions":["Deitado de costas, com os pés apoiados no chão. Eleve o quadril de forma uniforme, o mais alto que conseguir, e mantenha a posição pelo maior tempo possível."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["glutes"],"secondaryMuscles":["hamstrings"],"equipment":""},{"id":"wger-294","source":"https://wger.de/en/exercise/294/view/","name":"Elevação pélvica","portuguese":true,"instructions":["A barra deve ficar apoiada diretamente na parte superior das coxas, logo abaixo da virilha. Os pés devem ficar alinhados diretamente sob os joelhos. Empurre o quadril para cima até formar uma linha reta dos joelhos aos ombros. Use uma almofada para maior conforto."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["glutes"],"secondaryMuscles":[],"equipment":"barbell","video":{"url":"https://wger.de/media/exercise-video/294/45bacf4b-1bb6-4d47-8bd1-9f00eddd4019.MOV","size":87548125,"credit":{"author":"Goulart","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}},{"id":"wger-297","source":"https://wger.de/en/exercise/297/view/","name":"Isometria de canoínha","portuguese":true,"instructions":["Deite-se de costas em um colchonete. Contraia o abdômen, estenda os braços e as pernas e eleve-os, mantendo também a cabeça e os ombros elevados. Certifique-se de que a lombar permaneça em contato com o colchonete."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["abdominals"],"secondaryMuscles":[],"equipment":""},{"id":"wger-301","source":"https://wger.de/en/exercise/301/view/","name":"Hiperextensão lombar","portuguese":true,"instructions":["Deite-se no banco de hiperextensão com o umbigo na borda frontal, deixando a parte superior do corpo pendurada livremente. Contraia todos os músculos das costas e eleve o tronco até a horizontal, sem passar disso. Desça lentamente, mantendo um fluxo contínuo e controlado do movimento."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":""},{"id":"wger-308","source":"https://wger.de/en/exercise/308/view/","name":"Crucifixo inclinado com halteres","portuguese":true,"instructions":["O exercício consiste em deitar-se em um banco inclinado e segurar um halter em cada mão. Os braços são abertos para os lados, paralelos ao chão, e depois aproximados num movimento de abraço. Trabalha principalmente os músculos do peito."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["chest"],"secondaryMuscles":[],"equipment":"dumbbell"},{"id":"wger-310","source":"https://wger.de/en/exercise/310/view/","name":"Remada com halteres no banco inclinado","portuguese":true,"instructions":["1. Com pegada neutra, apoie o tronco no banco inclinado.","2. Segure um halter em cada mão com pegada neutra, começando com os braços estendidos; esta é a posição inicial.","3. Retraia as escápulas e flexione os cotovelos para puxar os halteres para o lado do corpo.","4. Faça uma pausa no topo do movimento e retorne à posição inicial."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":["lats"],"equipment":"dumbbell"},{"id":"wger-312","source":"https://wger.de/en/exercise/312/view/","name":"Prancha inclinada com toque alternado no chão","portuguese":true,"instructions":["Faça a prancha com as pernas elevadas e os pés apoiados em uma bola suíça. Depois de estabilizar, afaste lentamente um pé da bola para o lado, até tocá-lo no chão, e volte à posição inicial. Alterne com o outro pé.","Este é um exercício para o core."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["abdominals"],"secondaryMuscles":[],"equipment":""},{"id":"Isometric_Wipers","source":"https://wger.de/en/exercise/314/view/","name":"Flexão isométrica com deslocamento lateral","portuguese":true,"instructions":["Assuma a posição de flexão de braço, com as mãos um pouco mais afastadas que a largura dos ombros.","Desloque o peso do corpo o máximo possível para um dos lados, permitindo que o cotovelo desse lado flexione.","Reverta o movimento, passando completamente para o outro lado.","Volte à posição inicial e repita pelo número de repetições desejado."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}},{"id":"wger-319","source":"https://wger.de/en/exercise/319/view/","name":"Corrida leve","portuguese":true,"instructions":["Calce o tênis, saia para a rua e comece a correr em ritmo moderado."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":""},{"id":"wger-320","source":"https://wger.de/en/exercise/320/view/","name":"Polichinelos","portuguese":true,"instructions":["1. Fique com seus pés juntos e os braços em repouso de cada lado","2. Pule para uma posição em que suas pernas fiquem abertas e as mãos toquem sob sua cabeça","3. Repita"],"credit":{"author":"student1234","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["quadriceps"],"secondaryMuscles":[],"equipment":""},{"id":"Cable_Crossover","source":"https://wger.de/en/exercise/323/view/","name":"Cross-over na polia","portuguese":true,"instructions":["Comece com as polias na altura dos ombros, uma em cada mão. Dê um passo à frente, deixando um pé na frente do outro, para dar estabilidade e manter a tensão nos cabos. Junte as mãos à frente do corpo e tente sobrepô-las alguns centímetros, de modo que os cabos se cruzem."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}},{"id":"wger-331","source":"https://wger.de/en/exercise/331/view/","name":"Swing com kettlebell (variação)","portuguese":true,"instructions":["Segure o kettlebell com firmeza nas duas mãos. Mantenha as costas retas durante todo o movimento, evitando arredondar a coluna. Com os joelhos relaxados, faça a dobradiça do quadril para trás, deixando o kettlebell passar entre os joelhos.","Flexione a partir do quadril o máximo que conseguir *sem deixar as costas arredondarem para frente*. Em seguida, lance o quadril rapidamente para frente e fique em pé, travando o corpo na postura ereta.","A velocidade desse movimento faz os braços e o kettlebell subirem à frente do corpo. Não tente *levantar* o kettlebell com os braços: o impulso do quadril faz o kettlebell subir pelo momento. Dependendo do peso do kettlebell e da velocidade do movimento do quadril, os braços sobem até cerca da altura dos ombros. No topo do balanço, deixe o quadril ir para trás novamente enquanto o kettlebell desce de volta para entre as pernas, iniciando a próxima repetição."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["glutes"],"secondaryMuscles":["hamstrings"],"equipment":"kettlebells"},{"id":"wger-341","source":"https://wger.de/en/exercise/341/view/","name":"Agachamento no Smith","instructions":["Apoie a barra na parte alta das costas e destrave o aparelho. Flexione os joelhos e o quadril para descer, mantendo os pés firmes. Estenda as pernas e trave a barra ao terminar."],"portuguese":true,"images":[],"primaryMuscles":["quadriceps"],"secondaryMuscles":["glutes"],"equipment":"","video":{"url":"https://wger.de/media/exercise-video/341/0cbfeace-dda9-4166-8424-f51358e88a4f.MOV","size":34036878,"credit":{"author":"Goulart","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}},{"id":"wger-348","source":"https://wger.de/en/exercise/348/view/","name":"Lateral Raises","portuguese":false,"instructions":["This exercise works the deltoid muscle of the shoulder. The movement starts with the arms straight, and the hands holding weights at the sides or in front of the body. Body is in a slight forward-leaning position with hips and knees bent a little. Arms are kept straight or slightly bent, and raised through an arc of movement in the coronal plane that terminates when the hands are at approximately shoulder height. Weights are lowered to the starting position, completing one rep. When using a cable machine the individual stands with the coronal plane in line with the pulley, which is at or near the ground.[9] The exercise can be completed one shoulder at a time (with the other hand used to stabilize the body against the weight moved), or with both hands simultaneously if two parallel pulleys are available."],"credit":{"author":"wger.de","license":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"},"images":[],"primaryMuscles":["shoulders"],"secondaryMuscles":[],"equipment":"dumbbell","video":{"url":"https://wger.de/media/exercise-video/348/de69928a-8a35-4096-821c-1f46de5e0e03.MOV","size":43874331,"credit":{"author":"Goulart","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}},{"id":"wger-349","source":"https://wger.de/en/exercise/349/view/","name":"Remada lateral unilateral na polia","portuguese":true,"instructions":["Ajuste a polia na altura da cintura. Comece com o braço cruzado na frente do abdômen e mova a mão para cima e para fora, até o outro lado, um braço de cada vez."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["shoulders"],"secondaryMuscles":[],"equipment":"","video":{"url":"https://wger.de/media/exercise-video/349/9896d82e-d8b6-48af-bdd5-b8545dc523e9.MOV","size":33127028,"credit":{"author":"Goulart","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}},{"id":"wger-351","source":"https://wger.de/en/exercise/351/view/","name":"Elevação lateral e frontal combinada","portuguese":true,"instructions":["1. Execute uma elevação lateral, pausando no topo do movimento.","2. Em vez de descer o peso, leve-o à frente do corpo, como se estivesse na posição alta de uma elevação frontal; faça isso com um movimento de voador, mantendo os braços estendidos.","3. Agora desça o peso até os quadríceps, ou seja, desça os halteres como se estivesse completando uma repetição de elevação frontal.","4. Reverta o movimento: faça uma elevação frontal e, no ponto mais alto, use um movimento de voador inverso para posicionar os pesos no topo de uma elevação lateral e, por fim, desça os pesos até as palmas praticamente encostarem nas laterais das coxas. Esta é uma repetição."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["shoulders"],"secondaryMuscles":[],"equipment":"dumbbell"},{"id":"wger-354","source":"https://wger.de/en/exercise/354/view/","name":"Puxada alta inclinando o tronco","portuguese":true,"instructions":["Incline o tronco para trás e puxe a barra até o peito."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["lats"],"secondaryMuscles":[],"equipment":""},{"id":"wger-355","source":"https://wger.de/en/exercise/355/view/","name":"Puxada Alta","portuguese":true,"instructions":["Puxe a barra para baixo até o strenum e mantenha as costas retas."],"credit":{"author":"br_Orion","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["lats"],"secondaryMuscles":[],"equipment":""},{"id":"wger-364","source":"https://wger.de/en/exercise/364/view/","name":"Flexora","portuguese":true,"instructions":["A flexora, também conhecida como flexão de pernas, é um exercício de isolamento que tem como alvo os músculos isquiotibiais. O exercício consiste em flexionar a perna contra a resistência, levando-a em direção aos glúteos. Outros exercícios que fortalecem os isquiotibiais são a flexão glúteo-isquiotibial e o levantamento terra."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["hamstrings","glutes"],"secondaryMuscles":[],"equipment":""},{"id":"wger-365","source":"https://wger.de/en/exercise/365/view/","name":"Leg Curls (laying)","portuguese":false,"instructions":["Lay on a bench and put your calves behind the leg holder (better if they are hold on around the lower calves). Hold a grip on the bars to make sure the body is firmly in place. Bend your legs bringing the weight up, go slowly back. During the exercise the body should not move, all work is done by the legs."],"credit":{"author":"wger.de","license":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"},"images":[],"primaryMuscles":["hamstrings"],"secondaryMuscles":[],"equipment":"","video":{"url":"https://wger.de/media/exercise-video/365/becaf013-5044-40d0-bae9-7ed60c973737.MOV","size":31825446,"credit":{"author":"Goulart","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}},{"id":"wger-366","source":"https://wger.de/en/exercise/366/view/","name":"Cadeira flexora","instructions":["Alinhe os joelhos ao eixo da máquina e posicione o apoio acima dos calcanhares. Flexione os joelhos e volte devagar."],"portuguese":true,"images":[],"primaryMuscles":["hamstrings"],"secondaryMuscles":[],"equipment":"","video":{"url":"https://wger.de/media/exercise-video/366/43df4b79-d4c3-4fbf-bcb5-e0d825b84120.MOV","size":72266814,"credit":{"author":"Goulart","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}},{"id":"wger-367","source":"https://wger.de/en/exercise/367/view/","name":"Flexora em pé","instructions":["Ajuste a máquina para apoiar o rolo atrás do tornozelo. Flexione o joelho de uma perna sem balançar o tronco e volte com controle."],"portuguese":true,"images":[],"primaryMuscles":["hamstrings"],"secondaryMuscles":[],"equipment":"","video":{"url":"https://wger.de/media/exercise-video/367/e8113ae4-a0b4-42a2-8eaa-3263de64622e.MOV","size":41674596,"credit":{"author":"Goulart","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}},{"id":"wger-369","source":"https://wger.de/en/exercise/369/view/","name":"Cadeira extensora","portuguese":true,"instructions":["A extensão de pernas é um exercício de treinamento resistido que tem como alvo o músculo quadríceps. O exercício é feito em uma máquina chamada cadeira extensora. Existem vários fabricantes dessas máquinas e cada uma é um pouco diferente. A maioria das academias e salas de musculação tem a máquina em suas instalações. A extensão de pernas é um exercício isolado, que atinge um grupo muscular específico, o quadríceps. Ela não deve ser considerada um treino completo de pernas, como o agachamento ou o levantamento terra. O exercício consiste em flexionar a perna no joelho, estendê-la e depois baixá-la de volta à posição original."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["quadriceps"],"secondaryMuscles":[],"equipment":""},{"id":"Leg_Press","source":"https://wger.de/en/exercise/371/view/","name":"Leg press","portuguese":true,"instructions":["O leg press é um exercício de treinamento com pesos no qual a pessoa empurra um peso ou resistência para longe de si usando as pernas."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"video":{"url":"https://wger.de/media/exercise-video/371/6aae16b4-01b9-4eb4-935c-3250f84d2c59.MOV","size":57665329,"credit":{"author":"Goulart","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}},{"id":"wger-373","source":"https://wger.de/en/exercise/373/view/","name":"Leg press com pés fechados","portuguese":true,"instructions":["O exercício é muito parecido com o leg press aberto.","Sente-se na máquina e apoie os pés na plataforma com uma distância entre eles que permita apenas encaixar outro pé no meio. Os pés ficam paralelos e apontados para cima.","Desça o peso até que os joelhos formem um ângulo reto. Empurre a plataforma imediatamente para cima, sem nenhuma pausa. Na posição baixa, os joelhos apontam um pouco para fora e o movimento deve ser sempre fluido."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["quadriceps"],"secondaryMuscles":["glutes"],"equipment":""},{"id":"wger-374","source":"https://wger.de/en/exercise/374/view/","name":"Leg press com pés abertos","portuguese":true,"instructions":["Sente-se na máquina e apoie os pés na plataforma, um pouco mais afastados que a largura dos ombros. Os pés ficam virados para fora por alguns graus.","Desça o peso até que os joelhos formem um ângulo reto. Empurre a plataforma imediatamente para cima, sem nenhuma pausa. Na posição baixa, os joelhos apontam um pouco para fora e o movimento deve ser sempre fluido."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["quadriceps"],"secondaryMuscles":["glutes"],"equipment":"","video":{"url":"https://wger.de/media/exercise-video/374/5336822a-7803-45b3-a880-f2bbf37a28f2.MOV","size":45597793,"credit":{"author":"Goulart","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}},{"id":"wger-375","source":"https://wger.de/en/exercise/375/view/","name":"Leg press no hack","instructions":["Apoie as costas no encosto e os pés na plataforma. Solte a trava, flexione os joelhos com controle e pressione a plataforma para voltar. Trave o aparelho no fim."],"portuguese":true,"images":[],"primaryMuscles":["quadriceps"],"secondaryMuscles":[],"equipment":"","video":{"url":"https://wger.de/media/exercise-video/375/effa7a81-dbdd-4014-83ee-ddf0fd835301.MOV","size":80419952,"credit":{"author":"Goulart","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}},{"id":"wger-376","source":"https://wger.de/en/exercise/376/view/","name":"Levantamento de pernas","portuguese":true,"instructions":["Posição inicial:","Deite-se de costas, com os pés juntos, e os braços ao seu lado.","Passos:","1. Dobre os joelhos, depois os endireite para apontar para cima.","2. Mantenha as pernas retas, abaixe-as juntas, sem tocar o chão. Quanto mais baixo você for, mais intenso será o exercício.","3. Levante as duas pernas juntas para apontar para cima novamente.","4. Repita a partir do passo 2."],"credit":{"author":"BFad07","license":"CC0","url":"http://creativecommons.org/publicdomain/zero/1.0/"},"images":[],"primaryMuscles":["abdominals"],"secondaryMuscles":[],"equipment":""},{"id":"wger-377","source":"https://wger.de/en/exercise/377/view/","name":"Elevação de pernas deitado","portuguese":true,"instructions":["Deite-se em um banco e segure na parte reclinável com as mãos para se manter estável. Mantenha as pernas estendidas e eleve-as até formarem um ângulo de cerca de 45°. Faça uma pausa curta de 1 segundo e desça lentamente até a posição inicial. Para aumentar a intensidade, você pode fazer uma pausa mais longa de 7 segundos a cada cinco repetições."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["abdominals"],"secondaryMuscles":[],"equipment":""},{"id":"wger-378","source":"https://wger.de/en/exercise/378/view/","name":"Elevação de pernas em pé","portuguese":true,"instructions":["Coloque os antebraços sobre os apoios da máquina de elevação de pernas, com o corpo suspenso livremente. Eleve as pernas com um movimento rápido o mais alto que conseguir, faça uma pausa curta de 1 segundo no topo e desça novamente. Certifique-se de que o corpo não balance durante o exercício; apenas as pernas devem se mover."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["abdominals"],"secondaryMuscles":[],"equipment":""},{"id":"wger-379","source":"https://wger.de/en/exercise/379/view/","name":"Supino em máquina articulada","portuguese":true,"instructions":["Ajuste a altura do assento para que as manoplas fiquem na parte inferior do peitoral."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["chest"],"secondaryMuscles":[],"equipment":""},{"id":"wger-380","source":"https://wger.de/en/exercise/380/view/","name":"Remada em máquina articulada","portuguese":true,"instructions":["Ajuste a altura do assento para que as manoplas fiquem na parte inferior do peitoral ou logo abaixo."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["lats"],"secondaryMuscles":[],"equipment":""},{"id":"wger-382","source":"https://wger.de/en/exercise/382/view/","name":"Isometria em L","portuguese":true,"instructions":["Mantenha a posição em L pelo maior tempo possível."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":""},{"id":"wger-394","source":"https://wger.de/en/exercise/394/view/","name":"Remada baixa","portuguese":true,"instructions":["Sente-se, coloque os pés nos pontos de apoio e agarre a barra com uma pegada larga. Puxe o peso com um movimento rápido em direção ao umbigo, não para cima. Mantenha os braços e cotovelos durante o movimento próximos ao corpo. Seus ombros são puxados juntos. Deixe o peso cair lentamente até que seus braços estejam completamente esticados."],"credit":{"author":"wger.de","license":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"},"images":[],"primaryMuscles":["lats"],"secondaryMuscles":["biceps"],"equipment":""},{"id":"wger-454","source":"https://wger.de/en/exercise/454/view/","name":"Flexão Pike","portuguese":true,"instructions":["Posição inicial:","Com a cara virada para baixo:Seu corpo deve fazer uma forma em V, com as costas, braços e pernas retas. Seus quadris devem estar para cima no ar.Você pode chegar a esta posição caminhando com as mãos para trás a partir de uma prancha alta.","Passos:","1. Dobre os cotovelos para o lado, mantendo suas costas e pernas retas e movendo sua cabeça para mais perto do chão.","2. Endireite os braços, empurrando os quadris para cima e mantendo as costas e as pernas retas.","3. Repita."],"credit":{"author":"Nash","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["chest"],"secondaryMuscles":["triceps"],"equipment":""},{"id":"wger-456","source":"https://wger.de/en/exercise/456/view/","name":"Pistol squats esquerda","portuguese":true,"instructions":["1. Fique de pé em uma perna, com a outra perna reta e ligeiramente para frente.","2. Dobre um joelho lentamente, descendo para um agachamento e mantendo as costas e a outra perna reta.","3. Levante-se lentamente do agachamento, endireitando o joelho dobrado e mantendo a outra perna reta.","4. Repita"],"credit":{"author":"minifigmaster125","license":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"},"images":[],"primaryMuscles":["hamstrings","glutes"],"secondaryMuscles":["shoulders","biceps"],"equipment":""},{"id":"Plank","source":"https://wger.de/en/exercise/458/view/","name":"Prancha horizontal","portuguese":true,"instructions":["Posição inicial:","1. Inicie na posição de quatro.Os braços devem dobrar-se em um ângulo reto, com os ombro alinhados aos cotovelos.As costas devem estar direitas, com todo o corpo em linha reta.","Passos:","1. Mantenha essa posição."],"credit":{"author":"YYCfit / BFad07","license":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"}},{"id":"wger-465","source":"https://wger.de/en/exercise/465/view/","name":"Preacher Curls","portuguese":false,"instructions":["Place the EZ curl bar on the rest handles in front of the preacher bench. Lean over the bench and grab the EZ curl bar with palms up. Sit down on the preacher bench seat so your upper arms rest on top of the pad and your chest is pressed against the pad. Lower the weight until your elbows are extended and arms are straight. Bring the weights back up to the starting point by contracting biceps. Repeat"],"credit":{"author":"cgoob883","license":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":"e-z curl bar","video":{"url":"https://wger.de/media/exercise-video/465/5d2339a4-815f-46ba-aa19-8a763cfdeba0.MOV","size":46887882,"credit":{"author":"Goulart","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}},{"id":"Pullups","source":"https://wger.de/en/exercise/475/view/","name":"Barra fixa pronada","portuguese":true,"instructions":["Posição inicial:","Comece pendurando-se na barra de pull-up, com as palmas das mãos voltadas para fora e os pés fora do chão.Suas mãos devem estar ligeiramente mais afastadas do que a largura dos ombros. Apenas ligeiramente, de modo que os cotovelos ainda estejam na frente do corpo e não diretamente para o lado.Seu corpo deve ser reto e apontado ligeiramente para a frente. Seus braços devem estar estendidos.","Passos:","1. Use sua força para puxar o corpo para cima de maneira uniforme, aproximando o peito da barra e o queixo logo acima dela. NÃO se levante usando impulso, como chutar.","2. Abaixe cuidadosamente o corpo de volta à posição inicial.","3. Repita.","Dicas:","* Para fazer flexões corretamente, você deve primeiro aumentar a força em várias áreas-chave, incluindo ombros, braços e abdominais. Comece com flexões somente depois de ter construído força suficiente com outros exercícios."],"credit":{"author":"wger.de","license":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"},"video":{"url":"https://wger.de/media/exercise-video/475/83067ffe-ccb9-4e22-8507-5131b211ce74.MOV","size":57098527,"credit":{"author":"Goulart","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}},{"id":"wger-477","source":"https://wger.de/en/exercise/477/view/","name":"Pull Ups na máquina","portuguese":true,"instructions":["Os pull-ups da máquina são uma variação assistida do exercício pull-up tradicional. Eles são projetados para ajudar as pessoas que estão desenvolvendo a força necessária para realizar o movimento completo. A máquina permite ajustar o peso para fornecer suporte adequado durante o exercício.","Para realizar flexões na máquina, siga os seguintes passos: posicione-se corretamente, ajuste o peso para o suporte desejado, segure a barra com as mãos alinhadas com os ombros, mantenha os braços retos e a postura ereta. Inicie o movimento flexionando os cotovelos e puxando o corpo em direção à barra. Suba até que seu queixo esteja acima da barra e seus ombros estejam firmes.","A descida deve ser feita de forma controlada, estendendo totalmente os braços. Realize o número desejado de repetições, adaptando-o à sua habilidade. Lembre-se de respirar corretamente durante o exercício, inspirando na fase descendente e expirando ao puxar o corpo para cima.","A prática regular de flexões na máquina fortalecerá os músculos das costas, ombros e braços, ajudando a melhorar a postura e a força geral. À medida que você ganha mais força, pode reduzir gradualmente a assistência fornecida pela máquina e progredir para a tradicional flexão sem ajuda.","Essa variação do exercício é uma opção acessível para iniciantes ou pessoas que lutam para realizar flexões completas. Lembre-se de adaptar o peso e o número de repetições de acordo com seu nível de força e capacidade. A prática regular e a progressão gradual ajudarão a melhorar sua forma e progredir em direção a flexões completas."],"credit":{"author":"wger.de","license":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"},"images":[],"primaryMuscles":["lats"],"secondaryMuscles":["shoulders","biceps"],"equipment":"","video":{"url":"https://wger.de/media/exercise-video/477/2e23bb52-2782-40c8-bf88-fa2d2e2a9a0d.MOV","size":57098527,"credit":{"author":"Goulart","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}},{"id":"wger-484","source":"https://wger.de/en/exercise/484/view/","name":"Levantamento terra em rack","portuguese":true,"instructions":["O levantamento terra deve ser feito usando uma máquina Smith ou um rack livre. A barra ou haltere deve ficar logo abaixo do nível da rótula. Levante usando os glúteos e através dos calcanhares e depois volte à posição inicial com um movimento de controle de 2 segundos.","Este exercício tem como alvo principalmente a região lombar e os glúteos."],"credit":{"author":"roneydya","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["glutes"],"secondaryMuscles":["biceps"],"equipment":""},{"id":"Romanian_Deadlift","source":"https://wger.de/en/exercise/507/view/","name":"Romanian Deadlift","portuguese":false,"instructions":["DL from top to pos 2: https://www.youtube.com/watch?v=WtWtjViRsKo"],"credit":{"author":"pjwirth","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"video":{"url":"https://wger.de/media/exercise-video/507/307e7276-a14d-4ea0-b579-f5b0dbc6f5af.MOV","size":38136083,"credit":{"author":"Goulart","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}},{"id":"wger-512","source":"https://wger.de/en/exercise/512/view/","name":"Rowing seated, narrow grip","portuguese":false,"instructions":["* Tighten muscles","* Controlled movement","* Slow movement","* Keep upper body upright","* Do not lean back","* Pull toward chest"],"credit":{"author":"wger.de","license":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"},"images":[],"primaryMuscles":["lats"],"secondaryMuscles":[],"equipment":"","video":{"url":"https://wger.de/media/exercise-video/512/fff4c294-93f0-4926-b3a2-bf59ad4afaa5.MOV","size":34332925,"credit":{"author":"Goulart","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}},{"id":"wger-537","source":"https://wger.de/en/exercise/537/view/","name":"Supino Inclinado com Halteres.","portuguese":true,"instructions":["- * O banco deve estar inclinado entre 30 e 45 graus.","- * Certifique-se de empurrar os halteres diretamente para cima (perpendiculares ao chão)."],"credit":{"author":"Jhonatan","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"equipment":"dumbbell","video":{"url":"https://wger.de/media/exercise-video/537/b9c937e9-daeb-42a9-be8e-7a77e368478c.MOV","size":10602354,"credit":{"author":"Goulart","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}},{"id":"wger-538","source":"https://wger.de/en/exercise/538/view/","name":"Supino inclinado com barra","portuguese":true,"instructions":["Para uma execução lenta, use a cadência 4010."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"equipment":"barbell","video":{"url":"https://wger.de/media/exercise-video/538/4349a6f6-4cee-4c09-828b-c5e7fc2c1ff1.MOV","size":6205424,"credit":{"author":"Goulart","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}},{"id":"wger-543","source":"https://wger.de/en/exercise/543/view/","name":"Desenvolvimento na máquina","instructions":["Ajuste o banco para que as alças fiquem na altura dos ombros. Pressione para cima, mantendo as costas apoiadas, e volte devagar."],"portuguese":true,"images":[],"primaryMuscles":["shoulders"],"secondaryMuscles":["triceps"],"equipment":"","video":{"url":"https://wger.de/media/exercise-video/543/dbfd396b-1aab-4a64-a50b-2c31ff0a2cf7.MOV","size":23511495,"credit":{"author":"Goulart","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}},{"id":"wger-567","source":"https://wger.de/en/exercise/567/view/","name":"Shoulder Press, Dumbbells","portuguese":false,"instructions":["Sit on a bench, the back rest should be almost vertical. Take two dumbbells and bring them up to shoulder height, the palms and the elbows point during the whole exercise to the front. Press the weights up, at the highest point they come very near but don't touch. Go slowly down and repeat."],"credit":{"author":"wger.de","license":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"},"images":[],"primaryMuscles":["shoulders"],"secondaryMuscles":[],"equipment":"dumbbell","video":{"url":"https://wger.de/media/exercise-video/567/64f33c19-1d96-4b7c-af17-6c6a4941c614.MOV","size":62860017,"credit":{"author":"Goulart","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}},{"id":"wger-570","source":"https://wger.de/en/exercise/570/view/","name":"Encolher os ombros","portuguese":true,"instructions":["Posicão inicial:","Sente-se ou fique de pé com as costas retas.","Passos:","1. Levante os ombros o máximo possível e segure por 5 segundos.","2. Solte os ombros de volta para uma posição relaxada.","3. Repita."],"credit":{"author":"BFad07","license":"CC0","url":"http://creativecommons.org/publicdomain/zero/1.0/"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":"","video":{"url":"https://wger.de/media/exercise-video/570/bd1f14a3-9d2b-4ec0-b6b9-e82d739f7e60.MOV","size":31195824,"credit":{"author":"Goulart","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}},{"id":"wger-572","source":"https://wger.de/en/exercise/572/view/","name":"Encolhimento com halteres","portuguese":true,"instructions":["O exercício consiste em segurar um halter em cada mão e encolher os ombros na direção das orelhas, depois baixá-los novamente. Trabalha principalmente o trapézio, na parte superior das costas, e pode ajudar a melhorar a postura e a estabilidade dos ombros."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["shoulders"],"secondaryMuscles":[],"equipment":"dumbbell"},{"id":"wger-575","source":"https://wger.de/en/exercise/575/view/","name":"Encolhimento de ombros no Smith","instructions":["Segure a barra com os braços estendidos. Eleve os ombros em direção às orelhas sem girá-los e abaixe com controle."],"portuguese":true,"images":[],"primaryMuscles":["shoulders"],"secondaryMuscles":["triceps"],"equipment":"","video":{"url":"https://wger.de/media/exercise-video/575/a7d99f2b-86fc-433a-8ab1-83144c802296.MOV","size":35270778,"credit":{"author":"Goulart","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}},{"id":"wger-580","source":"https://wger.de/en/exercise/580/view/","name":"Prancha lateral esquerda","portuguese":true,"instructions":["1. Deite-se de lado, com o cotovelo inferior em ângulo reto, com o braço para fora","2. Levante sua pélvis do chão levantando o ombro inferior para cima, mantendo o antebraço no chão; sua cabeça, pélvis e pés devem estar em linha reta","3. Mantenha esta posição"],"credit":{"author":"http://www.bodybuilding.com/","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["abdominals"],"secondaryMuscles":[],"equipment":""},{"id":"wger-584","source":"https://wger.de/en/exercise/584/view/","name":"Single-arm Preacher Curl","portuguese":false,"instructions":["Sit on the preacher curl bench and perform a bicep curl with a dumbbell in one hand. Your other hand can be at rest, or beneath your curling arm's elbow."],"credit":{"author":"tuckerm","license":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"},"images":[],"primaryMuscles":["biceps"],"secondaryMuscles":[],"equipment":"dumbbell","video":{"url":"https://wger.de/media/exercise-video/584/109e8d5d-62a4-40ad-8813-2ccef5bc751f.MOV","size":30869204,"credit":{"author":"Goulart","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}},{"id":"wger-590","source":"https://wger.de/en/exercise/590/view/","name":"Elevação de panturrilha na máquina (sentado)","portuguese":true,"instructions":["Sente-se em um banco para elevação de panturrilha e verifique se os pés estão apoiados só pela metade e se você consegue alongar completamente as panturrilhas para baixo. Suba os calcanhares o máximo que conseguir. No ponto mais alto, faça uma pausa curta de 1 ou 2 segundos e desça."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":["calves"],"equipment":"","video":{"url":"https://wger.de/media/exercise-video/590/a325ae2e-686b-4a1f-aff2-ba37fa3fa157.MOV","size":27735168,"credit":{"author":"Goulart","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}},{"id":"wger-615","source":"https://wger.de/en/exercise/615/view/","name":"Agachamentos","portuguese":true,"instructions":["1. Fique com os pés alinhados com os ombros","2. Mova o quadril para trás e dobre os joelhos e o quadril para abaixar o troco","3. Repita"],"credit":{"author":"wger.de","license":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"},"images":[],"primaryMuscles":["quadriceps"],"secondaryMuscles":["glutes"],"equipment":"barbell"},{"id":"wger-616","source":"https://wger.de/en/exercise/616/view/","name":"Agachamento de impulso","portuguese":true,"instructions":["Posição inicial:","Comece na posição de prancha alta:costas, braços e pernas retos e as mãos afastadas alinhadas aos ombros.","Passos:","1. Pule jogando seus pés para frente entre os braços, mantendo as costas reta.","2. Mantendo suas mãos no chão, retorne suas pernas para a posição de prancha altas.","3. Repita."],"credit":{"author":"BFad07","license":"CC0","url":"http://creativecommons.org/publicdomain/zero/1.0/"},"images":[],"primaryMuscles":["glutes","quadriceps","abdominals"],"secondaryMuscles":[],"equipment":""},{"id":"Standing_Calf_Raises","source":"https://wger.de/en/exercise/622/view/","name":"Standing Calf Raises","portuguese":false,"instructions":["Get onto the calf raises machine, you should able to completely push your calves down. Stand straight, don't make a hollow back and don't bend your legs. Pull yourself up as high as you can. Make a small pause of 1 - 2 seconds and go slowly down."],"credit":{"author":"wger.de","license":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"},"video":{"url":"https://wger.de/media/exercise-video/622/461171e5-2b16-407d-bf27-27aeef43f105.MOV","size":27311167,"credit":{"author":"Goulart","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}},{"id":"wger-627","source":"https://wger.de/en/exercise/627/view/","name":"Stiff","portuguese":true,"instructions":["Voce pega o halter, trava a dorsal estufa o peito, inclina até a altura do calcanhar"],"credit":{"author":"admin","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["hamstrings"],"secondaryMuscles":["glutes"],"equipment":"barbell"},{"id":"wger-632","source":"https://wger.de/en/exercise/632/view/","name":"Agachamentos de sumô","portuguese":true,"instructions":["Posição inicial:","Fique em pé com as pernas separadas e os dedos dos pés virados para fora.","Passos:","1. Agache lentamente dobrando os joelhos. Jogue os braços para frente. Mantenha a cabeça, o peito e os quadris em linha reta. Aperte seus glúteos.","2. Levante de volta para a posição inicial.","3. Repita este exercício em um movimento pulsante."],"credit":{"author":"sophialj","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["glutes","quadriceps"],"secondaryMuscles":[],"equipment":""},{"id":"Tricep_Dumbbell_Kickback","source":"https://wger.de/en/exercise/655/view/","name":"Tricep Dumbbell Kickback","portuguese":false,"instructions":["1. Start with a dumbbell in each hand and your palms facing your torso. Keep your back straight with a slight bend in the knees and bend forward at the waist. Your torso should be almost parallel to the floor. Make sure to keep your head up. Your upper arms should be close to your torso and parallel to the floor. Your forearms should be pointed towards the floor as you hold the weights. There should be a 90-degree angle formed between your forearm and upper arm. This is your starting position.","2. Now, while keeping your upper arms stationary, exhale and use your triceps to lift the weights until the arm is fully extended. Focus on moving the forearm.","3. After a brief pause at the top contraction, inhale and slowly lower the dumbbells back down to the starting position.","4. Repeat the movement for the prescribed amount of repetitions.","**Variations:** This exercise can be executed also one arm at a time much like the one arm rows are performed.","Also, if you like the one arm variety, you can use a low pulley handle instead of a dumbbell for better peak contraction. In this case, the palms should be facing up (supinated grip) as opposed to the torso (neutral grip)."],"credit":{"author":"http://www.bodybuilding.com/","license":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"},"video":{"url":"https://wger.de/media/exercise-video/655/2d88a05b-bde3-4026-bfbf-524c11068dc5.MOV","size":3407290,"credit":{"author":"Goulart","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}},{"id":"wger-659","source":"https://wger.de/en/exercise/659/view/","name":"Triceps Extensions on Cable","portuguese":false,"instructions":["Grab the cable, stand with your feet shoulder wide, keep your back straight and lean forward a little. Push the bar down, making sure the elbows don't move during the exercise. Rotate your hands outwards at the very end and go back to the initial position without pause."],"credit":{"author":"wger.de","license":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"},"images":[],"primaryMuscles":["triceps"],"secondaryMuscles":[],"equipment":"","video":{"url":"https://wger.de/media/exercise-video/659/1f2eb3b6-3185-429f-8330-26dc88f39aff.MOV","size":7557215,"credit":{"author":"Goulart","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}},{"id":"wger-660","source":"https://wger.de/en/exercise/660/view/","name":"Extensões de tríceps no cabo com barra","portuguese":true,"instructions":["Agarre a barra, fique em pé com os pés afastados dos ombros, mantenha as costas retas e incline-se um pouco para a frente. Empurre a barra para baixo, certificando-se de que os cotovelos não se movam durante o exercício. Sem pausa, volte à posição inicial."],"credit":{"author":"wger.de","license":"CC-BY-SA 3","url":"https://creativecommons.org/licenses/by-sa/3.0/deed.en"},"images":[],"primaryMuscles":["triceps"],"secondaryMuscles":[],"equipment":""},{"id":"wger-661","source":"https://wger.de/en/exercise/661/view/","name":"Tríceps na máquina","portuguese":true,"instructions":["Sente-se","e segure a barra firmemente com as mãos. Agora pressione o peso para","cima (não estenda totalmente os braços) e abaixe-o lentamente novamente.","Tal como acontece com outros exercícios de tríceps, é importante não","mover a parte superior dos braços."],"credit":{"author":"stwalkerster","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["triceps"],"secondaryMuscles":[],"equipment":""},{"id":"wger-694","source":"https://wger.de/en/exercise/694/view/","name":"Remada alta com halteres","portuguese":true,"instructions":["Segure um halter em cada mão à frente do corpo, com as palmas voltadas para você. Suba as mãos em linha reta até ficarem sob o queixo e depois desça. Repita o exercício."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["shoulders"],"secondaryMuscles":["biceps"],"equipment":"dumbbell"},{"id":"wger-702","source":"https://wger.de/en/exercise/702/view/","name":"Elevação da panturrilha esquerda","portuguese":true,"instructions":["1. Fique de pé no chão ou na borda de um degrau para aumentar o alcance do movimento. Levante um pé, colocando a parte superior sobre sua panturrilha.","2. Levante os calcanhares até ficar de pé sobre os dedos do pé.","3. Fique nesta posição por três segundos, depois abaixe o pé sem tocar o chão com seu calcanhar."],"credit":{"author":"McMarcel13","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["calves"],"secondaryMuscles":[],"equipment":""},{"id":"wger-718","source":"https://wger.de/en/exercise/718/view/","name":"Agachamento parede","portuguese":true,"instructions":["1. Encoste na parede, de frente com os pés firmes no chão, alinhados na largura dos ombros e afastados da parede cerca de 60 centímetros","2. Deslize pela parede, mantendo as costas pressionada, até que as pernas fiquem em ângulo reto, paralelas ao chão. Os joelhos devem estar diretamente acima dos tornozelos.Dor no quadríceps é normal. Pare se sentir dor nos joelhos ou na rótula do joelho"],"credit":{"author":"Blablabla","license":"CC0","url":"http://creativecommons.org/publicdomain/zero/1.0/"},"images":[],"primaryMuscles":["hamstrings","quadriceps"],"secondaryMuscles":[],"equipment":""},{"id":"wger-723","source":"https://wger.de/en/exercise/723/view/","name":"Puxada alta aberta","portuguese":true,"instructions":["**Movimento descendente:**","- Puxe a barra para baixo para que ela passe perto do queixo e toque a parte superior do peito.","- Mantenha o resto do corpo imóvel.","**Movimento para cima:**","- Permita que os cotovelos se estendam para deixar a barra subir até a posição inicial.","- Mantenha o resto do corpo imóvel."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["lats"],"secondaryMuscles":["shoulders"],"equipment":""},{"id":"wger-801","source":"https://wger.de/en/exercise/801/view/","name":"Flexão com halteres","portuguese":true,"instructions":["Flexões normais feitas com as mãos apoiadas nos halteres, o que amplia a amplitude do movimento."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"equipment":"dumbbell"},{"id":"wger-802","source":"https://wger.de/en/exercise/802/view/","name":"Afundo caminhando com barra","instructions":["Apoie a barra na parte alta das costas. Dê um passo à frente, flexione os joelhos e empurre o chão com o pé da frente. Continue alternando as pernas."],"portuguese":true,"images":[],"primaryMuscles":["glutes","quadriceps"],"secondaryMuscles":["hamstrings","calves"],"equipment":"barbell","video":{"url":"https://wger.de/media/exercise-video/802/85d1d7f8-c3c5-47e8-9b26-56896919e6e7.MOV","size":23668353,"credit":{"author":"Goulart","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}},{"id":"wger-803","source":"https://wger.de/en/exercise/803/view/","name":"Tríceps unilateral na polia","instructions":["Com o cabo na polia alta, segure a alça com uma mão e mantenha o cotovelo junto ao corpo. Estenda o braço e retorne devagar."],"portuguese":true,"images":[],"primaryMuscles":["triceps"],"secondaryMuscles":[],"equipment":"","video":{"url":"https://wger.de/media/exercise-video/803/99e0001f-217a-4b11-823c-014d24a5415e.MOV","size":4296447,"credit":{"author":"Goulart","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}}},{"id":"wger-820","source":"https://wger.de/en/exercise/820/view/","name":"Fingerboard com borda de 20 mm","portuguese":true,"instructions":["Pendure-se por 10 segundos em um fingerboard com borda de 20 mm."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":""},{"id":"Cable_Rear_Delt_Fly","source":"https://wger.de/en/exercise/822/view/","name":"Voador inverso na polia","portuguese":true,"instructions":["O voador inverso na polia, também conhecido como crucifixo inverso na polia, é um exercício para fortalecer e definir o deltoide. É um dos melhores exercícios de isolamento para as costas e o deltoide posterior. Esse treino tem como alvo os deltoides posteriores (da parte de trás), usando também uma série de músculos dos membros superiores.","1. Ajuste a carga e as polias na altura correta. Você deve conseguir ver as polias, pois elas precisam ficar acima da sua cabeça.","2. Com a mão direita, pegue a polia esquerda, e com a mão esquerda, pegue a polia direita, cruzando os cabos na sua frente. Esta é a posição inicial.","3. Inicie o movimento levando os braços para trás e para a frente, mantendo-os estendidos.","4. Faça uma breve pausa no final do movimento antes de retornar as alças à posição inicial."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}},{"id":"wger-828","source":"https://wger.de/en/exercise/828/view/","name":"Voador inverso no banco inclinado","portuguese":true,"instructions":["O voador inverso com halteres no banco inclinado é um exercício de membros superiores que trabalha os deltoides posteriores, além dos músculos posturais da parte superior das costas. Como atinge músculos pequenos, costuma ser executado com carga leve e muitas repetições, como 10 a 15 repetições por série ou mais."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["shoulders"],"secondaryMuscles":[],"equipment":"dumbbell"},{"id":"wger-911","source":"https://wger.de/en/exercise/911/view/","name":"Tríceps testa inclinado","portuguese":true,"instructions":["Sentado a 45 graus, usando halteres para fazer o tríceps testa inclinado."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["triceps"],"secondaryMuscles":[],"equipment":""},{"id":"wger-915","source":"https://wger.de/en/exercise/915/view/","name":"Rotação de ombros com anilha (volante)","portuguese":true,"instructions":["Sentado, segure uma anilha com as duas mãos como se fosse um volante, elevada um pouco abaixo da altura dos olhos."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["shoulders"],"secondaryMuscles":[],"equipment":""},{"id":"wger-923","source":"https://wger.de/en/exercise/923/view/","name":"Remada deitado com halteres + encolhimento sentado","portuguese":true,"instructions":["Deitado de barriga para baixo em um banco com leve inclinação."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["lats"],"secondaryMuscles":["biceps"],"equipment":"dumbbell"},{"id":"wger-925","source":"https://wger.de/en/exercise/925/view/","name":"Supino inclinado no smith","portuguese":true,"instructions":["**Execução**","**Posição inicial:**","- Tire a barra do suporte e segure-a acima da parte superior do peito com os braços totalmente estendidos.","- Mantenha as escápulas retraídas e pressionadas contra o banco.","**Fase de descida (excêntrica):**","- Leve a barra lentamente até pouco abaixo da clavícula ou da parte superior do peito.","- Mantenha o controle, sem quicar a barra.","**Fase de subida (concêntrica):**","- Empurre a barra para cima em linha reta até os braços ficarem totalmente estendidos.","- Concentre-se em contrair a parte superior do peito no alto.","**Travar e repetir:**","- Complete as repetições e encaixe a barra com segurança nos ganchos."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["chest"],"secondaryMuscles":[],"equipment":""},{"id":"wger-958","source":"https://wger.de/en/exercise/958/view/","name":"Rosca bíceps no TRX","portuguese":true,"instructions":["Segure as alças das fitas TRX, incline o corpo para trás com braços e pernas estendidos, mantendo o corpo em uma única linha reta. Este é um exercício de braços, não de abdômen."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["biceps"],"secondaryMuscles":[],"equipment":""},{"id":"wger-960","source":"https://wger.de/en/exercise/960/view/","name":"Balanço com kettlebell","portuguese":true,"instructions":["Embora o balanço com kettlebell seja um exercício de corpo inteiro, ele trabalha principalmente os músculos da cadeia posterior (parte de trás do corpo). Os principais músculos utilizados são os glúteos, os isquiotibiais, os eretores da espinha e os músculos da parte superior das costas."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["shoulders","glutes"],"secondaryMuscles":["quadriceps","abdominals"],"equipment":"kettlebells"},{"id":"wger-962","source":"https://wger.de/en/exercise/962/view/","name":"Elíptico","portuguese":true,"instructions":["Melhora o tônus muscular, fortalece os músculos das pernas (quadríceps, glúteos e panturrilhas), auxilia na vascularização e aumenta a resistência. O elíptico também é muito útil se o seu objetivo é perder peso."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["glutes","quadriceps"],"secondaryMuscles":["biceps","abdominals","triceps"],"equipment":""},{"id":"wger-974","source":"https://wger.de/en/exercise/974/view/","name":"Rosca com kettlebell (duas mãos)","portuguese":true,"instructions":["Fique em pé e segure o kettlebell com as duas mãos. Faça a flexão dos cotovelos partindo da extensão completa até a mão chegar na altura dos ombros. Afaste um pouco as pernas para se estabilizar e, para executar corretamente, procure não empurrar com as costas nem com o corpo de modo geral. Ajuste a carga do kettlebell para regular a dificuldade."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["biceps"],"secondaryMuscles":[],"equipment":"kettlebells"},{"id":"Box_Squat","source":"https://wger.de/en/exercise/977/view/","name":"Agachamento no caixote","portuguese":true,"instructions":["1. **Prepare o caixote:** Posicione o caixote atrás de você, a cerca de 90 cm do suporte de agachamento se estiver usando barra. Escolha uma altura que permita agachar e tocar levemente os glúteos no caixote com as costas retas.","2. **Fique em pé com a postura correta:** Fique em pé com os pés na largura dos ombros e as pontas dos pés levemente para fora. Contraia o abdômen e mantenha a coluna neutra. Se usar barra, apoie-a na altura dos ombros.","3. **Desça:** Sente para trás como se fosse sentar numa cadeira, dobrando os joelhos e baixando o quadril em direção ao caixote, com o abdômen firme e as costas retas durante todo o movimento.","4. **Descida controlada:** Desça de forma controlada até os glúteos tocarem suavemente o caixote, sem despencar.","5. **Pause e empurre para cima:** Faça uma breve pausa embaixo, com as costas retas e o abdômen contraído, e empurre com os calcanhares para voltar à posição inicial.","O exercício melhora coordenação, equilíbrio e resistência, tonifica a musculatura das pernas e dos glúteos e aumenta a densidade óssea de forma geral, reduzindo o risco de osteoporose."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}},{"id":"wger-978","source":"https://wger.de/en/exercise/978/view/","name":"Elevação de joelhos","portuguese":true,"instructions":["A elevação de pernas a 90° na barra é um exercício muito intenso, que envolve toda a musculatura abdominal."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["abdominals"],"secondaryMuscles":[],"equipment":"body only"},{"id":"wger-979","source":"https://wger.de/en/exercise/979/view/","name":"Elevação de pernas na barra fixa","portuguese":true,"instructions":["Com pegada firme nas duas mãos na barra, eleve as pernas estendidas até formar um ângulo de 90° com o tronco."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["abdominals"],"secondaryMuscles":["quadriceps"],"equipment":"body only"},{"id":"wger-981","source":"https://wger.de/en/exercise/981/view/","name":"Progressos","portuguese":true,"instructions":["1. Fique de pé de frente para uma cadeira","2. Suba na cadeira","3. Desça da cadeira","4. Repita"],"credit":{"author":"Vinicius Rodrigues (imported from Feeel), Eduardo Celino (imported from Feeel), Rodolfo Candido (imported from Feeel), gbpu (imported from Feeel), mondstern (imported from Feeel), flexagoon (imported from Feeel)","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["glutes","quadriceps"],"secondaryMuscles":["hamstrings","calves"],"equipment":""},{"id":"wger-983","source":"https://wger.de/en/exercise/983/view/","name":"Joelhos para cima","portuguese":true,"instructions":["1. Corra no lugar, colocando os joelhos o mais alto o confortável e trocando de pernas a um ritmo rápido"],"credit":{"author":"Vinicius Rodrigues (imported from Feeel), Eduardo Celino (imported from Feeel), Rodolfo Candido (imported from Feeel), gbpu (imported from Feeel), mondstern (imported from Feeel), flexagoon (imported from Feeel)","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":""},{"id":"wger-984","source":"https://wger.de/en/exercise/984/view/","name":"Investidas","portuguese":true,"instructions":["1. Fique de pé com as costas retas","2. Dê um grande passo adiante com sua perna esquerda","3. Desça com sua pélvis até quase tocar o chão com o seu joelho direito","4. Leve sua pélvis de volta para cima","5. Retorne para a posição de pé, dando um passo atrás","6. Repita, trocando de pernas a cada vez"],"credit":{"author":"Vinicius Rodrigues (imported from Feeel), Eduardo Celino (imported from Feeel), Rodolfo Candido (imported from Feeel), gbpu (imported from Feeel), mondstern (imported from Feeel), flexagoon (imported from Feeel)","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["glutes","quadriceps"],"secondaryMuscles":["hamstrings"],"equipment":""},{"id":"wger-985","source":"https://wger.de/en/exercise/985/view/","name":"Flexão em T","portuguese":true,"instructions":["1. Faça uma flexão de braços pradrão1.a Deite-se de barriga para baixo1.b Coloque suas mãos perto dos ouvidos1.c Use suas mão para levantar a barriga até que os braços estejam retos, mantendo as costas retas1.d Dobre os braços até que o peito quase toque o chão, certificando-se de que as costas estejam retas1.e Repita a partir do passo 1.c","2. Gire seu corpo para o lado para que as costas fiquem retas, de modo que a mão inferior que sustenta o corpo fique totalmente estendida, e apenas a mão inferior e o pé toquem o chão","3. Repita, mudando de lado no passo 2 cada vez"],"credit":{"author":"Vinicius Rodrigues (imported from Feeel), Eduardo Celino (imported from Feeel), Rodolfo Candido (imported from Feeel), gbpu (imported from Feeel), mondstern (imported from Feeel), flexagoon (imported from Feeel)","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["chest","triceps"],"secondaryMuscles":["shoulders"],"equipment":""},{"id":"wger-986","source":"https://wger.de/en/exercise/986/view/","name":"Side split squats esquerda","portuguese":true,"instructions":["1. Fique de pé e dê um passo lateral largo, apenas maior que a largura dos ombros.","2. Dobre um joelho até que sua coxa fique parelela ao chão. O joelho dobrado deve estar em linha com o pé.","3. Empurre de volta para a posição inicial e repita."],"credit":{"author":"Vinicius Rodrigues (imported from Feeel), Eduardo Celino (imported from Feeel), Rodolfo Candido (imported from Feeel), gbpu (imported from Feeel), mondstern (imported from Feeel), flexagoon (imported from Feeel)","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":""},{"id":"wger-987","source":"https://wger.de/en/exercise/987/view/","name":"Side split squats direita","portuguese":true,"instructions":["1. Fique de pé e dê um passo lateral largo, apenas maior que a largura dos ombros.","2. Dobre um joelho até que sua coxa fique parelela ao chão. O joelho dobrado deve estar em linha com o pé.","3. Empurre de volta para a posição inicial e repita."],"credit":{"author":"Vinicius Rodrigues (imported from Feeel), Eduardo Celino (imported from Feeel), Rodolfo Candido (imported from Feeel), gbpu (imported from Feeel), mondstern (imported from Feeel), flexagoon (imported from Feeel)","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":""},{"id":"wger-988","source":"https://wger.de/en/exercise/988/view/","name":"Bulgarian split squats esquerda","portuguese":true,"instructions":["1. Fique de pé em frente a uma cadeira e dê um grande passo. Coloque a parte superior de um de seus pés sobre a cadeira.","2. Dobre o joelho da frente, equilibrando-se com os braços até que o joelho de trás quase toque o chão","3. Empurre de volta para a posição inicial e repita."],"credit":{"author":"Vinicius Rodrigues (imported from Feeel), Eduardo Celino (imported from Feeel), Rodolfo Candido (imported from Feeel), gbpu (imported from Feeel), mondstern (imported from Feeel), flexagoon (imported from Feeel)","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["glutes","quadriceps"],"secondaryMuscles":["hamstrings"],"equipment":""},{"id":"wger-989","source":"https://wger.de/en/exercise/989/view/","name":"Bulgarian split squats direita","portuguese":true,"instructions":["1. Fique de pé em frente a uma cadeira e dê um grande passo. Coloque a parte superior de um de seus pés sobre a cadeira.","2. Dobre o joelho da frente, equilibrando-se com os braços até que o joelho de trás quase toque o chão","3. Empurre de volta para a posição inicial e repita."],"credit":{"author":"Vinicius Rodrigues (imported from Feeel), Eduardo Celino (imported from Feeel), Rodolfo Candido (imported from Feeel), gbpu (imported from Feeel), mondstern (imported from Feeel), flexagoon (imported from Feeel)","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["glutes","quadriceps"],"secondaryMuscles":["hamstrings"],"equipment":""},{"id":"wger-990","source":"https://wger.de/en/exercise/990/view/","name":"Coice","portuguese":true,"instructions":["1. Fique em posição de quatro.","2. Empurre um pé para trás até que esteja totalmente estendido, concentrando-se nos músculos dos glúteos.","3. Fique por um segundo depois retorne à posição inicial.","4. Repita, alternando os pés"],"credit":{"author":"Vinicius Rodrigues (imported from Feeel), Eduardo Celino (imported from Feeel), Rodolfo Candido (imported from Feeel), gbpu (imported from Feeel), mondstern (imported from Feeel), flexagoon (imported from Feeel)","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["glutes"],"secondaryMuscles":["hamstrings"],"equipment":""},{"id":"wger-991","source":"https://wger.de/en/exercise/991/view/","name":"Split squats esquerda","portuguese":true,"instructions":["1. Fique de pé com as costas retas","2. Dê um grande passo para frente com sua perna esquerda","3. Leve sua pélvis para baixo até quase tocar o chão com seu joelho direito","4. Leve sua pélvis de volta para cima","5. Repita a partir do passo 3."],"credit":{"author":"Vinicius Rodrigues (imported from Feeel), Eduardo Celino (imported from Feeel), Rodolfo Candido (imported from Feeel), gbpu (imported from Feeel), mondstern (imported from Feeel), flexagoon (imported from Feeel)","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["glutes","quadriceps"],"secondaryMuscles":["hamstrings"],"equipment":""},{"id":"wger-992","source":"https://wger.de/en/exercise/992/view/","name":"Split squats direita","portuguese":true,"instructions":["1. Fique de pé com as costas retas","2. Dê um grande passo para frente com sua perna esquerda","3. Leve sua pélvis para baixo até quase tocar o chão com seu joelho direito","4. Leve sua pélvis de volta para cima","5. Repita a partir do passo 3."],"credit":{"author":"Vinicius Rodrigues (imported from Feeel), Eduardo Celino (imported from Feeel), Rodolfo Candido (imported from Feeel), gbpu (imported from Feeel), mondstern (imported from Feeel), flexagoon (imported from Feeel)","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["glutes","quadriceps"],"secondaryMuscles":["hamstrings"],"equipment":""},{"id":"wger-993","source":"https://wger.de/en/exercise/993/view/","name":"Corda de Salto: saltos básicos","portuguese":true,"instructions":["Este exercício requer uma corda de salto. Certifique-se de que o comprimento da corda é ajustado à sua altura. Uma maneira de verificar é agarrar ambas as pegas com uma mão e ficar no meio da corda pendurada no chão com um pé. Se a corda (excluindo as pegas) chegar mesmo abaixo do seu peito, o seu comprimento é o correcto. Uma corda mais curta seria perigosa, pois poderia atingir-se a si próprio, e uma corda mais comprida seria uma má forma.","1. Coloque os pés juntos, dobre um pouco os joelhos, mantenha a cabeça e o corpo direitos, mantenha os cotovelos para dentro, abra os braços.","2. Rodar apenas os pulsos com força suficiente para fazer girar a corda.","3. Saltem só com força suficiente para passar a corda por baixo dos pés.","4. Repita a partir do passo 2."],"credit":{"author":"Vinicius Rodrigues (imported from Feeel), Eduardo Celino (imported from Feeel), Rodolfo Candido (imported from Feeel), gbpu (imported from Feeel), mondstern (imported from Feeel), flexagoon (imported from Feeel)","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":""},{"id":"wger-994","source":"https://wger.de/en/exercise/994/view/","name":"Círculos com o braço pra frente","portuguese":true,"instructions":["1. Fique em pé com as costas retas.","2. Mantendo os braços esticados, traga-os à sua frente, mova-os para baixo, atrás das costas, depois sobre a cabeça e de volta à posição inicial.","3. Continue circulando seus braços conforme descrito na etapa 2."],"credit":{"author":"Vinicius Rodrigues (imported from Feeel), Eduardo Celino (imported from Feeel), Rodolfo Candido (imported from Feeel), gbpu (imported from Feeel), mondstern (imported from Feeel), flexagoon (imported from Feeel)","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":""},{"id":"wger-995","source":"https://wger.de/en/exercise/995/view/","name":"Círculos com o braço pra trás","portuguese":true,"instructions":["1. Fique em pé com as costas retas.","2. Mantendo os braços esticados, leve-os à sua frente, levante-os acima da cabeça e, a seguir, continue o movimento atrás das costas e desça até a posição inicial.","3. Continue circulando seus braços conforme descrito na etapa 2."],"credit":{"author":"Vinicius Rodrigues (imported from Feeel), Eduardo Celino (imported from Feeel), Rodolfo Candido (imported from Feeel), gbpu (imported from Feeel), mondstern (imported from Feeel), flexagoon (imported from Feeel)","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":""},{"id":"Mountain_Climbers","source":"https://wger.de/en/exercise/996/view/","name":"Montanhistas","portuguese":true,"instructions":["Posição inicial:","Começar na posição vertical de flexão, ou na prancha alta.As mãos devem estar diretamente abaixo dos seus ombros.Manter a cabeça alinhada com as costas, virada para o chão.Os pés devem ter a distância entre os quadris.","Passos:","1. Mova um joelho em direção ao centro do corpo, em direção aos cotovelos, mantendo a outra perna estendida.","2. Num movimento de salto rápido, endireite a perna dobrada para fora e puxe o outro joelho em direção ao seu corpo.","3. Continue a repetir o passo 2, alternando as pernas.","Notas:","Ao longo do exercício, as costas devem permanecer o mais reto o possível - evite uma corcunda ou uma curvatura nas costas."],"credit":{"author":"Vinicius Rodrigues (imported from Feeel), Eduardo Celino (imported from Feeel), Rodolfo Candido (imported from Feeel), gbpu (imported from Feeel), mondstern (imported from Feeel), flexagoon (imported from Feeel)","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}},{"id":"wger-997","source":"https://wger.de/en/exercise/997/view/","name":"Burpee sem flexão","portuguese":true,"instructions":["Posição inicial:","Fique de pé reto, com os pés afastados alinhados ao quadris.","Passos:","1. Se agache e se apoie com as mãos no chão entre os joelhos e a frente de seus pés, mantendo as costas retas.","2. Mantendo as mãos no chão, pule jogando as pernas para trás para a posição de prancha altas","3. Pule os pés para frente para voltar à posição de agachamento.","4. Repita."],"credit":{"author":"Vinicius Rodrigues (imported from Feeel), Eduardo Celino (imported from Feeel), Rodolfo Candido (imported from Feeel), gbpu (imported from Feeel), mondstern (imported from Feeel), flexagoon (imported from Feeel)","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":""},{"id":"wger-998","source":"https://wger.de/en/exercise/998/view/","name":"Burpee sem flexão","portuguese":true,"instructions":["Posição inicial:","Fique de pé reto, com os pés afastados alinhados ao quadris.","Passos:","1. Se agache e se apoie com as mãos no chão entre os joelhos e a frente de seus pés, mantendo as costas retas.","2. Mantendo as mãos no chão, pule jogando as pernas para trás para a posição de prancha altas.","3. Pule os pés para frente para voltar à posição de agachamento.","4. Salte.","5. Repita."],"credit":{"author":"Vinicius Rodrigues (imported from Feeel), Eduardo Celino (imported from Feeel), Rodolfo Candido (imported from Feeel), gbpu (imported from Feeel), mondstern (imported from Feeel), flexagoon (imported from Feeel)","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":""},{"id":"wger-999","source":"https://wger.de/en/exercise/999/view/","name":"Lunge reverso","portuguese":true,"instructions":["Posição inicial:","Fique de pé reto, com os pés afastados.","Passos:","1. Dê um passo para trás com uma perna para que você possa dobrar-se confortavelmente a um ângulo de 90 graus.","2. Dobre lentamente ambos os joelhos para formar ângulos de 90 graus.","3. Retorne para a posição inicial.","4. Repita, alternando as pernas."],"credit":{"author":"Vinicius Rodrigues (imported from Feeel), Eduardo Celino (imported from Feeel), Rodolfo Candido (imported from Feeel), gbpu (imported from Feeel), mondstern (imported from Feeel), flexagoon (imported from Feeel)","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["glutes","quadriceps"],"secondaryMuscles":["hamstrings"],"equipment":""},{"id":"wger-1000","source":"https://wger.de/en/exercise/1000/view/","name":"Mergulho em solo","portuguese":true,"instructions":["Posição inicial:","Sente-se com seus braços atrás de você, apoiando suas costas.Seus dedos devem apontar para frente.Seus joelhos devem estar dobrados, com os pés juntos.","Passos:","1. Levante seus quadris do chão, endireitando seus braços.","2. Dobre os cotovelos, abaixando os quadris.","3. Endireite os braços, voltando à posição anterior.","4. Repita os passos 2 e 3.","Notas:","A dificuldade do exercício depende do quanto você eleva seus quadris."],"credit":{"author":"Vinicius Rodrigues (imported from Feeel), Eduardo Celino (imported from Feeel), Rodolfo Candido (imported from Feeel), gbpu (imported from Feeel), mondstern (imported from Feeel), flexagoon (imported from Feeel)","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["triceps"],"secondaryMuscles":["shoulders","chest"],"equipment":""},{"id":"wger-1001","source":"https://wger.de/en/exercise/1001/view/","name":"Prancha alta","portuguese":true,"instructions":["Posição inicial:","Entre na posição de prancha alta:as mãos e os dedos dos pés devem tocar o chão, as costas, os braços e as pernas devem estar retos.Para chegar a essa posição, você pode deitar de bruços, colocar as mãos voltadas para baixo ao lado da cabeça e levantar os braços até que estejam retos.","Passos:","1. Mantenha a posição inicial durante todo o exercício."],"credit":{"author":"Vinicius Rodrigues (imported from Feeel), Eduardo Celino (imported from Feeel), Rodolfo Candido (imported from Feeel), gbpu (imported from Feeel), mondstern (imported from Feeel), flexagoon (imported from Feeel)","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["abdominals"],"secondaryMuscles":["shoulders","triceps"],"equipment":""},{"id":"Childs_Pose","source":"https://wger.de/en/exercise/1002/view/","name":"Postura da criança (Balsana)","portuguese":true,"instructions":["Posição inicial:","Comece de quatro, joelhos, dedos dos pés e mãos tocando o chão. Seus dois dedões dos pés devem estar se tocando.","Passos:","1. Mova os joelhos para que fiquem aproximadamente na largura do quadril.","2. Ao expirar, mova a pélvis para trás para se sentar sobre os calcanhares. Suas mãos ainda devem estar tocando o chão.","3. Relaxe a parte superior do corpo, abaixando a testa até o chão e deixando as mãos avançarem naturalmente.","4. Permaneça nesta postura.","Dicas:","* Para sair da postura, passe os braços para trás sob os ombros e mova a parte superior do corpo para cima, para uma posição sentada."],"credit":{"author":"Vinicius Rodrigues (imported from Feeel), Eduardo Celino (imported from Feeel), Rodolfo Candido (imported from Feeel), gbpu (imported from Feeel), mondstern (imported from Feeel), flexagoon (imported from Feeel)","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}},{"id":"wger-1003","source":"https://wger.de/en/exercise/1003/view/","name":"Levantamento terra com Kettlebell","portuguese":true,"instructions":["Posição inicial:","Fique em pé na largura do quadril, com o kettlebell centralizado entre os tornozelos. Suas costas devem estar retas, sua cabeça voltada para a frente.","Passos:","1. Dobre os quadris e dobre levemente os joelhos para colocar as mãos nas alças do kettlebell. Suas costas devem estar retas enquanto você executa o movimento.","2. Agarre as alças do kettlebell, com as mãos empurrando em direções opostas, como se fosse separar a alça.","3. Enquanto faz contato com seus abdominais e glúteos, fique em pé.","4. Dobre os quadris novamente para trazer o kettlebell de volta para baixo, semelhante ao passo 1.","5. Repita a partir da etapa 3.","Dicas:","* Certifique-se de realizar os movimentos corretamente, pois fazer o contrário pode causar lesões. Por exemplo, não se agache em vez de dobrar os quadris, não arredonde as costas ao alcançar o kettlebell e não se incline para trás ao se levantar."],"credit":{"author":"Vinicius Rodrigues (imported from Feeel), Eduardo Celino (imported from Feeel), Rodolfo Candido (imported from Feeel), gbpu (imported from Feeel), mondstern (imported from Feeel), flexagoon (imported from Feeel)","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["hamstrings","glutes"],"secondaryMuscles":["quadriceps"],"equipment":"kettlebells"},{"id":"wger-1004","source":"https://wger.de/en/exercise/1004/view/","name":"Rotação do ombro para frente","portuguese":true,"instructions":["Posicão inicial:","Sente-se ou fique de pé com as costas retas.","Passos:","1. Coloque as mãos nos ombros.","2. Gire repetidamente ambas as articulações dos ombros em um movimento circular em um ritmo moderado."],"credit":{"author":"Vinicius Rodrigues (imported from Feeel), Eduardo Celino (imported from Feeel), Rodolfo Candido (imported from Feeel), gbpu (imported from Feeel), mondstern (imported from Feeel), flexagoon (imported from Feeel)","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":""},{"id":"wger-1005","source":"https://wger.de/en/exercise/1005/view/","name":"Rotação do ombro para trás","portuguese":true,"instructions":["Posicão inicial:","Sente-se ou fique de pé com as costas retas.","Passos:","1. Coloque as mãos nos ombros.","2. Gire repetidamente ambas as articulações dos ombros em um movimento circular em um ritmo moderado."],"credit":{"author":"Vinicius Rodrigues (imported from Feeel), Eduardo Celino (imported from Feeel), Rodolfo Candido (imported from Feeel), gbpu (imported from Feeel), mondstern (imported from Feeel), flexagoon (imported from Feeel)","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":""},{"id":"wger-1006","source":"https://wger.de/en/exercise/1006/view/","name":"Flexão de queixo","portuguese":true,"instructions":["Posicão inicial:","Sente-se ou fique de pé com as costas retas.","Passos:","1. Coloque os dedos no queixo para incliná-lo para dentro lentamente, movendo a cabeça para trás para alinhá-la com a coluna.","2. Segure por 5 segundos.","3. Volte à posição normal da cabeça e repita."],"credit":{"author":"Vinicius Rodrigues (imported from Feeel), Eduardo Celino (imported from Feeel), Rodolfo Candido (imported from Feeel), gbpu (imported from Feeel), mondstern (imported from Feeel), flexagoon (imported from Feeel)","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":""},{"id":"wger-1007","source":"https://wger.de/en/exercise/1007/view/","name":"Virar a cabeça","portuguese":true,"instructions":["Posição inicial:","Sente-se ou fique em pé com as costas retas e com os ombros para baixo.","Passos:","1. Sente-se ou levante-se ereto, ombros caídos.","2. Vire a cabeça para o lado o máximo possível. Pare quando você atingir um limite e segure por 5 segundos.","3. Retorne à posição central e repita, mudando de lado."],"credit":{"author":"Vinicius Rodrigues (imported from Feeel), Eduardo Celino (imported from Feeel), Rodolfo Candido (imported from Feeel), gbpu (imported from Feeel), mondstern (imported from Feeel), flexagoon (imported from Feeel)","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":""},{"id":"wger-1008","source":"https://wger.de/en/exercise/1008/view/","name":"Alongamento de pescoço para esquerda","portuguese":true,"instructions":["Posição inicial:","Sente-se ou fique em pé com as costas retas.","Passos:","1. Incline a cabeça para o lado e segure por 8 segundos para alongar a lateral do pescoço.","2. Com a mão mais próxima no topo da cabeça, puxe suavemente para alongar ainda mais. Segure por 8 segundos.","3. Vire o queixo para o ombro. Segure por 8 segundos.","4. Solte e retorne à posição inicial."],"credit":{"author":"Vinicius Rodrigues (imported from Feeel), Eduardo Celino (imported from Feeel), Rodolfo Candido (imported from Feeel), gbpu (imported from Feeel), mondstern (imported from Feeel), flexagoon (imported from Feeel)","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":""},{"id":"wger-1009","source":"https://wger.de/en/exercise/1009/view/","name":"Alongamento de pescoço para direita","portuguese":true,"instructions":["Posição inicial:","Sente-se ou fique em pé com as costas retas.","Passos:","1. Incline a cabeça para o lado e segure por 8 segundos para alongar a lateral do pescoço.","2. Com a mão mais próxima no topo da cabeça, puxe suavemente para alongar ainda mais. Segure por 8 segundos.","3. Vire o queixo para o ombro. Segure por 8 segundos.","4. Solte e retorne à posição inicial."],"credit":{"author":"Vinicius Rodrigues (imported from Feeel), Eduardo Celino (imported from Feeel), Rodolfo Candido (imported from Feeel), gbpu (imported from Feeel), mondstern (imported from Feeel), flexagoon (imported from Feeel)","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":""},{"id":"wger-1010","source":"https://wger.de/en/exercise/1010/view/","name":"Alongamento de pescoço","portuguese":true,"instructions":["Posição inicial:","Sente-se ereto em uma cadeira ou em um travesseiro firme.","Passos:","1. Expire e incline a cabeça para frente, queixo no peito, colocando as mãos atrás da cabeça.","2. Use as mãos para puxar a cabeça levemente para baixo. Segure por 5 segundos.","3. Puxe os ombros para trás e para baixo usando os músculos das costas. Isso deve aumentar o alongamento do pescoço. Segure por 5 segundos.","4. Agora empurre suavemente a cabeça para cima, enquanto também a puxa para baixo com as mãos. Equilibre as duas forças para que sua cabeça não se mova. Segure por pelo menos 5 segundos.","5. Leve os dedos à testa e use-os para mover suavemente a cabeça de volta à posição original."],"credit":{"author":"Vinicius Rodrigues (imported from Feeel), Eduardo Celino (imported from Feeel), Rodolfo Candido (imported from Feeel), gbpu (imported from Feeel), mondstern (imported from Feeel), flexagoon (imported from Feeel)","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":""},{"id":"wger-1011","source":"https://wger.de/en/exercise/1011/view/","name":"Alongamento frontal do pescoço","portuguese":true,"instructions":["Posição inicial:","Sente-se ou fique em pé com as costas retas.","Passos:","1. Abra bem a boca.","2. Incline lentamente a cabeça para trás com a boca aberta. Se sentir necessidade de apoio, junte as mãos atrás da cabeça.","3. Feche e abra a boca muito lentamente.","4. Ao final, retorne lentamente à posição inicial e feche a boca."],"credit":{"author":"Vinicius Rodrigues (imported from Feeel), Eduardo Celino (imported from Feeel), Rodolfo Candido (imported from Feeel), gbpu (imported from Feeel), mondstern (imported from Feeel), flexagoon (imported from Feeel)","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":""},{"id":"wger-1012","source":"https://wger.de/en/exercise/1012/view/","name":"Rosca alternada","portuguese":true,"instructions":["**Posição inicial:** Comece em pé, com um halter em cada mão, as costas retas e os pés na largura do quadril. Os braços devem estar relaxados, apontando para baixo, os joelhos levemente flexionados, o abdômen contraído e os ombros abaixados.","**Execução:**","1. Flexione um dos braços no cotovelo, levando o halter até o ombro, mantendo o braço superior imóvel durante o movimento.","2. Desça o halter até o braço voltar à posição relaxada inicial.","3. Repita, alternando os braços."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["biceps"],"secondaryMuscles":[],"equipment":"dumbbell"},{"id":"wger-1013","source":"https://wger.de/en/exercise/1013/view/","name":"Alongamento do elevador da escápula esquerdo","portuguese":true,"instructions":["**Posição inicial:** Comece em pé ou sentado. Vire a cabeça para a esquerda, cerca de 45 graus, na direção de um ponto logo acima do mamilo. Coloque a mão direita atrás das costas ou sente-se sobre ela. Com a mão esquerda, segure a parte de trás da cabeça. Incline levemente a cabeça para baixo.","**Execução:**","1. Depois de assumir a posição inicial, pressione a cabeça contra a mão esquerda com força leve; a mão deve pressionar de volta com a mesma força, para que a cabeça não se mova. Mantenha essa posição."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":""},{"id":"wger-1015","source":"https://wger.de/en/exercise/1015/view/","name":"Círculos de pescoço no sentido horário","portuguese":true,"instructions":["**Posição inicial:** Comece sentado ou em pé. Deixe a cabeça cair para baixo, levando o queixo em direção ao peito, sem forçar.","**Execução:**","Em um movimento mais lento e fluido, com a cabeça relaxada e sem empurrar em nenhuma direção:","1. Incline a cabeça em direção ao ombro direito.","2. Depois leve a cabeça para trás, olhando para cima.","3. Depois incline em direção ao ombro esquerdo.","4. E retorne à posição inicial.","Continue repetindo isso como parte de um único movimento lento e fluido."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":""},{"id":"wger-1016","source":"https://wger.de/en/exercise/1016/view/","name":"Círculos de pescoço no sentido anti-horário (var.)","portuguese":true,"instructions":["**Posição inicial:** Comece sentado ou em pé. Deixe a cabeça cair para baixo, levando o queixo em direção ao peito, sem forçar.","**Execução:**","Em um movimento mais lento e fluido, com a cabeça relaxada e sem empurrar em nenhuma direção:","1. Incline a cabeça em direção ao ombro esquerdo.","2. Depois leve a cabeça para trás, olhando para cima.","3. Depois incline em direção ao ombro direito.","4. E retorne à posição inicial.","Continue repetindo isso como parte de um único movimento lento e fluido."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":""},{"id":"wger-1018","source":"https://wger.de/en/exercise/1018/view/","name":"Inclinação lateral de cabeça","portuguese":true,"instructions":["**Posição inicial:** Sente-se ou fique em pé com as costas retas.","**Execução:**","1. Incline a cabeça para um lado e segure por um instante.","2. Volte a cabeça à posição neutra e segure por um instante.","3. Incline a cabeça para o outro lado e segure por um instante.","4. Volte novamente à posição neutra e segure por um instante.","5. Repita."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":""},{"id":"wger-1019","source":"https://wger.de/en/exercise/1019/view/","name":"Prancha lateral direita","portuguese":true,"instructions":["1. Deite-se de lado, com o cotovelo inferior em ângulo reto, com o braço para fora","2. Levante sua pélvis do chão levantando o ombro inferior para cima, mantendo o antebraço no chão; sua cabeça, pélvis e pés devem estar em linha reta","3. Mantenha esta posição"],"credit":{"author":"Vinicius Rodrigues (imported from Feeel), Eduardo Celino (imported from Feeel), Rodolfo Candido (imported from Feeel), gbpu (imported from Feeel), mondstern (imported from Feeel), flexagoon (imported from Feeel)","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["abdominals"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1020","source":"https://wger.de/en/exercise/1020/view/","name":"Pistol squats direita","portuguese":true,"instructions":["1. Fique de pé em uma perna, com a outra perna reta e ligeiramente para frente.","2. Dobre um joelho lentamente, descendo para um agachamento e mantendo as costas e a outra perna reta.","3. Levante-se lentamente do agachamento, endireitando o joelho dobrado e mantendo a outra perna reta.","4. Repita"],"credit":{"author":"Vinicius Rodrigues (imported from Feeel), Eduardo Celino (imported from Feeel), Rodolfo Candido (imported from Feeel), gbpu (imported from Feeel), mondstern (imported from Feeel), flexagoon (imported from Feeel)","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["glutes","quadriceps"],"secondaryMuscles":["hamstrings","calves","abdominals"],"equipment":""},{"id":"wger-1021","source":"https://wger.de/en/exercise/1021/view/","name":"Elevação da panturrilha direita","portuguese":true,"instructions":["1. Fique de pé no chão ou na borda de um degrau para aumentar o alcance do movimento. Levante um pé, colocando a parte superior sobre sua panturrilha.","2. Levante os calcanhares até ficar de pé sobre os dedos do pé.","3. Fique nesta posição por três segundos, depois abaixe o pé sem tocar o chão com seu calcanhar."],"credit":{"author":"Vinicius Rodrigues (imported from Feeel), Eduardo Celino (imported from Feeel), Rodolfo Candido (imported from Feeel), gbpu (imported from Feeel), mondstern (imported from Feeel), flexagoon (imported from Feeel)","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["calves"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1027","source":"https://wger.de/en/exercise/1027/view/","name":"Alongamento de prece com apoio elevado","portuguese":true,"instructions":["**Posição inicial:** Ajoelhe-se de frente para um banco, a uma distância suficiente para que o tronco caiba entre os joelhos e o banco. Com as costas retas, apoie os cotovelos no banco, com as palmas juntas e as mãos apontando para cima.","**Execução:**","1. Expirando, alongue o peito para baixo em direção ao chão sem mover a lombar. Ao mesmo tempo, leve as mãos em direção aos ombros, mantendo as palmas juntas e os cotovelos no banco.","2. Segure por alguns segundos.","3. Inspirando, relaxe as costas para voltar à posição inicial.","4. Repita."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["lats"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1080","source":"https://wger.de/en/exercise/1080/view/","name":"Flexão hindu","portuguese":true,"instructions":["Exercício para fortalecer ombros e peitorais. O nome vem de ele começar na posição de yoga Cachorro Olhando para Baixo, passar para a Cobra sem apoiar as pernas ou o tronco no chão e terminar com uma flexão normal. O exercício também pode ser executado no sentido inverso (voltando à posição inicial). Como variação, após fazer a flexão, o quadril pode ser elevado para retornar ao Cachorro Olhando para Baixo."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["shoulders","chest"],"secondaryMuscles":["triceps"],"equipment":""},{"id":"wger-1082","source":"https://wger.de/en/exercise/1082/view/","name":"Remada curvada com rotação externa","portuguese":true,"instructions":["**Posição inicial:** Fique atrás de uma cadeira ou na frente de uma mesa. Incline o tronco pela cintura para apoiar a testa no encosto da cadeira ou na mesa, mantendo as costas retas. Os braços devem ficar pendurados, apontando para o chão.","**Execução:**","1. Leve os cotovelos até a altura dos ombros, com os antebraços apontando para baixo, perpendiculares aos bíceps. Os bíceps devem ficar na mesma altura das costas e perpendiculares à coluna.","2. Segure por um instante.","3. Gire nos cotovelos para levar as mãos o mais alto que conseguir.","4. Segure por um instante.","5. Gire nos cotovelos de volta à posição anterior.","6. Desça os braços até a posição original.","7. Repita."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":""},{"id":"Dumbbell_Floor_Press","source":"https://wger.de/en/exercise/1084/view/","name":"Supino no chão com halteres","portuguese":true,"instructions":["Pegue os halteres e deite-se de costas, com os joelhos flexionados e os pés apoiados no chão (use um banco, se tiver). Empurre os pesos para cima, estendendo os cotovelos. Desça-os lentamente até os braços ficarem apoiados no chão, próximos ao corpo. Faça uma pausa nessa posição e só então empurre de volta de forma explosiva. Contraia bem o peitoral e repita."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}},{"id":"wger-1086","source":"https://wger.de/en/exercise/1086/view/","name":"Flexão com pegada fechada","portuguese":true,"instructions":["Entre numa posição de prancha firme, aproximando as mãos até quase se tocarem. Flexione os cotovelos para levar o peito ao chão lentamente. Mantenha os cotovelos próximos ao corpo enquanto empurra de volta de forma explosiva. Repita. Certifique-se de descer devagar em cada repetição, mantendo a técnica impecável."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["lats","chest"],"secondaryMuscles":["shoulders","biceps","triceps"],"equipment":""},{"id":"wger-1087","source":"https://wger.de/en/exercise/1087/view/","name":"Power clean com halteres a partir da coxa","portuguese":true,"instructions":["Em pé, fique ereto com os halteres ao lado do corpo. Faça a dobradiça no quadril para baixá-los até os joelhos. Suba de volta com um pequeno salto, aproveitando o impulso para puxar os halteres até os ombros. Fique em pé ereto e desça com controle até os lados do corpo, repetindo. Mantenha o movimento rápido e explosivo; se a sua frequência cardíaca não disparar, a execução está errada."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["hamstrings","glutes"],"secondaryMuscles":["calves","quadriceps"],"equipment":"dumbbell"},{"id":"wger-1088","source":"https://wger.de/en/exercise/1088/view/","name":"Terra sumô com halteres","portuguese":true,"instructions":["Baixe o halter até o chão entre as pernas. Adote uma base bem aberta e desça mantendo as costas retas. Com o halter apoiado em pé, segure-o pelo topo da “cabeça” (figura 1). Mantendo o peito erguido e o core firme, empurre o chão e suba de volta até ficar em pé (figura 2). Repita. Se você consegue fazer 20 a 30 repetições com facilidade, use dois halteres."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["hamstrings","glutes"],"secondaryMuscles":["quadriceps"],"equipment":"dumbbell"},{"id":"wger-1092","source":"https://wger.de/en/exercise/1092/view/","name":"Treino com saco de pancadas","portuguese":true,"instructions":["O treino com saco de pancadas melhora a definição muscular dos deltoides, dos deltoides posteriores, do tríceps e do bíceps, além de ser um ótimo exercício cardiovascular."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["shoulders","chest"],"secondaryMuscles":["biceps","hamstrings","calves","lats","abdominals"],"equipment":""},{"id":"wger-1096","source":"https://wger.de/en/exercise/1096/view/","name":"Abdução em pé","portuguese":true,"instructions":["Treinar uma base estável, predominantemente sobre uma perna, é fundamental para os dois lados. Por um lado, evita desconforto; por outro, estabelece uma base firme. O praticante assume a posição em pé habitual e, com o tronco estável, tenta elevar repetidamente a perna sem carga, dobrando-a no quadril e no joelho, e depois abaixá-la novamente. O movimento também é repetido do outro lado. O exercício treina a estabilidade dos músculos que envolvem o quadril."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":""},{"id":"wger-1099","source":"https://wger.de/en/exercise/1099/view/","name":"Sustentação lateral com kettlebell","portuguese":true,"instructions":["Enrole um elástico em um kettlebell e levante o kettlebell pelo elástico. Deixe-o pendurado ao lado do corpo e fique em pé sobre uma perna, trocando de perna sem soltar a carga. Repita com a outra mão."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":["abdominals"],"equipment":"kettlebells"},{"id":"wger-1101","source":"https://wger.de/en/exercise/1101/view/","name":"Isometria de barra fixa","portuguese":true,"instructions":["Execute uma barra fixa isométrica cronometrada: suba e mantenha o queixo na altura da barra ou acima dela durante o tempo determinado."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["lats","chest"],"secondaryMuscles":["shoulders","biceps"],"equipment":"body only"},{"id":"wger-1102","source":"https://wger.de/en/exercise/1102/view/","name":"Afundo alternado para trás","portuguese":true,"instructions":["Os músculos posteriores dos glúteos, os isquiotibiais, o sóleo e o gastrocnêmio são mais trabalhados."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["glutes","quadriceps"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1109","source":"https://wger.de/en/exercise/1109/view/","name":"Rosca concentrada na polia","portuguese":true,"instructions":["A rosca concentrada é um exercício clássico para construir o bíceps com um braço de cada vez. Pode ser feita curvado para a frente ou ajoelhado, mas costuma ser realizada com mais frequência sentado em um banco. É ótima para enfatizar o pico do bíceps e costuma ser usada para finalizar o treino de bíceps."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["biceps"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1111","source":"https://wger.de/en/exercise/1111/view/","name":"Flexão inclinada","portuguese":true,"instructions":["Flexão de braço comum, executada com inclinação de 30 graus."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["chest"],"secondaryMuscles":["triceps"],"equipment":""},{"id":"wger-1112","source":"https://wger.de/en/exercise/1112/view/","name":"Flexão Declinada","portuguese":true,"instructions":["Com os pés elevados cerca de 30 cm em uma plataforma, alinhe ombros, cotovelos e mãos e faça flexões tradicionais. Isso enfatiza as fibras claviculares do peitoral maior."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"equipment":""},{"id":"wger-1115","source":"https://wger.de/en/exercise/1115/view/","name":"Afundo 3D de aquecimento","portuguese":true,"instructions":["Como aquecimento, use halteres leves, um em cada mão. Faça afundos alternando as direções: para a frente, para o lado, para trás e em ângulos de 45 graus."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":"dumbbell"},{"id":"wger-1116","source":"https://wger.de/en/exercise/1116/view/","name":"Caminhada do fazendeiro com halteres","portuguese":true,"instructions":["Pegue metade do seu peso corporal em cada mão e caminhe."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":"dumbbell"},{"id":"wger-1125","source":"https://wger.de/en/exercise/1125/view/","name":"Puxada alta aberta supinada","portuguese":true,"instructions":["**Movimento descendente:**","- Puxe a barra para baixo para que ela passe perto do queixo e toque a parte superior do peito.","- Mantenha o resto do corpo imóvel."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["lats"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1127","source":"https://wger.de/en/exercise/1127/view/","name":"Puxada alta fechada supinada","portuguese":true,"instructions":["**Movimento descendente:**","- Puxe a barra para baixo para que ela passe perto do queixo e toque a parte superior do peito.","- Mantenha o resto do corpo imóvel."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["lats"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1131","source":"https://wger.de/en/exercise/1131/view/","name":"Extensão de glúteo na polia","portuguese":true,"instructions":["Esta atividade permite exercitar a região do glúteo superior ou máximo. Por isso, ela não pode faltar na sua rotina de exercícios isolados para glúteos.","Posicione-se em frente a uma máquina de polia e localize o gancho inferior. Em seguida, prenda-o na tornozeleira para trabalhar na polia baixa. Quanto à postura, mantenha-se ereto o tempo todo. Preste atenção especial às costas para mantê-las retas e não se machucar.","É recomendável segurar-se na máquina para ter mais equilíbrio. Com a perna que sustenta a carga da polia, faça uma extensão lenta para trás sem flexionar o joelho."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["glutes"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1132","source":"https://wger.de/en/exercise/1132/view/","name":"Extensão de glúteo na máquina","portuguese":true,"instructions":["Um exercício de extensão de quadril no aparelho GHD é um dos melhores exercícios para glúteos. Apesar de o foco principal serem os glúteos, ele também é excelente para a região lombar, as panturrilhas e os isquiotibiais."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["glutes"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1136","source":"https://wger.de/en/exercise/1136/view/","name":"Puxada alta com pegada neutra","portuguese":true,"instructions":["A puxada alta é um exercício importante para fortalecer as costas e melhorar a postura, o que pode contribuir para uma vida mais saudável. Para executar o exercício corretamente e evitar lesões, siga alguns passos-chave:","1. Posicione-se em frente à máquina de polias com os joelhos levemente flexionados e os pés no chão.","2. Segure o puxador com as palmas voltadas uma para a outra e as mãos afastadas na largura dos ombros.","3. Puxe o puxador para baixo até encostar ou chegar perto do peito, mantendo a posição por um ou dois segundos.","4. Retorne o puxador lentamente à posição inicial, mantendo os braços e as mãos estendidos e as costas retas durante todo o movimento."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["biceps","lats"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1138","source":"https://wger.de/en/exercise/1138/view/","name":"Puxada alta no banco inclinado","portuguese":true,"instructions":["Sobre o banco inclinado em frente à máquina de polia, com o corpo de bruços sobre o banco, executa-se a puxada."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["lats"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1141","source":"https://wger.de/en/exercise/1141/view/","name":"Arabesque unilateral","portuguese":true,"instructions":["Coloque todo o peso sobre uma perna e mantenha essa posição, deixando quadris e pelve nivelados o tempo todo. Com as costas na posição neutra, incline-se para a frente jogando a perna livre para trás e, depois, use os glúteos para retornar lentamente à posição neutra."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["hamstrings","glutes"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1143","source":"https://wger.de/en/exercise/1143/view/","name":"Extensão de coluna na máquina","portuguese":true,"instructions":["Na máquina de extensão, com as costas apoiadas e carga, flexione o tronco para a frente e estenda-o de volta à posição neutra, controlando o movimento em todo o percurso."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["lats"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1188","source":"https://wger.de/en/exercise/1188/view/","name":"Flexão lateral de tronco","portuguese":true,"instructions":["Com um halter em uma das mãos, estendemos o braço para baixo e flexionamos o outro braço, apoiando a mão na cabeça. Em seguida, levamos a mão que segura a carga para cima e para baixo, inclinando o tronco."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":["abdominals"],"equipment":"dumbbell"},{"id":"wger-1192","source":"https://wger.de/en/exercise/1192/view/","name":"Rosca alternada com halteres","portuguese":true,"instructions":["Segure um halter em cada mão, com os braços estendidos e as mãos ao lado do corpo, palmas voltadas para dentro. Flexione um braço por vez e suba o peso com movimento rápido. No início do movimento, gire o antebraço 90 graus; no ponto mais alto, gire um pouco mais o peso para fora. Sem pausa, desça o braço lentamente e faça o mesmo com o outro lado.","Não deixe o corpo balançar durante o exercício: todo o trabalho é do bíceps, o único músculo que deve se mover (atenção aos cotovelos)."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["biceps"],"secondaryMuscles":[],"equipment":"dumbbell"},{"id":"wger-1201","source":"https://wger.de/en/exercise/1201/view/","name":"Agachamento cruzado","portuguese":true,"instructions":["Comece em pé, com os pés na largura do quadril. Cruze o pé direito atrás do corpo em direção ao canto esquerdo e ao fundo da sala, flexionando os dois joelhos. Volte e repita, alternando os lados. Mantenha o quadril e os ombros apontados para a frente enquanto cruza os pés e flexiona os joelhos."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["quadriceps"],"secondaryMuscles":["hamstrings","calves","glutes"],"equipment":""},{"id":"wger-1203","source":"https://wger.de/en/exercise/1203/view/","name":"Elevação de panturrilha na perna esquerda","portuguese":true,"instructions":["1. Fique em pé no chão ou na borda de um degrau para aumentar a amplitude do movimento.","2. Levante um pé.","3. Suba o calcanhar até ficar na ponta dos pés.","4. *(variável)* Permaneça nessa posição por três segundos.","5. Desça o pé lentamente até quase tocar o chão com o calcanhar — não deixe o pé cair de uma vez."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["calves"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1204","source":"https://wger.de/en/exercise/1204/view/","name":"Sessão de cardio na bicicleta","portuguese":true,"instructions":["Sessão de cardio na bicicleta ergométrica Technogym Bike Excite 1000."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":""},{"id":"wger-1214","source":"https://wger.de/en/exercise/1214/view/","name":"Alavanca frontal agrupada","portuguese":true,"instructions":["Os músculos envolvidos na alavanca frontal mais sujeitos a tensão são principalmente os extensores: latíssimo do dorso, redondo maior, deltoide posterior e cabeça longa do bíceps."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["shoulders","biceps","lats"],"secondaryMuscles":["triceps"],"equipment":"body only"},{"id":"wger-1217","source":"https://wger.de/en/exercise/1217/view/","name":"Flexão nos dedos","portuguese":true,"instructions":["**Posicionamento das mãos:**","- Comece na posição de prancha, com as mãos diretamente sob os ombros.","- Abra bem os dedos e apoie-os firmemente no chão.","**Posicionamento dos dedos:**","- Aos poucos, tire as palmas do chão, transferindo o peso para os dedos.","- Distribua a carga de forma uniforme entre as pontas dos dedos e os polegares.","**Alinhamento do corpo:**","- Mantenha uma linha reta da cabeça aos calcanhares para ativar o core.","- Mantenha o corpo controlado e estável durante todo o exercício.","**Fase de descida:**","- Flexione lentamente os cotovelos, descendo o peito em direção ao chão.","- Mantenha o movimento controlado, com estabilidade nas pontas dos dedos.","**Fase de subida:**","- Empurre com as pontas dos dedos para estender os braços e voltar à posição inicial.","- Mantenha dedos e polegares ativos durante toda a flexão."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["chest"],"secondaryMuscles":["shoulders","abdominals","triceps"],"equipment":""},{"id":"wger-1219","source":"https://wger.de/en/exercise/1219/view/","name":"Remada australiana","portuguese":true,"instructions":["1. Deite-se sob uma barra alta ou barra de suspensão na altura adequada.","2. Posicione-se de costas sob a barra, segurando-a com pegada supinada (palmas voltadas para você).","3. Ajuste o corpo alinhado da cabeça aos pés, com os braços totalmente estendidos, os ombros estabilizados e as pernas alinhadas ao restante do corpo.","4. Flexione os cotovelos e puxe o peito até a barra, contraindo as costas; imagine que está tentando juntar as escápulas.","5. Segure a contração no topo do movimento por um instante para maximizar a ativação muscular.","6. Volte lentamente à posição inicial, estendendo os cotovelos."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["shoulders","biceps","lats"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1223","source":"https://wger.de/en/exercise/1223/view/","name":"Palmas acima da cabeça","portuguese":true,"instructions":["Fique em pé com os pés na largura dos ombros. Levante os braços e bata palmas acima da cabeça."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["shoulders"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1224","source":"https://wger.de/en/exercise/1224/view/","name":"Rosca arrastada com halteres","portuguese":true,"instructions":["Segure um halter em cada mão com as palmas voltadas para a frente. Puxe os cotovelos para trás e eleve os halteres até a altura do peito. Desça lentamente os halteres e repita o exercício."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["biceps"],"secondaryMuscles":[],"equipment":"dumbbell"},{"id":"wger-1225","source":"https://wger.de/en/exercise/1225/view/","name":"Rosca aberta com halteres","portuguese":true,"instructions":["Segure um halter em cada mão, com as mãos um pouco mais afastadas que a largura dos ombros e as palmas voltadas para a frente. Flexione os cotovelos e eleve os halteres até os ombros. Volte lentamente e repita."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["biceps"],"secondaryMuscles":[],"equipment":"dumbbell"},{"id":"wger-1226","source":"https://wger.de/en/exercise/1226/view/","name":"Rosca e desenvolvimento com halteres","portuguese":true,"instructions":["Flexione os cotovelos e eleve os halteres até os ombros. Empurre os halteres acima da cabeça girando os braços para que as palmas fiquem voltadas para a frente. Faça o caminho inverso para descer. Repita o exercício."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["biceps"],"secondaryMuscles":[],"equipment":"dumbbell"},{"id":"wger-1227","source":"https://wger.de/en/exercise/1227/view/","name":"Remada para deltoide posterior com halteres","portuguese":true,"instructions":["Segure um halter em cada mão. Incline o tronco pelo quadril até as costas ficarem quase paralelas ao chão e deixe os braços pendurados, alinhados aos ombros. Flexione e eleve os cotovelos para os lados até os braços ficarem paralelos ao chão. Volte lentamente e repita."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["shoulders"],"secondaryMuscles":[],"equipment":"dumbbell"},{"id":"wger-1228","source":"https://wger.de/en/exercise/1228/view/","name":"Supino fechado com halteres","portuguese":true,"instructions":["Deite-se de costas em um banco plano. Segure um halter em cada mão e eleve os braços em direção ao teto, com as palmas voltadas uma para a outra e os halteres pressionados juntos. Desça lentamente os halteres até o peito e empurre-os de volta devagar. Repita o exercício."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["chest","triceps"],"secondaryMuscles":[],"equipment":"dumbbell"},{"id":"wger-1234","source":"https://wger.de/en/exercise/1234/view/","name":"Elevação pélvica unilateral com halter","portuguese":true,"instructions":["A elevação pélvica unilateral é feita apoiando a parte superior das costas em um banco, elevando uma perna e estendendo o quadril da outra para obter uma contração isolada do glúteo. Trabalhando cada lado separadamente, você isola totalmente os glúteos de forma unilateral, o que gera estímulo máximo de treino."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["glutes"],"secondaryMuscles":["hamstrings","quadriceps"],"equipment":"dumbbell"},{"id":"wger-1238","source":"https://wger.de/en/exercise/1238/view/","name":"Posição de sapo","portuguese":true,"instructions":["**Posição inicial:**","- Fique em pé com os pés na largura dos ombros e os dedos apontados para a frente, de frente para uma parede ou banco para apoio, se necessário.","- Flexione os joelhos em posição de agachamento.","- Coloque as mãos no chão à frente, na largura dos ombros, com os dedos bem abertos.","- Garanta que os cotovelos fiquem sob os ombros e que o corpo forme uma linha reta da cabeça aos calcanhares.","**Fase de subida:**","- Empurre com pés e mãos para tirar o corpo do chão.","- Estenda as pernas e os braços mantendo o corpo alinhado.","- Contraia o core e os glúteos para manter a posição.","- Se precisar, apoie os joelhos na parede ou no banco como auxílio."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["shoulders","biceps","abdominals"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1241","source":"https://wger.de/en/exercise/1241/view/","name":"Dorsiflexão com elástico","portuguese":true,"instructions":["Este exercício usa uma faixa elástica e trabalha o sóleo e o tibial anterior."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":""},{"id":"wger-1242","source":"https://wger.de/en/exercise/1242/view/","name":"Flexão plantar com elástico","portuguese":true,"instructions":["A flexão plantar com elástico é uma ótima forma de fazer a ponte entre a amplitude de flexão plantar e a elevação de panturrilha com carga, mais intensa. Ela ajuda a fortalecer a panturrilha, carregar o tendão de Aquiles e melhorar a amplitude de flexão plantar."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["calves"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1243","source":"https://wger.de/en/exercise/1243/view/","name":"Elevação de panturrilha bilateral","portuguese":true,"instructions":["A elevação de panturrilha com as duas pernas é importante para fortalecer e criar controle e estabilidade em torno do tornozelo e do joelho, além de dar equilíbrio e controle ao quadril e à pelve."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["calves"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1245","source":"https://wger.de/en/exercise/1245/view/","name":"Alavanca frontal","portuguese":true,"instructions":["A alavanca frontal é uma figura na qual o corpo é mantido na horizontal, paralelo ao chão."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["lats","abdominals"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1248","source":"https://wger.de/en/exercise/1248/view/","name":"Do topo da barra fixa à alavanca frontal","portuguese":true,"instructions":["A partir da fase final da barra fixa, empurramos o corpo para trás com os ombros até chegar à posição de alavanca frontal. De lá, puxamos de volta até a posição inicial."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["lats"],"secondaryMuscles":["abdominals"],"equipment":""},{"id":"wger-1252","source":"https://wger.de/en/exercise/1252/view/","name":"Barra fixa no front lever","portuguese":true,"instructions":["Na posição de front lever, com as pernas estendidas ou mais fácil se estiverem recolhidas, puxe aproximando o peito da barra."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["biceps","lats","abdominals"],"secondaryMuscles":["shoulders"],"equipment":"body only"},{"id":"wger-1263","source":"https://wger.de/en/exercise/1263/view/","name":"Ponte de costas","portuguese":true,"instructions":["Deite-se no chão com as costas apoiadas no solo e as pernas flexionadas, com os pés apoiados no chão, deixando cerca de 20 cm entre os pés e os glúteos. As mãos ficam apoiadas no chão, junto às orelhas, com os dedos apontando na direção dos pés. Os cotovelos ficam flexionados e apontando para o teto. Esta é a posição inicial. Agora empurre o quadril o mais alto que puder, elevando o corpo do chão, e continue empurrando com as mãos, estendendo os cotovelos e os joelhos, até que as costas fiquem totalmente arqueadas (ponte lombar). A cabeça também sai do chão e deve ficar na linha dos cotovelos, olhando para trás. Esta é a posição final. A descida deve ser lenta e controlada. A coluna deve ficar em curva convexa. Não é bom tirar as costas do chão; ela deve permanecer reta. Deve ficar bem arredondada. Você também vai perceber uma sensação de maior oxigenação nas costas. Depois de sair do chão, o quadril deve ficar bem alto, até acima do nível da cabeça. Braços e pernas devem permanecer estendidos. Parece fácil, mas exige um bom nível de flexibilidade. A respiração deve ser profunda. Esta postura alonga a caixa torácica e faz pressão sobre o diafragma. Se a postura for executada corretamente, a respiração será perfeita. Nunca prenda a respiração durante o exercício."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":["shoulders","hamstrings","calves","lats","triceps"],"equipment":""},{"id":"wger-1280","source":"https://wger.de/en/exercise/1280/view/","name":"Puxada de Biceps","portuguese":true,"instructions":["Na máquina de puxada de costas, segure a barra com as mãos relativamente próximas. Use uma pegada pronada (P.ex.: o dorso das suas mãos vão ficar voltados para a máquina). Então puxe a barra em uma linha reta, como se fosse em direção ao chão. Garanta que seus bíceps sejam a força motriz do movimento. Você provavelmente sentirá seus ombros e latíssimo trabalhando, mas garanta que seus bíceps sejam os músculos mais afetados."],"credit":{"author":"daniel.escada","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["biceps"],"secondaryMuscles":["shoulders","lats"],"equipment":""},{"id":"wger-1282","source":"https://wger.de/en/exercise/1282/view/","name":"Barra fixa isométrica com pegada invertida","portuguese":true,"instructions":["Segure a barra com pegada supinada, com as palmas voltadas para você, e mantenha o corpo suspenso na posição alta da barra fixa, com o queixo próximo ou acima da barra. Permaneça parado nessa posição pelo tempo determinado, mantendo o core firme, os ombros estáveis e o corpo sem balançar."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["lats"],"secondaryMuscles":["biceps"],"equipment":"body only"},{"id":"wger-1283","source":"https://wger.de/en/exercise/1283/view/","name":"Remada com halteres apoiada no peito","portuguese":true,"instructions":["Ajuste um banco regulável em um ângulo de 45 graus.","Deite-se de bruços com a cabeça pendurada um pouco acima da borda do banco.","Segure um halter em cada mão e posicione-se com boa postura: core e latíssimo engajados e ombros neutros.","Reme os halteres em direção à parte superior do estômago e contraia as costas no topo da repetição.","Por fim, desça os halteres de volta à posição inicial e repita até completar todas as repetições."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["biceps","lats"],"secondaryMuscles":[],"equipment":"dumbbell"},{"id":"wger-1286","source":"https://wger.de/en/exercise/1286/view/","name":"Prancha dinâmica com saltos","portuguese":true,"instructions":["1. Comece na posição de prancha, com as mãos diretamente sob os ombros e os pés na largura do quadril.","2. Contraia o core para manter o corpo em linha reta da cabeça aos pés.","3. A partir dessa posição, flexione levemente os joelhos e salte com os dois pés para dentro, aproximando-os o máximo possível do centro do corpo.","4. Assim que os pés tocarem o chão, empurre com força para saltar de novo e voltar à posição inicial de prancha.","5. Continue repetindo esse movimento de salto, mantendo o controle e a estabilidade do core durante todo o exercício.","6. Mantenha a respiração constante durante os saltos, respirando fundo e controlando a respiração.","7. Mantenha o olhar fixo no chão para preservar o alinhamento correto da coluna.","8. Repita os saltos pelo tempo desejado ou pelo número de repetições recomendado no seu programa de treino.","9. Para terminar o exercício, descanse saindo da posição de prancha e depois alongue se necessário para relaxar a musculatura."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["abdominals"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1290","source":"https://wger.de/en/exercise/1290/view/","name":"Rosca direta com pegada pronada","portuguese":true,"instructions":["**Posição inicial:**","Selecione o peso adequado em uma barra. Fique em pé com a barra, usando pegada pronada e as mãos afastadas na largura dos ombros. Contraia o assoalho pélvico e o core enquanto mantém o peito levantado.","**Execução:**","Contraindo os bíceps, flexione os cotovelos totalmente enquanto expira. Volte à posição inicial com um movimento suave enquanto inspira."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["biceps"],"secondaryMuscles":[],"equipment":"barbell"},{"id":"wger-1294","source":"https://wger.de/en/exercise/1294/view/","name":"Arco femoral unilateral","portuguese":true,"instructions":["Especificamente, os músculos envolvidos são: bíceps femoral, músculo semimembranoso e músculo semitendinoso."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["hamstrings"],"secondaryMuscles":["glutes"],"equipment":""},{"id":"wger-1298","source":"https://wger.de/en/exercise/1298/view/","name":"Extensão de tríceps na polia alta cruzada","portuguese":true,"instructions":["A extensão de tríceps na polia alta com pegada cruzada é um exercício de isolamento para os tríceps, especialmente a cabeça longa. Ela usa polias e pegadores segurados com as mãos invertidas entre si, permitindo um movimento de empurrar diferenciado que pode ser eficaz para ganhar força no tríceps. Diferentemente de exercícios com barra reta ou corda, essa variação pode ser mais confortável para os punhos e os cotovelos."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["triceps"],"secondaryMuscles":[],"equipment":""},{"id":"JM_Press","source":"https://wger.de/en/exercise/1302/view/","name":"JM press","portuguese":true,"instructions":["O JM press mantém os ombros parados, usando a flexão e a extensão dos cotovelos para mover a carga com a força do tríceps. Isso significa que você aproveita todos os benefícios dos melhores exercícios para o tríceps sem sobrecarregar a delicada articulação do ombro. Um clássico ganha-ganha!"],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}},{"id":"wger-1303","source":"https://wger.de/en/exercise/1303/view/","name":"Remada Helms","portuguese":true,"instructions":["**Montagem:** apoie o peito na ponta de um banco, usando uma toalha ou algo macio para proteger o peito. O peito deve ficar em contato com o banco na altura da linha dos mamilos. As costas devem ficar quase paralelas ao chão.","**Execução:** ao iniciar o exercício, concentre-se em puxar os cotovelos para trás até sentir a máxima contração no latíssimo. Se quiser ativar também o trapézio, relaxe as escápulas quando os pesos estiverem pendurados e retraia-as no início da repetição."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["lats"],"secondaryMuscles":[],"equipment":"dumbbell"},{"id":"wger-1307","source":"https://wger.de/en/exercise/1307/view/","name":"Prancha frontal","portuguese":true,"instructions":["A prancha é um exercício com peso corporal. Por ser um movimento multifuncional, ela não trabalha só a musculatura abdominal, mas também a coluna e o quadril. A prancha fortalece e firma o corpo todo, melhora a postura e o equilíbrio, reduz a gordura corporal e pode ajudar a acelerar o metabolismo.","Exercícios como a prancha ajudam a aumentar a resistência dos músculos estabilizadores do abdômen. Também podem aliviar dores nas costas associadas ao enfraquecimento da função dos músculos estabilizadores do corpo.","A prancha é um exercício versátil que trabalha muitos dos grupos musculares mais importantes do corpo, por isso pode ser usada por qualquer pessoa para melhorar a resistência e a força geral."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["abdominals"],"secondaryMuscles":["chest","quadriceps"],"equipment":""},{"id":"wger-1312","source":"https://wger.de/en/exercise/1312/view/","name":"Agachamento com peso corporal","portuguese":true,"instructions":["O agachamento é um tipo de exercício com peso corporal. É um dos exercícios mais populares para ganho de força e massa muscular. O agachamento é especialmente eficaz para focar nos músculos das pernas e do quadril.","É um exercício fácil para iniciantes. Pode ajudar a fortalecer a musculatura das pernas, firmar os músculos do quadril e queimar calorias para perder peso.","Ele firma os glúteos e as pernas. O agachamento é muito eficaz para firmar e fortalecer as pernas, atuando nos glúteos, nos flexores do quadril, no quadríceps, nos posteriores da coxa e nos músculos da parte interna da coxa. Além disso, o agachamento com peso corporal ajuda a modelar os glúteos."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","abdominals"],"equipment":""},{"id":"wger-1314","source":"https://wger.de/en/exercise/1314/view/","name":"Polichinelo","portuguese":true,"instructions":["O polichinelo é um exercício pliométrico. A pliometria reúne movimentos aeróbicos explosivos que aumentam a velocidade, a agilidade e a potência e trabalham o corpo todo.","O polichinelo trabalha braços, ombros, abdômen, musculatura do quadril e flexores do quadril, além das coxas, dos tendões dos joelhos e do quadríceps.","Os saltos fazem bem à saúde porque combinam condicionamento cardiovascular com trabalho de força. Como elevam a frequência cardíaca, também melhoram o condicionamento cardiovascular."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["quadriceps"],"secondaryMuscles":["glutes","abdominals"],"equipment":""},{"id":"wger-1318","source":"https://wger.de/en/exercise/1318/view/","name":"Corrida saltada com joelhos altos","portuguese":true,"instructions":["Você pode usar este exercício tanto como aquecimento dinâmico antes do treino quanto na sua rotina de cardio para queimar gordura.","A corrida saltada com joelhos altos é um exercício pliométrico. A pliometria reúne movimentos aeróbicos explosivos que aumentam a velocidade, a agilidade e a potência e trabalham o corpo todo.","Ela trabalha os oblíquos, a musculatura das pernas, o quadril e os flexores do quadril, além das coxas, dos tendões dos joelhos, do quadríceps e dos ombros.","Os saltos fazem bem à saúde porque combinam condicionamento cardiovascular com trabalho de força. Como elevam a frequência cardíaca, também melhoram o condicionamento cardiovascular."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["abdominals"],"secondaryMuscles":["biceps","glutes","quadriceps","triceps"],"equipment":""},{"id":"wger-1320","source":"https://wger.de/en/exercise/1320/view/","name":"Mergulho no chão para tríceps","portuguese":true,"instructions":["O mergulho no chão para tríceps é um exercício composto, pois trabalha vários grupos musculares ao mesmo tempo. Apesar de o foco principal ser o tríceps, esse exercício com peso corporal também atinge o peito e a parte frontal do ombro.","É um dos exercícios mais eficazes para aumentar a força dos braços e construir massa magra na parte superior dos braços.","O mergulho no chão é um exercício de cadeia cinética fechada, ou seja, o movimento acontece em torno de um ponto fixo. Isso aumenta a força de compressão sobre as articulações e melhora a estabilidade."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["biceps","triceps"],"secondaryMuscles":["shoulders","chest"],"equipment":""},{"id":"wger-1324","source":"https://wger.de/en/exercise/1324/view/","name":"Afundo com peso corporal","portuguese":true,"instructions":["O afundo com peso corporal é um exercício calistênico eficaz para fortalecer a parte inferior do corpo, melhorar o equilíbrio e a estabilidade e desenvolver força funcional. É uma opção popular em treinos com o peso do corpo e em casa, e também pode fazer parte de uma rotina de força mais ampla."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["quadriceps"],"secondaryMuscles":["glutes"],"equipment":""},{"id":"wger-1325","source":"https://wger.de/en/exercise/1325/view/","name":"Salto lateral com impulso","portuguese":true,"instructions":["Impulsione-se do chão, aterrisse em uma perna e recupere o equilíbrio antes de saltar para a outra perna."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["calves"],"secondaryMuscles":["hamstrings"],"equipment":""},{"id":"wger-1333","source":"https://wger.de/en/exercise/1333/view/","name":"Rosca de punho com pegada supinada","portuguese":true,"instructions":["- Contraia a musculatura.","- Não pegue embalo.","- Execute o movimento de forma controlada e lenta."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":"dumbbell"},{"id":"wger-1353","source":"https://wger.de/en/exercise/1353/view/","name":"Supino hexagonal com halteres","portuguese":true,"instructions":["- Contraia a musculatura.","- Posicione os pés bem afastados.","- Execute o movimento de forma controlada e lenta, conduzindo os pesos em direção à parte inferior do peito e ao abdômen."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["chest","triceps"],"secondaryMuscles":["shoulders"],"equipment":"dumbbell"},{"id":"wger-1360","source":"https://wger.de/en/exercise/1360/view/","name":"Arremesso e desenvolvimento com kettlebells","portuguese":true,"instructions":["Exercício de hipertrofia para o corpo todo. Proporciona uma grande variedade de benefícios em força e em tamanho muscular, além de ser extremamente funcional."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["shoulders","biceps","quadriceps","triceps"],"secondaryMuscles":["hamstrings","glutes","lats","abdominals"],"equipment":"kettlebells"},{"id":"wger-1361","source":"https://wger.de/en/exercise/1361/view/","name":"Agachamento frontal com dois kettlebells","portuguese":true,"instructions":["O agachamento frontal com kettlebells é um exercício composto e multiarticular que trabalha vários grupos musculares."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["glutes","quadriceps"],"secondaryMuscles":["hamstrings","calves","abdominals"],"equipment":"kettlebells"},{"id":"wger-1363","source":"https://wger.de/en/exercise/1363/view/","name":"Liberação miofascial com rolo","portuguese":true,"instructions":["- Execute movimentos controlados e lentos.","- Sem pegar embalo."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":""},{"id":"wger-1366","source":"https://wger.de/en/exercise/1366/view/","name":"Agachamento em passada estática com halteres","portuguese":true,"instructions":["- Execução controlada.","- Sem embalo.","- Em ritmo lento."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["glutes","quadriceps"],"secondaryMuscles":["hamstrings","calves"],"equipment":"dumbbell"},{"id":"wger-1370","source":"https://wger.de/en/exercise/1370/view/","name":"Terra com halteres","portuguese":true,"instructions":["- Execução controlada e lenta.","- Sem pegar embalo."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["hamstrings","glutes"],"secondaryMuscles":["quadriceps"],"equipment":"dumbbell"},{"id":"wger-1378","source":"https://wger.de/en/exercise/1378/view/","name":"Elevação lateral na polia (unilateral)","portuguese":true,"instructions":["A elevação lateral unilateral na polia é uma variação da elevação lateral e um exercício usado para construir os músculos dos ombros.","1. Posicione a polia na altura mais baixa possível e acople uma alça simples.","2. Alcance o corpo e segure a alça com pegada neutra.","3. Mantenha o cotovelo levemente flexionado e puxe a alça atravessando o corpo, elevando-a lateralmente.","4. Desça a alça lentamente de volta à posição inicial, com controle."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["shoulders"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1380","source":"https://wger.de/en/exercise/1380/view/","name":"Abertura com elástico","portuguese":true,"instructions":["- Segure o elástico com os braços estendidos à frente na altura dos ombros.","- Mantenha os cotovelos levemente flexionados, porém fixos durante todo o movimento.","- Abra o elástico afastando os braços até que ele toque ou chegue perto do peito.","- Traga os braços lentamente de volta à posição inicial, controlando a tensão do elástico."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":""},{"id":"wger-1387","source":"https://wger.de/en/exercise/1387/view/","name":"Chutes frontais para posterior de coxa","portuguese":true,"instructions":["Fique em pé com os pés na largura do quadril e estenda um braço à frente. Balance a perna para cima, à frente do corpo, e desça, mantendo-a o mais reta possível e os dedos dos pés apontados para cima. Repita com a outra perna."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["hamstrings"],"secondaryMuscles":["glutes"],"equipment":""},{"id":"wger-1391","source":"https://wger.de/en/exercise/1391/view/","name":"Caminhada do elefante","portuguese":true,"instructions":["Incline-se no quadril até sentir um alongamento atrás dos joelhos. Flexione uma perna enquanto a outra permanece estendida e, em seguida, flexione a outra perna enquanto estende a primeira, de forma fluida."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["hamstrings"],"secondaryMuscles":["calves"],"equipment":""},{"id":"Good_Morning","source":"https://wger.de/en/exercise/1392/view/","name":"Flexão de tronco em pé","portuguese":true,"instructions":["Fique em pé com os pés afastados além da largura dos ombros (base mais ampla) e coloque as mãos na cintura. Incline-se no quadril e desça o tronco em direção ao chão mantendo as costas retas, depois retorne."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}},{"id":"wger-1395","source":"https://wger.de/en/exercise/1395/view/","name":"Balanço de perna cruzado","portuguese":true,"instructions":["Apoie-se em uma parede ou em algo próximo. Balance uma perna cruzando a frente do corpo, depois volte e abra para o lado. Repita aumentando lentamente a amplitude do movimento."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["hamstrings"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1398","source":"https://wger.de/en/exercise/1398/view/","name":"Alongamento de isquiotibiais sentado","portuguese":true,"instructions":["Sente-se no chão e flexione uma perna, trazendo o joelho em direção ao corpo. Coloque a mão atrás do isquiotibial e puxe suavemente a perna em direção ao peito, sentindo o alongamento na parte de trás da coxa. Em seguida, estenda a perna, apontando para o teto."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["hamstrings"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1400","source":"https://wger.de/en/exercise/1400/view/","name":"Alongamento cruzado de isquiotibiais","portuguese":true,"instructions":["Em pé, cruze uma perna atrás da outra, mantendo essa perna estendida. Desça o tronco e tente tocar os dedos do pé dessa perna. Flexione levemente a outra perna para conseguir descer."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["hamstrings"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1407","source":"https://wger.de/en/exercise/1407/view/","name":"Agachamento cossaco","portuguese":true,"instructions":["O agachamento cossaco é um exercício multiarticular que trabalha principalmente as pernas e os glúteos, mas também envolve músculos estabilizadores. É excelente para melhorar força, mobilidade e estabilidade de forma funcional."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["glutes","quadriceps"],"secondaryMuscles":["calves","abdominals"],"equipment":""},{"id":"wger-1409","source":"https://wger.de/en/exercise/1409/view/","name":"Bandeira do dragão","portuguese":true,"instructions":["Mantenha o corpo completamente rígido durante todo o movimento, evitando que a lombar afunde. Use uma pegada firme para estabilizar a parte superior do corpo. Comece com versões mais simples, como com os joelhos flexionados, para construir força e controle."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["abdominals"],"secondaryMuscles":["shoulders","glutes","lats","triceps"],"equipment":""},{"id":"wger-1411","source":"https://wger.de/en/exercise/1411/view/","name":"Toque nos calcanhares","portuguese":true,"instructions":["**Posição inicial:**","- Deite-se de costas em um colchonete.","- Flexione os joelhos, mantendo os pés apoiados no chão na largura do quadril.","- Coloque os braços ao lado do corpo, com as palmas voltadas para dentro e ligeiramente afastadas do chão.","**Ativação do core:**","- Eleve um pouco a cabeça, os ombros e a parte superior das costas, mantendo o pescoço neutro e o queixo levemente recolhido.","**Execução do movimento:**","- Incline o tronco para a direita, levando a mão direita em direção ao calcanhar direito.","- Volte ao centro; em seguida, incline para a esquerda, levando a mão esquerda ao calcanhar esquerdo.","- Continue alternando os lados de forma controlada.","**Respiração:**","- Expire ao alcançar o calcanhar e inspire ao voltar ao centro."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":["abdominals"],"equipment":""},{"id":"wger-1414","source":"https://wger.de/en/exercise/1414/view/","name":"Agachamento hack","portuguese":true,"instructions":["O agachamento hack trabalha o corpo inferior e pode ser feito na máquina de hack squat ou com barra. Na versão com máquina, posicione-se na plataforma com os ombros sob os apoios e os pés um pouco à frente. Empurre com os calcanhares para tirar o peso, depois flexione os joelhos e desça a plataforma de forma controlada até as coxas ficarem paralelas ao chão. Empurre de volta para a posição inicial. Na versão com barra, segure a barra atrás das pernas com os braços estendidos e execute um movimento semelhante ao agachamento."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["quadriceps"],"secondaryMuscles":["hamstrings","calves","glutes"],"equipment":""},{"id":"wger-1415","source":"https://wger.de/en/exercise/1415/view/","name":"Abdominal com halter","portuguese":true,"instructions":["O abdominal com halter é uma variação com carga do abdominal tradicional, feita para trabalhar a musculatura abdominal com mais intensidade. Deite-se de costas com os joelhos flexionados e os pés apoiados no chão. Segure um halter com as duas mãos junto ao peito ou acima da cabeça. Eleve os ombros e a parte alta das costas do chão em um movimento de flexão do tronco, contraindo o abdômen. Desça devagar até a posição inicial. Mantenha o movimento controlado do começo ao fim para evitar sobrecarga na região."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["abdominals"],"secondaryMuscles":[],"equipment":"dumbbell"},{"id":"wger-1424","source":"https://wger.de/en/exercise/1424/view/","name":"Rosca bíceps na máquina","portuguese":true,"instructions":["A rosca bíceps na máquina isola o bíceps e oferece uma amplitude de movimento controlada. Sente-se na máquina com as costas apoiadas no encosto e ajuste o assento para que seus braços fiquem alinhados com as alças ou apoios. Segure as alças com firmeza, mantendo os cotovelos fixos no lugar, e flexione os braços para cima contraindo o bíceps. Desça as alças devagar até a posição inicial, mantendo o controle durante todo o movimento."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["biceps"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1429","source":"https://wger.de/en/exercise/1429/view/","name":"Rotação de ombro com halter","portuguese":true,"instructions":["A rotação de ombro com halter fortalece os músculos do manguito rotador e melhora a estabilidade e a mobilidade do ombro.","1. **Rotação externa:** segure um halter em uma das mãos, com o cotovelo flexionado a 90 graus e junto ao corpo. Gire o antebraço para fora, afastando-o do corpo, mantendo o cotovelo parado. Volte devagar à posição inicial.","2. **Rotação interna:** segure um halter em uma das mãos, com o cotovelo flexionado a 90 graus e junto ao corpo. Gire o antebraço para dentro, em direção ao corpo, e volte devagar à posição inicial. Execute o exercício com movimentos controlados para evitar lesões."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["shoulders"],"secondaryMuscles":[],"equipment":"dumbbell"},{"id":"wger-1434","source":"https://wger.de/en/exercise/1434/view/","name":"Lat pull com halter","portuguese":true,"instructions":["- Incline o tronco à frente","- Traga os halteres junto ao corpo, com os braços levemente flexionados, em direção às costas."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["lats"],"secondaryMuscles":["glutes"],"equipment":"dumbbell"},{"id":"Clean","source":"https://wger.de/en/exercise/1438/view/","name":"Clean (levantamento olímpico)","portuguese":true,"instructions":["Clean é um levantamento olímpico clássico: puxe a barra do chão e receba o peso sobre os ombros, executando um agachamento frontal."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}},{"id":"wger-1441","source":"https://wger.de/en/exercise/1441/view/","name":"Desenvolvimento inclinado com halteres","portuguese":true,"instructions":["- Sente-se em um banco com inclinação de 45 graus.","- Mantenha os cotovelos a 45 graus para fora.","- Desça os halteres até os braços ficarem paralelos aos ombros.","- Suba os halteres até se encontrarem acima da cabeça."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["shoulders"],"secondaryMuscles":["triceps"],"equipment":"dumbbell"},{"id":"wger-1442","source":"https://wger.de/en/exercise/1442/view/","name":"Desenvolvimento Kreis com halteres","portuguese":true,"instructions":["- Sente-se em um banco com inclinação de 45 graus.","- Segure os halteres acima da cabeça.","- Desça os halteres como em um desenvolvimento.","- Gire os halteres com as palmas voltadas para cima e estenda os braços à frente do corpo.","- Aproxime as mãos até os halteres se encontrarem, mantendo os braços estendidos.","- Faça o movimento inverso até os halteres voltarem acima da cabeça.","- Isso completa uma repetição."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["shoulders"],"secondaryMuscles":["biceps","chest","abdominals","triceps"],"equipment":"dumbbell"},{"id":"wger-1445","source":"https://wger.de/en/exercise/1445/view/","name":"Arremesso (jerk)","portuguese":true,"instructions":["Arremesso olímpico.","- Segure a barra apoiada na parte da frente dos ombros, como no push press.","- Flexione e estenda os joelhos impulsionando a barra para cima enquanto mergulha por baixo dela.","- Receba a barra acima da cabeça com os braços estendidos, em afundo.","- Depois, junte os pés até ficarem paralelos, mantendo a barra travada acima da cabeça."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["shoulders"],"secondaryMuscles":["glutes","quadriceps","triceps"],"equipment":"barbell"},{"id":"wger-1446","source":"https://wger.de/en/exercise/1446/view/","name":"Arremesso olímpico (clean and jerk)","portuguese":true,"instructions":["Arremesso olímpico (clean and jerk): combinação do clean com o jerk em um único movimento."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["shoulders","hamstrings","glutes","quadriceps"],"secondaryMuscles":["lats","abdominals","triceps"],"equipment":"barbell"},{"id":"wger-1449","source":"https://wger.de/en/exercise/1449/view/","name":"Simulador de escada (ClimbMill)","portuguese":true,"instructions":["O ClimbMill, também conhecido como simulador de escada, é um equipamento aeróbico que simula subir escadas. É uma forma eficaz de melhorar o condicionamento enquanto fortalece o corpo inferior. Para usar o equipamento, suba nos degraus móveis, mantenha a postura ereta e use os apoios laterais para equilíbrio, se precisar. Ajuste a velocidade e a intensidade conforme seu nível de condicionamento. O exercício melhora a saúde cardiovascular, queima calorias e aumenta a resistência muscular do corpo inferior."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["quadriceps"],"secondaryMuscles":["hamstrings","glutes"],"equipment":""},{"id":"wger-1450","source":"https://wger.de/en/exercise/1450/view/","name":"Alongamento cobra","portuguese":true,"instructions":["O alongamento cobra é um exercício de extensão da coluna que melhora a flexibilidade da coluna e alivia a tensão na lombar. Para executar, deite-se de bruços no chão com as mãos apoiadas sob os ombros. Empurre as palmas contra o chão e eleve o peito, mantendo o quadril no chão. Mantenha os cotovelos levemente flexionados e os ombros relaxados. Segure o alongamento por alguns segundos e depois desça devagar. O exercício ajuda a melhorar a postura e a reduzir a rigidez da lombar."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["abdominals"],"secondaryMuscles":["chest"],"equipment":""},{"id":"wger-1452","source":"https://wger.de/en/exercise/1452/view/","name":"Alongamento joelho ao peito","portuguese":true,"instructions":["O alongamento joelho ao peito é simples e eficaz para aliviar a tensão na lombar e melhorar a mobilidade do quadril. Para executar, deite-se de costas com as pernas estendidas. Traga um joelho em direção ao peito, envolvendo a canela ou a parte de trás da coxa com as mãos. Puxe suavemente o joelho para mais perto do peito, mantendo a outra perna estendida no chão. Segure o alongamento de 15 a 30 segundos e troque de lado. Para um alongamento mais profundo, os dois joelhos podem ser puxados ao peito ao mesmo tempo."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["glutes"],"secondaryMuscles":["hamstrings"],"equipment":""},{"id":"wger-1457","source":"https://wger.de/en/exercise/1457/view/","name":"Press around na polia","portuguese":true,"instructions":["Ajuste a polia na altura do peito e coloque uma alça em D. Pegue a alça com pegada neutra e segure-a junto ao peito, com o cotovelo totalmente flexionado e colado ao lado do corpo. Vire-se de costas para a polia, de modo que o tronco fique a 45 graus.","Segure o outro lado da estação funcional com a mão correspondente. Adote uma base escalonada, com uma perna à frente da outra, para melhor equilíbrio.","Mantendo o peito aberto, estenda o cotovelo a 45 graus cruzando a linha do meio do corpo, com o braço paralelo ao chão. Pare pouco antes de travar o cotovelo e contraia o peito no ponto mais alto da amplitude."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["shoulders","chest","triceps"],"secondaryMuscles":["biceps"],"equipment":""},{"id":"wger-1458","source":"https://wger.de/en/exercise/1458/view/","name":"Elevação em Y cruzada na polia","portuguese":true,"instructions":["Fixe uma alça em D na polia. Execute um movimento semelhante a sacar uma espada atravessando o corpo."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["shoulders","lats"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1463","source":"https://wger.de/en/exercise/1463/view/","name":"Remada curvada supinada com halteres","portuguese":true,"instructions":["A remada curvada supinada com halteres envolve as costas, então você pode usar uma carga um pouco maior. O detalhe é conseguir controlar o peso em todas as repetições.","1. Comece segurando um par de halteres, com os pés afastados na largura dos ombros e os joelhos levemente flexionados.","2. Incline o tronco à frente pelo quadril até ele ficar quase paralelo ao chão, mantendo as costas retas e os joelhos com uma leve flexão.","3. Solte o ar enquanto rema os halteres para os lados até a altura do peito, conduzindo com os cotovelos, até os braços passarem um pouco da paralela ao chão e os halteres ficarem na altura das costelas.","4. Desça devagar até a posição inicial e repita. Mantenha as costas retas o tempo todo."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["biceps"],"secondaryMuscles":["lats"],"equipment":"dumbbell"},{"id":"wger-1466","source":"https://wger.de/en/exercise/1466/view/","name":"Elevação de panturrilha na máquina de hack","portuguese":true,"instructions":["De preferência com o acessório de trapézio, eleve o peso usando as panturrilhas, ficando na ponta dos pés."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["calves"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1467","source":"https://wger.de/en/exercise/1467/view/","name":"Supino inclinado com pegada fechada","portuguese":true,"instructions":["Pegada mais fechada que a do supino reto normal, apenas um pouco além da largura dos ombros."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["triceps"],"secondaryMuscles":["shoulders","chest"],"equipment":"barbell"},{"id":"wger-1468","source":"https://wger.de/en/exercise/1468/view/","name":"Tríceps testa no chão","portuguese":true,"instructions":["Permite carregar mais peso com segurança do que o tríceps testa tradicional: deite-se no chão e apoie o peso no chão entre cada repetição."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["triceps"],"secondaryMuscles":[],"equipment":"e-z curl bar"},{"id":"wger-1469","source":"https://wger.de/en/exercise/1469/view/","name":"Crucifixo curvado na polia","portuguese":true,"instructions":["Mantendo o tronco inclinado a aproximadamente 105 graus."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["chest"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1470","source":"https://wger.de/en/exercise/1470/view/","name":"Puxada alta unilateral meio ajoelhado","portuguese":true,"instructions":["Fixe uma alça em D em uma polia alta e use os músculos do latíssimo para puxar o peso com uma só mão."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["lats"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1471","source":"https://wger.de/en/exercise/1471/view/","name":"Remada unilateral pesada (Kroc)","portuguese":true,"instructions":["Remadas com halteres, com técnica mais solta, mas com carga mais pesada."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["lats"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1472","source":"https://wger.de/en/exercise/1472/view/","name":"Encolhimento na polia baixa (para dentro)","portuguese":true,"instructions":["Fixe duas alças em D em duas polias baixas e faça o encolhimento puxando as alças para dentro, usando a parte superior do trapézio."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":""},{"id":"wger-1475","source":"https://wger.de/en/exercise/1475/view/","name":"Prancha com joelho ao cotovelo oposto","portuguese":true,"instructions":["Neste movimento de rotação de baixo para cima, você cruza o joelho e o leva contra o cotovelo oposto. Comece em prancha alta (ou na posição de quatro apoios) com as mãos diretamente sob os ombros. Eleve o joelho esquerdo em direção ao braço direito e deslize-o para cima ao longo do antebraço, para obter mais retroversão pélvica e ativação do abdômen. Depois faça o lado oposto, levando o joelho direito em direção à mão esquerda."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["abdominals"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1476","source":"https://wger.de/en/exercise/1476/view/","name":"Abdominal remador com pernas em borboleta","portuguese":true,"instructions":["Neste exercício de amplitude intermediária, os músculos dos braços dão um pouco de impulso para ajudar a tirar o corpo do chão. Você também abre os braços, na posição acima da cabeça, o que ativa a parte superior das costas. Comece deitado com os pés apoiados no chão, joelhos em ângulo e braços cruzados sobre o peito. Usando o abdômen, eleve o tronco do chão enquanto abre os braços na posição de trave de gol, com os cotovelos a 90 graus, e depois desça lentamente para voltar à posição inicial."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["abdominals"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1478","source":"https://wger.de/en/exercise/1478/view/","name":"Abdominal com pausa no topo (levitação)","portuguese":true,"instructions":["Neste movimento de cima para baixo, buscamos mover o tronco superior sem mover o tronco inferior. Comece deitado no chão com os pés apoiados no chão e os braços cruzados acima da cabeça, com as mãos atrás da cabeça. Eleve o tronco e tire as escápulas do chão, segurando e pausando no topo por uma ou duas contagens. Procure fazer o abdômen superior trabalhar e sustente essa contração por 10 repetições de boa qualidade."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["abdominals"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1481","source":"https://wger.de/en/exercise/1481/view/","name":"Tríceps na corda com arraste no corpo","portuguese":true,"instructions":["1. A posição inicial é em pé, de frente para a polia, com as alças da corda em ambas as mãos e os pés na largura dos ombros.","2. Incline levemente o tronco à frente, a partir do quadril, mantendo o peito ereto, e leve os ombros e cotovelos para trás do corpo, para que, ao empurrar as alças para baixo, você consiga uma contração completa da cabeça longa do tríceps.","3. Arraste a corda o mais próximo possível do corpo e estenda os cotovelos até o bloqueio total."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["triceps"],"secondaryMuscles":[],"equipment":"e-z curl bar"},{"id":"wger-1482","source":"https://wger.de/en/exercise/1482/view/","name":"Rosca com halteres com impulso","portuguese":true,"instructions":["1. A posição inicial é em pé, com os pés na largura dos ombros.","2. As mãos devem segurar os halteres com pegada supinada, com as palmas voltadas para cima, na largura dos ombros.","3. Mantendo os cotovelos junto ao tronco durante todo o movimento, use o impulso para fazer a rosca com os halteres, contraindo o bíceps no topo.","4. Desça lentamente para voltar à posição inicial, mantendo o core firme durante todo o exercício.","O impulso na fase concêntrica dessa rosca desafiadora é uma ótima oportunidade de aumentar o tempo sob tensão e gerar sobrecarga excêntrica com cargas mais pesadas na descida."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["biceps"],"secondaryMuscles":[],"equipment":"dumbbell"},{"id":"wger-1483","source":"https://wger.de/en/exercise/1483/view/","name":"Trifeta de roscas para bíceps","portuguese":true,"instructions":["Este exercício é uma mistura de três roscas diferentes: a rosca cruzada supinada, a rosca cruzada pronada e a rosca no money. Você alterna entre três variações de rosca, cada uma com objetivos diferentes, e mantém a série além da faixa usual de 8 a 12 repetições, o que dá essa intensidade.","1. Para a rosca cruzada supinada, supine o antebraço com as palmas voltadas para cima e os antebraços cruzando o corpo; eleve a parte interna do halter em direção ao ombro.","2. Para a rosca cruzada pronada, prona o antebraço com as palmas voltadas para baixo, em pegada pronada, e os antebraços cruzando o corpo; eleve a parte interna do halter em direção ao ombro.","3. Para a rosca no money, faça a rosca enquanto roda o ombro para fora; eleve a parte interna do halter em direção à parte externa do ombro."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["biceps"],"secondaryMuscles":[],"equipment":"dumbbell"},{"id":"wger-1486","source":"https://wger.de/en/exercise/1486/view/","name":"Remada alternada na polia alta","portuguese":true,"instructions":["1. Comece colocando o acessório na posição alta da polia e afaste-se cerca de 1 m dele. Segure a alça da polia com a mão esquerda, na altura da cabeça, com o cotovelo levemente flexionado. Dê um passo atrás com o pé esquerdo.","2. Puxe o cotovelo em direção ao tronco, girando levemente o tronco, e faça uma remada unilateral. Ative o latíssimo ao girar.","3. Volte à posição inicial com a alça e o pé esquerdo e segure a alça com a mão direita. Repita o movimento do lado oposto, com o pé direito atrás."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["lats"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1487","source":"https://wger.de/en/exercise/1487/view/","name":"Combo Y e W na hiperextensão","portuguese":true,"instructions":["1. Use um banco de hiperextensão ou uma bola suíça para este exercício, com um disco leve em cada mão.","2. Eleve o tronco até formar uma linha reta com as pernas e eleve os braços para fora, um pouco além de 90 graus, na posição de W, para atingir os músculos do manguito rotador; depois volte à posição inicial.","3. Em seguida, eleve novamente com os braços na posição de Y, para ativar a porção inferior do trapézio."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["lats"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1492","source":"https://wger.de/en/exercise/1492/view/","name":"Remada na polia alta ajoelhado","portuguese":true,"instructions":["Ajoelhado sobre uma perna, puxe a polia para baixo levando o cotovelo em direção ao latíssimo."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["lats"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1493","source":"https://wger.de/en/exercise/1493/view/","name":"Rosca bayesiana na polia","portuguese":true,"instructions":["Rosca na polia com o ombro estendido para trás, o que alonga o bíceps na posição inicial."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["biceps"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1496","source":"https://wger.de/en/exercise/1496/view/","name":"Supino para peitoral superior com halter","portuguese":true,"instructions":["Com o halter na mão em pegada de rosca, incline o corpo em direção ao braço para ajudar a levar o halter para cima, acima do peito e ao lado da cabeça, ativando o conjunto peitoral e deltoide."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["chest"],"secondaryMuscles":["shoulders"],"equipment":"dumbbell"},{"id":"wger-1497","source":"https://wger.de/en/exercise/1497/view/","name":"Supino com halteres e pegada supinada","portuguese":true,"instructions":["Com pegada supinada nos halteres, execute o movimento normal de supino, mantendo os cotovelos próximos ao peito."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["chest"],"secondaryMuscles":["shoulders"],"equipment":"dumbbell"},{"id":"wger-1498","source":"https://wger.de/en/exercise/1498/view/","name":"Supino com halteres com cotovelos junto ao corpo","portuguese":true,"instructions":["Supino com halteres com os cotovelos junto ao corpo, um movimento de empurrar para o peito com foco no tríceps. Os halteres permanecem paralelos ao corpo."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["triceps"],"secondaryMuscles":["chest"],"equipment":"dumbbell"},{"id":"wger-1501","source":"https://wger.de/en/exercise/1501/view/","name":"Remada gorila com halteres","portuguese":true,"instructions":["Com o tronco levemente inclinado e os joelhos flexionados, imitando a posição de um gorila, puxe os halteres em direção ao peito. Os halteres permanecem retos, com os polegares apontando para cima."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["lats"],"secondaryMuscles":[],"equipment":"dumbbell"},{"id":"wger-1502","source":"https://wger.de/en/exercise/1502/view/","name":"Rosca martelo cruzada com halteres","portuguese":true,"instructions":["Rosca de bíceps com os halteres cruzando à frente do corpo, com pegada neutra, trabalhando o braquial."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["biceps"],"secondaryMuscles":[],"equipment":"dumbbell"},{"id":"wger-1503","source":"https://wger.de/en/exercise/1503/view/","name":"Elevação pélvica sapo com halter","portuguese":true,"instructions":["Semelhante à elevação pélvica, mas com os pés juntos, tirando o glúteo do chão em uma posição que lembra uma rã."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["glutes"],"secondaryMuscles":[],"equipment":"dumbbell"},{"id":"wger-1504","source":"https://wger.de/en/exercise/1504/view/","name":"Desenvolvimento Bradford com halteres","portuguese":true,"instructions":["Partindo da posição de espera frontal com os halteres, como no desenvolvimento militar, empurre os halteres acima da cabeça, leve-os para trás, em direção à parte posterior dos ombros, desça e empurre novamente para a frente."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["shoulders"],"secondaryMuscles":[],"equipment":"dumbbell"},{"id":"wger-1508","source":"https://wger.de/en/exercise/1508/view/","name":"Supino inclinado alto no smith","portuguese":true,"instructions":["Ajuste o banco em uma inclinação de 45 a 60 graus. Encoste a barra na parte superior do peito."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["shoulders","chest","triceps"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1509","source":"https://wger.de/en/exercise/1509/view/","name":"Coice de tríceps na polia","portuguese":true,"instructions":["Segure a alça e puxe o cotovelo para cima e para trás, um pouco acima do tronco. Mantenha o braço paralelo ao chão durante toda a série."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["triceps"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1511","source":"https://wger.de/en/exercise/1511/view/","name":"Rosca Kong","portuguese":true,"instructions":["Este exercício é um pouco parecido com uma rosca na polia e com um crossover na polia. Mas, em vez de ser um exercício de peito ou bíceps, ele trabalha o músculo braquial, responsável por aquele braço largo visto de frente.","Durante o exercício, mantenha o antebraço em posição pronada, partindo de cerca de 45 graus de pronação. Comece com os cotovelos levemente flexionados e faça a rosca alternando os braços até que as mãos (o polegar primeiro) se encontrem no meio da parte superior do peito, de forma semelhante a como o Kong bate no peito, daí o nome do exercício."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["biceps"],"secondaryMuscles":[],"equipment":"dumbbell"},{"id":"wger-1512","source":"https://wger.de/en/exercise/1512/view/","name":"Rosca drop","portuguese":true,"instructions":["A rosca drop, em uma posição modificada e em ritmo lento, recruta efetivamente o braquial para a largura do braço.","A posição inicial é com os dois braços em um leve ângulo um em direção ao outro, na altura do peito, com um halter em cada mão. Abaixe um halter quase até a extensão completa do braço, de forma lenta e controlada, na primeira metade da rosca, e depois faça a rosca de volta à posição inicial, enquanto o outro halter permanece na posição de partida. Em seguida, abaixe o outro halter. Isso mantém a tensão no braquial. Ao passar da marca de 90 graus no caminho de descida, o bíceps assume o trabalho."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["biceps"],"secondaryMuscles":[],"equipment":"dumbbell"},{"id":"wger-1514","source":"https://wger.de/en/exercise/1514/view/","name":"Caminhada lateral","portuguese":true,"instructions":["As caminhadas laterais, também conhecidas como passos laterais ou caminhada em agachamento, são um exercício em que você se desloca para o lado em posição de agachamento. Podem ser feitas com ou sem elástico. Esses exercícios fortalecem os abdutores do quadril, os glúteos e outros músculos estabilizadores."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["glutes"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1515","source":"https://wger.de/en/exercise/1515/view/","name":"Panturrilha no leg press (variação)","portuguese":true,"instructions":["Mova o leg press usando as panturrilhas, posicionando os pés na parte inferior da plataforma."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["calves"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1516","source":"https://wger.de/en/exercise/1516/view/","name":"Parada de mãos","portuguese":true,"instructions":["Parada de mãos livre, empurrando os braços contra o chão e contraindo o core e os glúteos."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["shoulders"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1524","source":"https://wger.de/en/exercise/1524/view/","name":"Cordas navais","portuguese":true,"instructions":["1. Segure as pontas da corda com os braços estendidos à frente, na altura dos quadris, e as mãos na largura dos ombros.","2. Contraia o core e comece a levantar e abaixar cada braço alternadamente, de forma explosiva.","3. Continue alternando os braços por três a quatro séries de 1 a 2 minutos."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["hamstrings","glutes","lats","quadriceps","abdominals"],"secondaryMuscles":["shoulders","biceps","chest","triceps"],"equipment":""},{"id":"wger-1525","source":"https://wger.de/en/exercise/1525/view/","name":"Arremesso de bola ao chão","portuguese":true,"instructions":["1. Fique em pé com os pés na largura dos ombros, joelhos e quadris levemente flexionados, segurando a bola com as duas mãos na altura do peito. Contraia o core e mantenha uma boa postura.","2. Estenda os joelhos e leve o quadril para frente enquanto levanta a bola ao mesmo tempo. Busque ficar o mais alto possível, com a bola acima da cabeça, os braços para cima, o quadril levemente à frente e os calcanhares fora do chão pela força do impulso.","3. Use o core e os braços para arremessar a medicine ball direto para o chão, entre os pés, com o máximo de força possível. Empurre o quadril para trás e flexione os joelhos para dar ainda mais potência ao arremesso. Expire ao arremessar a bola.","4. Agache para pegar a bola no chão e emende imediatamente o próximo arremesso, repetindo o movimento. Repita por repetições ou por tempo."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["lats","abdominals"],"secondaryMuscles":["shoulders","glutes"],"equipment":""},{"id":"wger-1531","source":"https://wger.de/en/exercise/1531/view/","name":"Rosca na polia","portuguese":true,"instructions":["Rosca de bíceps na polia. Pode ser feita sentado ou em pé."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["biceps"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1536","source":"https://wger.de/en/exercise/1536/view/","name":"Alongamento de deltoides","portuguese":true,"instructions":["Alongue os deltoides por um determinado período de tempo."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["shoulders"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1545","source":"https://wger.de/en/exercise/1545/view/","name":"Barra fixa arqueiro","portuguese":true,"instructions":["A barra fixa arqueiro é um exercício avançado com o peso do corpo que fortalece as costas e os bíceps, servindo de progressão para a barra fixa com um braço. O nome vem da posição de puxar o arco que o corpo assume no topo.","Para executar:","1. **Pegada:** segure a barra com pegada pronada mais aberta que a largura dos ombros.","2. **Posição inicial:** pendure-se com os braços totalmente estendidos, contraindo o core e mantendo as escápulas deprimidas.","3. **A puxada:** puxe o corpo para cima em direção a uma das mãos, como em uma barra fixa normal. Ao mesmo tempo, estenda o outro braço para o lado, mantendo-o o mais reto possível. Seu queixo deve ir em direção à mão que puxa.","4. **Segure e desça:** faça uma breve isometria no topo, com um braço flexionado puxando e o outro estendido. Desça lentamente de volta à posição inicial com controle.","5. **Alterne:** repita o movimento puxando em direção à mão oposta.","O ponto-chave é manter o braço de apoio o mais estendido possível para maximizar a carga sobre o braço que trabalha. Isso torna o exercício desafiador, mas eficaz para a força de puxada unilateral."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["lats"],"secondaryMuscles":["biceps"],"equipment":""},{"id":"wger-1546","source":"https://wger.de/en/exercise/1546/view/","name":"Supino Larsen","portuguese":true,"instructions":["Coloque as pernas sobre um banco separado e faça o supino sem impulso de pernas."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["chest"],"secondaryMuscles":["triceps"],"equipment":"barbell"},{"id":"wger-1554","source":"https://wger.de/en/exercise/1554/view/","name":"Flexão com palma","portuguese":true,"instructions":["A flexão com palma é um movimento explosivo de membros superiores que desenvolve potência e força das fibras de contração rápida. Ela acrescenta um desafio pliométrico à flexão tradicional, exigindo que as mãos saiam do chão no meio da repetição.","1. Comece em uma posição firme de flexão, com as mãos um pouco mais abertas que a largura dos ombros e o core contraído.","2. Desça o corpo de forma explosiva e empurre o chão com força suficiente para tirar as mãos do solo.","3. Bata palmas rapidamente na altura do peito antes de voltar as mãos ao chão.","4. Aterrisse com os cotovelos macios para absorver o impacto e emende imediatamente a próxima repetição."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["chest"],"secondaryMuscles":["shoulders","abdominals","triceps"],"equipment":""},{"id":"wger-1556","source":"https://wger.de/en/exercise/1556/view/","name":"Devil press","portuguese":true,"instructions":["O devil press é um movimento híbrido que combina o burpee com halteres e o snatch duplo com halteres. É um exercício de corpo inteiro e alta intensidade que desenvolve força, potência e condicionamento metabólico.","1. Comece com um halter em cada mão e execute um burpee, deixando o peito tocar o chão enquanto segura os halteres.","2. Salte com os pés para frente de forma explosiva e balance os halteres entre as pernas.","3. Leve os halteres acima da cabeça em um movimento contínuo, travando os braços.","4. Desça os halteres com controle para voltar à posição inicial e repita."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["shoulders","glutes","chest"],"secondaryMuscles":["hamstrings","lats","triceps"],"equipment":"dumbbell"},{"id":"wger-1567","source":"https://wger.de/en/exercise/1567/view/","name":"Rosca martelo alternada com halteres","portuguese":true,"instructions":["Fique em pé com os joelhos levemente flexionados e as costas retas. Segure um halter em cada mão, com pegada neutra, ao lado do corpo."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["biceps"],"secondaryMuscles":[],"equipment":"dumbbell"},{"id":"wger-1573","source":"https://wger.de/en/exercise/1573/view/","name":"Roda abdominal","portuguese":true,"instructions":["1. **Posição inicial:** ajoelhe-se no chão com a roda abdominal à sua frente.","2. **Pegada:** segure as alças com firmeza.","3. **Rolagem:** role a roda lentamente para frente, estendendo o corpo enquanto mantém o core firme.","4. **Retorno:** puxe a roda de volta em direção aos joelhos, mantendo a tensão no core."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["abdominals"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1577","source":"https://wger.de/en/exercise/1577/view/","name":"Alongamento bretzel","portuguese":true,"instructions":["Como fazer o alongamento bretzel.","1. **Posição inicial:** deite-se de costas em uma superfície plana, como um colchonete. Flexione os joelhos e apoie os pés no chão.","2. **Posicionamento das pernas:** levante a perna direita e cruze-a sobre a perna esquerda, apoiando o pé direito do lado de fora do joelho esquerdo. A perna esquerda deve permanecer estendida no chão.","3. **Posicionamento dos braços:** estenda o braço esquerdo para o lado na altura do ombro, mantendo-o reto. Use a mão direita para puxar suavemente o joelho direito em direção ao chão, do lado esquerdo do corpo.","4. **Alongamento:** ao puxar o joelho para baixo, procure manter o ombro esquerdo apoiado no chão. Você deve sentir o alongamento no quadril, na lombar e possivelmente no peito.","5. **Segure a posição:** mantenha-a por 20 a 30 segundos, respirando fundo e relaxando no alongamento. Troque de lado e repita o processo."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["glutes"],"secondaryMuscles":["hamstrings","lats","chest"],"equipment":""},{"id":"wger-1578","source":"https://wger.de/en/exercise/1578/view/","name":"Dobradiça de quadril","portuguese":true,"instructions":["A dobradiça de quadril é um padrão de movimento fundamental que consiste em flexionar o quadril mantendo a coluna neutra. Ela é usada comumente em exercícios como levantamento terra, swing com kettlebell e good morning.","Para executar:","1. **Posição inicial:** fique em pé com os pés na largura do quadril e os joelhos levemente flexionados.","2. **Dobradiça no quadril:** empurre o quadril para trás mantendo as costas retas. O tronco deve inclinar para frente e o peito deve permanecer aberto.","3. **Fase de descida:** continue a dobradiça até o tronco ficar quase paralelo ao chão, ou até sentir o alongamento nos posteriores de coxa.","4. **Retorno à posição em pé:** empurre com os calcanhares e leve o quadril para frente para voltar à posição inicial."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["hamstrings","glutes"],"secondaryMuscles":["calves","quadriceps","abdominals"],"equipment":"barbell"},{"id":"wger-1579","source":"https://wger.de/en/exercise/1579/view/","name":"Bronco","portuguese":true,"instructions":["Teste de condicionamento físico para rúgbi.","Cinco séries de idas e voltas de 20 m, 40 m e 60 m.","Complete o mais rápido possível."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":""},{"id":"wger-1589","source":"https://wger.de/en/exercise/1589/view/","name":"Alongamento de pernas e quadril","portuguese":true,"instructions":["Movimentos suaves para melhorar a flexibilidade da parte inferior do corpo e aliviar a tensão no quadril."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["hamstrings","glutes","quadriceps"],"secondaryMuscles":["lats"],"equipment":""},{"id":"wger-1590","source":"https://wger.de/en/exercise/1590/view/","name":"Alongamento de braços e pescoço","portuguese":true,"instructions":["Alivia tensões na parte superior do corpo, especialmente útil para quem trabalha em escritório ou passa muito tempo em posturas prolongadas."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["shoulders","triceps"],"secondaryMuscles":["lats"],"equipment":""},{"id":"Dumbbell_Scaption","source":"https://wger.de/en/exercise/1602/view/","name":"Elevação no plano escapular com halteres","portuguese":true,"instructions":["**Posição inicial:** Fique em pé com os pés afastados na largura dos ombros.","Segure um halter em cada mão com pegada neutra (palmas voltadas uma para a outra).","Mantenha os cotovelos levemente flexionados, os ombros relaxados e as escápulas puxadas para trás.","**Execução:** Eleve os halteres lentamente à frente e um pouco para o lado, num ângulo de cerca de 30 a 45 graus em relação ao corpo (entre uma elevação frontal e uma elevação lateral).","Suba até os braços ficarem aproximadamente na altura dos ombros, sem passar acima da cabeça.","Faça uma pausa de um segundo no topo e sinta a ativação nos ombros e nos estabilizadores escapulares.","Desça os halteres com controle até a posição inicial.","**Respiração:** Inspire ao descer os halteres.","Expire ao subi-los.","**Erros comuns:** Usar halteres pesados demais, o que gera movimentos bruscos.","Elevar acima da altura dos ombros, o que sobrecarrega desnecessariamente a articulação.","Arquear a lombar em vez de manter o movimento controlado nos ombros.","**Objetivo do exercício:** Ativar o trapézio inferior, o serrátil anterior e os estabilizadores escapulares, ajudando a corrigir a postura e a melhorar o equilíbrio dos ombros."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}},{"id":"wger-1603","source":"https://wger.de/en/exercise/1603/view/","name":"Flexão de joelhos com elástico","portuguese":true,"instructions":["**Em pé:** Posicione o elástico sob a planta do pé, na parte média do pé, e segure-o com pegada martelo."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["calves"],"secondaryMuscles":["hamstrings"],"equipment":""},{"id":"wger-1605","source":"https://wger.de/en/exercise/1605/view/","name":"Adução de adutores Copenhagen","portuguese":true,"instructions":["Deite-se de lado com o cotovelo apoiado diretamente abaixo do ombro, como na posição de prancha lateral. Apoie a perna de cima sobre um banco, com a parte interna do pé ou o tornozelo em contato com ele. Eleve o quadril e mantenha o corpo em linha reta, com a perna de baixo fora do chão. O exercício ativa fortemente os adutores da perna de cima e também desafia o core e os estabilizadores do quadril."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["glutes","quadriceps"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1606","source":"https://wger.de/en/exercise/1606/view/","name":"Elevação de braços em T, Y e I","portuguese":true,"instructions":["Fique em pé com os pés na largura do quadril, core firme e braços relaxados ao lado do corpo. A partir dessa posição, faça três tipos de elevação de braços para trabalhar os ombros e a parte superior das costas.","- **Elevação em T:** Suba os braços estendidos para os lados até ficarem paralelos ao chão, formando um T.","- **Elevação em Y:** Suba os braços num ângulo de cerca de 45 graus em relação ao corpo, formando um Y.","- **Elevação em I:** Suba os braços estendidos acima da cabeça, bem juntos, formando um I.","Mantenha a coluna neutra, evite arquear a lombar e mova-se devagar e com controle. Concentre-se em juntar as escápulas e manter os ombros longe das orelhas."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["shoulders","lats"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1608","source":"https://wger.de/en/exercise/1608/view/","name":"Rosca bíceps com peso corporal","portuguese":true,"instructions":["Posicione-se sob uma barra reta, na altura da cintura ou do peito. Segure a barra com as palmas voltadas para você (pegada supinada), com as mãos na largura dos ombros. Incline o corpo para trás com os braços estendidos, de modo que o tronco fique angulado em relação ao chão. Mantendo os cotovelos altos e próximos da barra, puxe o corpo em direção à barra flexionando os cotovelos, como numa rosca bíceps. Desça de volta de forma controlada. Mantenha o core firme e o movimento lento para maximizar a tensão no bíceps."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["biceps"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1618","source":"https://wger.de/en/exercise/1618/view/","name":"Cardio na bicicleta estática","portuguese":true,"instructions":["**Benefícios do cardio na bicicleta estática:** O cardio na bicicleta estática é uma excelente forma de exercício, com múltiplos benefícios para a saúde e o bem-estar. Entre os principais:","**Melhora da saúde cardiovascular:** Fortalece o coração — o exercício regular melhora a eficiência cardíaca e reduz o risco de doenças cardiovasculares — e aumenta a circulação, melhorando o fluxo sanguíneo, o que pode ajudar a reduzir a pressão arterial.","**Queima de calorias e perda de peso:** É eficiente para queimar calorias, com gasto de 400 a 600 calorias por hora dependendo da intensidade, e, combinado com uma dieta equilibrada, pode ser eficaz para emagrecer.","**Fortalecimento muscular:** Tonifica as pernas, trabalhando principalmente quadríceps, isquiotibiais e panturrilhas, e melhora a resistência muscular, aumentando com o tempo a resistência e a força nas pernas.","**Benefícios para a saúde mental:** Reduz o estresse, pois o exercício libera endorfina, que melhora o humor e reduz a tensão, e aumenta a energia, já que a atividade física regular eleva os níveis de energia e melhora a qualidade do sono."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":""},{"id":"wger-1630","source":"https://wger.de/en/exercise/1630/view/","name":"Blaze","portuguese":true,"instructions":["BLAZE é um treino HIIT de corpo inteiro, criado para turbinar o condicionamento cardiovascular e a força. Realizado em um estúdio próprio, o BLAZE é uma combinação única de artes marciais, cardio intenso e treino de força."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["shoulders","glutes","chest","quadriceps"],"secondaryMuscles":["biceps","hamstrings","lats","abdominals"],"equipment":"dumbbell"},{"id":"wger-1638","source":"https://wger.de/en/exercise/1638/view/","name":"Arremesso e desenvolvimento com barra","portuguese":true,"instructions":["O exercício consiste em levar a barra do chão até os ombros e, em seguida, empurrá-la acima da cabeça. É um movimento composto que trabalha diversos grupos musculares, incluindo pernas, costas, ombros e braços. Costuma ser usado em programas de força e condicionamento para melhorar a potência e o desempenho atlético em geral."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["shoulders","chest"],"secondaryMuscles":[],"equipment":"dumbbell"},{"id":"wger-1639","source":"https://wger.de/en/exercise/1639/view/","name":"Puxada de halteres para o rosto curvado","portuguese":true,"instructions":["O exercício usa halteres para fazer uma puxada em direção ao rosto com o tronco inclinado, trabalhando a parte superior das costas e os ombros. O movimento consiste em puxar os pesos na direção do rosto, mantendo os cotovelos altos e aproximando as escápulas."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["shoulders","lats"],"secondaryMuscles":[],"equipment":"dumbbell"},{"id":"wger-1640","source":"https://wger.de/en/exercise/1640/view/","name":"Agachamento frontal com halteres","portuguese":true,"instructions":["O exercício consiste em segurar um halter em cada mão na altura dos ombros e executar um agachamento. Trabalha os músculos da parte inferior do corpo, incluindo quadríceps, isquiotibiais e glúteos, e também recruta o core e a parte superior do corpo."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["glutes","quadriceps"],"secondaryMuscles":["shoulders","abdominals"],"equipment":"dumbbell"},{"id":"Kettlebell_One-Legged_Deadlift","source":"https://wger.de/en/exercise/1641/view/","name":"Terra unilateral com kettlebell","portuguese":true,"instructions":["O exercício consiste em segurar um kettlebell com uma das mãos e ficar apoiado em uma perna, inclinando o tronco à frente até encostar o kettlebell no chão. Trabalha isquiotibiais, glúteos e lombar, além de melhorar equilíbrio e estabilidade."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}},{"id":"wger-1642","source":"https://wger.de/en/exercise/1642/view/","name":"Elevação pélvica com halter (variação)","portuguese":true,"instructions":["O exercício consiste em sentar-se no chão com um halter apoiado sobre o quadril e, então, empurrar o quadril para cima apertando os glúteos. É ótimo para fortalecer os glúteos e melhorar a mobilidade do quadril."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["glutes","quadriceps"],"secondaryMuscles":[],"equipment":"dumbbell"},{"id":"Dumbbell_Side_Bend","source":"https://wger.de/en/exercise/1650/view/","name":"Flexão lateral com halter","portuguese":true,"instructions":["O exercício consiste em segurar um halter com uma das mãos e inclinar o tronco para o lado, trabalhando os oblíquos. Pode ser feito em pé ou sentado e costuma ser usado para fortalecer o core."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}},{"id":"Dumbbell_Rear_Lunge","source":"https://wger.de/en/exercise/1651/view/","name":"Afundo para trás com halteres","portuguese":true,"instructions":["O exercício consiste em segurar um halter em cada mão e dar um passo para trás entrando na posição de afundo, depois voltar a ficar em pé. Trabalha principalmente glúteos, isquiotibiais e quadríceps."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}},{"id":"wger-1652","source":"https://wger.de/en/exercise/1652/view/","name":"Terra romeno com halteres","portuguese":true,"instructions":["O exercício consiste em segurar um halter em cada mão e inclinar o tronco à frente a partir do quadril, mantendo as costas retas, e depois voltar à posição em pé. Trabalha principalmente isquiotibiais e glúteos."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["hamstrings","glutes"],"secondaryMuscles":[],"equipment":"dumbbell"},{"id":"wger-1653","source":"https://wger.de/en/exercise/1653/view/","name":"Agachamento lateral com halter","portuguese":true,"instructions":["O exercício consiste em segurar um halter com uma das mãos e executar um agachamento dando um passo para o lado. Trabalha pernas, glúteos e core."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["glutes","quadriceps"],"secondaryMuscles":["hamstrings"],"equipment":""},{"id":"wger-1654","source":"https://wger.de/en/exercise/1654/view/","name":"Elevação lateral na mãquina","portuguese":true,"instructions":["A elevação lateral na máquina é um exercício isolado que trabalha o músculo deltoide medial (lateral) para construir ombros mais largos e definidos. O caminho de movimento fixo da máquina proporciona maior estabilidade do que com halteres, tornando-a ideal para iniciantes ou para aqueles que desejam se concentrar apenas na ativação muscular."],"credit":{"author":"roneydya","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["shoulders"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1656","source":"https://wger.de/en/exercise/1656/view/","name":"Supino declinado unilateral na polia","portuguese":true,"instructions":["Supino unilateral feito na polia. Use o outro braço para apoiar o peso do corpo e concentrar-se na força do empurrão, em vez de no equilíbrio do corpo. Comece com a mão o mais próximo possível do peito e empurre contra a polia num leve declínio, mirando o centro do peito."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["chest"],"secondaryMuscles":["triceps"],"equipment":""},{"id":"wger-1659","source":"https://wger.de/en/exercise/1659/view/","name":"Puxada alta cruzada unilateral","portuguese":true,"instructions":["Sente-se na máquina de puxada alta com o corpo em ângulo diagonal, de modo que apenas uma perna fique sob o apoio. Puxe o cabo para baixo com o braço oposto, o que faz o cabo atravessar o corpo durante a puxada. Enfatiza o alongamento do grande dorsal."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["lats"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1660","source":"https://wger.de/en/exercise/1660/view/","name":"Supino inclinado na polia","portuguese":true,"instructions":["Supino unilateral feito na máquina de polia. Use o outro braço para apoiar o peso do corpo e focar na força do empurrão, em vez de no equilíbrio do tronco. Comece com a mão o mais próxima possível do peito e empurre contra o cabo num leve ângulo inclinado, mirando o centro do peito."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["chest"],"secondaryMuscles":["triceps"],"equipment":""},{"id":"wger-1661","source":"https://wger.de/en/exercise/1661/view/","name":"Extensão de tríceps na polia","portuguese":true,"instructions":["Exercício unilateral que começa com a mão próxima do peito, cotovelo flexionado e aberto para fora. Empurre para frente e para baixo contra o cabo, estendendo o cotovelo."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["triceps"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1662","source":"https://wger.de/en/exercise/1662/view/","name":"Extensão de tríceps na polia com rotação interna","portuguese":true,"instructions":["Exercício unilateral com o cabo segurado na altura do ombro oposto e o cotovelo flexionado. Gire em direção ao cabo e então estenda o cotovelo atravessando o corpo."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["triceps"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1666","source":"https://wger.de/en/exercise/1666/view/","name":"Rosca com ombro elevado","portuguese":true,"instructions":["Posicione o cotovelo mais ou menos na altura do ombro. Faça a rosca levando o peso até o ombro. Foque no alongamento na fase excêntrica da rosca."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["biceps"],"secondaryMuscles":[],"equipment":"dumbbell"},{"id":"wger-1670","source":"https://wger.de/en/exercise/1670/view/","name":"Círculos de perna (frente-trás)","portuguese":true,"instructions":["Fique em pé ao lado de uma parede ou apoio estável. Balance uma perna para frente e para trás em movimento controlado, mantendo o tronco ereto e o abdômen contraído. Troque de perna após completar as repetições."],"credit":{"author":"Jhonatan","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["hamstrings"],"secondaryMuscles":["glutes","quadriceps"],"equipment":""},{"id":"wger-1684","source":"https://wger.de/en/exercise/1684/view/","name":"Thruster com halteres","portuguese":true,"instructions":["Comece com os halteres apoiados nos ombros e agache. Estenda as pernas até ficar em pé e eleve os halteres até a posição acima da cabeça. Traga os halteres de volta aos ombros e repita."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["hamstrings","glutes","quadriceps"],"secondaryMuscles":["shoulders"],"equipment":"dumbbell"},{"id":"wger-1686","source":"https://wger.de/en/exercise/1686/view/","name":"Elevação pélvica com supino unilateral","portuguese":true,"instructions":["Com um halter em uma das mãos, faça a elevação pélvica. Segure o halter acima do peito; essa é a posição inicial da repetição. Desça o halter até o cotovelo tocar o chão ou ficar cerca de 45 graus abaixo do ombro, caso esteja usando um banco. Empurre o halter de volta à posição inicial."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["chest"],"secondaryMuscles":["shoulders","biceps","hamstrings","glutes","triceps"],"equipment":"dumbbell"},{"id":"wger-1687","source":"https://wger.de/en/exercise/1687/view/","name":"Puxada lateral em posição de urso","portuguese":true,"instructions":["Coloque um halter mais ou menos na altura do quadril e assuma a posição de urso, em quatro apoios. Tire os joelhos do chão e mantenha a posição.","Com a mão oposta, alcance o halter e puxe-o para o outro lado. Volte a mão ao chão e repita com a outra mão."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["shoulders","glutes","quadriceps","abdominals"],"secondaryMuscles":["hamstrings","calves"],"equipment":"dumbbell"},{"id":"wger-1688","source":"https://wger.de/en/exercise/1688/view/","name":"Terra romeno com apoio do pé","portuguese":true,"instructions":["Use a ponta do pé da perna que não trabalha para ajudar no equilíbrio e execute um levantamento terra romeno."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["hamstrings"],"secondaryMuscles":[],"equipment":"barbell"},{"id":"wger-1689","source":"https://wger.de/en/exercise/1689/view/","name":"Crucifixo na polia para peitoral médio","portuguese":true,"instructions":["**Execução**","1. **Posição inicial:** braços estendidos para os lados, formando um grande T, sentindo o alongamento no peito.","2. **Movimento:** junte as mãos à frente do peito num movimento amplo de abraço.","- Concentre-se em contrair o peito no centro.","- Não trave os cotovelos nem transforme o movimento em um supino.","3. **Retorno:** abra os braços lentamente de volta à posição inicial, mantendo a tensão no peito."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["chest"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1690","source":"https://wger.de/en/exercise/1690/view/","name":"Crucifixo na polia para peitoral superior","portuguese":true,"instructions":["**Execução**","1. **Posição inicial:**","- Braços para baixo e um pouco atrás do corpo, cotovelos levemente flexionados.","- Sinta um leve alongamento no peito.","2. **Movimento:**","- Leve as mãos para cima e junte-as à frente da parte superior do peito, mais ou menos na altura do queixo ao osso da clavícula.","- Use um movimento suave e controlado, sem trancos.","- Contraia o peito no alto por 1 a 2 segundos.","3. **Retorno:**","- Deixe os braços descerem lentamente e se abrirem para os lados, mantendo o controle e a tensão."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["chest"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1691","source":"https://wger.de/en/exercise/1691/view/","name":"Crucifixo na polia para peitoral inferior","portuguese":true,"instructions":["**Execução**","1. **Posição inicial:**","- Braços estendidos para os lados em forma de Y.","- Sinta o alongamento no peito, com os cotovelos levemente flexionados e sem travá-los.","2. **Movimento:**","- Leve as mãos para baixo e junte-as à frente da parte inferior do peito ou da parte alta do abdômen, num arco suave.","- Contraia o peito com força na parte de baixo por 1 a 2 segundos.","3. **Retorno:**","- Eleve os braços lentamente de volta pelo mesmo caminho até sentir um bom alongamento no peito.","- Mantenha o controle, sem deixar o peso puxar você de volta rápido demais."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["chest"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1693","source":"https://wger.de/en/exercise/1693/view/","name":"Isometria no supino inclinado","portuguese":true,"instructions":["**Execução**","1. **Posição de sustentação:**","- Desça os halteres até alguns centímetros acima do peito, mais ou menos no ponto médio de um supino inclinado normal.","- É aí que a parte superior do peito fica sob tensão máxima.","2. **Sustentação estática:**","- Mantenha a posição por 20 a 45 segundos com o peito contraído.","- Respire devagar, mas continue tenso, sem relaxar o peito nem os ombros.","3. **Fim da série:**","- Após a sustentação, desça os halteres com cuidado e descanse."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["chest"],"secondaryMuscles":[],"equipment":"dumbbell"},{"id":"wger-1694","source":"https://wger.de/en/exercise/1694/view/","name":"Supino reto na máquina","portuguese":true,"instructions":["**Execução**","1. **Posição inicial:**","- Cotovelos flexionados a cerca de 90 graus, mãos um pouco para fora do peito.","- Mantenha os punhos retos e alinhados com os antebraços.","2. **Fase de empurrar (concêntrica):**","- Empurre as pegadas para frente até os braços ficarem quase totalmente estendidos, sem travar.","- Concentre-se em contrair o peito no final do movimento.","3. **Fase de retorno (excêntrica):**","- Traga as pegadas de volta em direção ao peito lentamente, sentindo o alongamento nos peitorais.","- Mantenha a tensão, sem deixar a pilha de peso encostar entre as repetições."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["chest"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1698","source":"https://wger.de/en/exercise/1698/view/","name":"Remada curvada com pegada pronada","portuguese":true,"instructions":["**Execução**","1. **Posição inicial:**","- Segure a barra com os braços totalmente estendidos na direção do chão.","- Mantenha a tensão nos dorsais e nos músculos das costas."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["lats"],"secondaryMuscles":[],"equipment":"barbell"},{"id":"wger-1699","source":"https://wger.de/en/exercise/1699/view/","name":"Remada curvada com pegada supinada","portuguese":true,"instructions":["**Execução**","1. **Posição inicial:**","- Segure a barra com os braços totalmente estendidos na direção do chão.","- Mantenha a tensão nos dorsais e nos músculos das costas."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["lats"],"secondaryMuscles":[],"equipment":"barbell"},{"id":"wger-1700","source":"https://wger.de/en/exercise/1700/view/","name":"Terra romeno com barra","portuguese":true,"instructions":["**Execução:**","1. Faça a dobradiça no quadril:","- Empurre o **quadril para trás**, mantendo leve flexão dos joelhos (joelhos macios).","- Desça a barra **rente à frente das coxas e canelas**, mantendo a coluna neutra.","- Mantenha a barra **próxima ao corpo**."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["hamstrings","glutes"],"secondaryMuscles":[],"equipment":"barbell"},{"id":"wger-1702","source":"https://wger.de/en/exercise/1702/view/","name":"Puxada alta com pegada aberta (variação)","portuguese":true,"instructions":["A puxada alta é um exercício de tração que tem como alvo principal o grande dorsal (popularmente chamado de dorsal) nas costas. Consiste em puxar uma barra ou puxador de polia para baixo, em direção ao peito, sentado em uma máquina específica para esse exercício. A puxada alta costuma ser feita com pegada aberta, mas também pode ser executada com pegada fechada ou supinada, para atingir grupos musculares diferentes nas costas e nos braços. É um exercício popular para ganhar força na parte superior do corpo e melhorar a postura."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["lats"],"secondaryMuscles":["biceps"],"equipment":""},{"id":"wger-1706","source":"https://wger.de/en/exercise/1706/view/","name":"Agachamento búlgaro com halteres","portuguese":true,"instructions":["O agachamento búlgaro consiste em agachar com uma perna só, com o pé de trás apoiado em uma plataforma elevada. Elevar a perna de trás em um banco cria instabilidade e aumenta a amplitude de movimento do exercício."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["glutes","quadriceps"],"secondaryMuscles":["hamstrings"],"equipment":"dumbbell"},{"id":"wger-1710","source":"https://wger.de/en/exercise/1710/view/","name":"Alongamento de ombros ajoelhado","portuguese":true,"instructions":["1. Ajoelhe-se com as mãos juntas.","2. Apoie os cotovelos em um banco à sua frente e desça o peito.","3. Mantenha os cotovelos flexionados, com postura correta, e segure a posição."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["lats"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1712","source":"https://wger.de/en/exercise/1712/view/","name":"Alongamento de flexão horizontal do ombro","portuguese":true,"instructions":["1. Eleve o braço para o lado e apoie a mão em uma parede ou batente ao seu lado, na altura do ombro.","2. Gire o corpo para longe do braço para alongar o peito, até onde for confortável."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["chest"],"secondaryMuscles":["shoulders"],"equipment":""},{"id":"wger-1713","source":"https://wger.de/en/exercise/1713/view/","name":"Alongamento de peitoral no batente","portuguese":true,"instructions":["1. Apoie o antebraço na vertical em um batente de porta ou objeto fixo, na altura da cabeça.","2. Dê um passo à frente, passando do braço, mantendo-o apoiado no objeto para alongar o peito."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["chest"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1716","source":"https://wger.de/en/exercise/1716/view/","name":"Flexão escapular inclinada","portuguese":true,"instructions":["1. Apoie as mãos no banco na posição de flexão.","2. Empurre o peito para longe do banco para separar as escápulas.","3. **Mantendo os cotovelos estendidos**, desça o peito em direção ao banco para que as escápulas se aproximem.","4. Empurre o peito para longe do banco novamente."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["shoulders","chest"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1723","source":"https://wger.de/en/exercise/1723/view/","name":"Coice de glúteo na máquina","portuguese":true,"instructions":["Empurre com o calcanhar, não com os dedos dos pés, para atingir o glúteo.","Não hiperextenda a lombar no topo do movimento."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["glutes"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1731","source":"https://wger.de/en/exercise/1731/view/","name":"Elevação frontal na polia","portuguese":true,"instructions":["Eleve o puxador em um leve arco, com movimento controlado.","Não balance o tronco para iniciar a repetição."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["shoulders"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1732","source":"https://wger.de/en/exercise/1732/view/","name":"Puxada facial com elástico amarelo/verde","portuguese":true,"instructions":["Puxada facial com elástico: puxada horizontal em pé. Segure o elástico na altura do rosto e puxe os cotovelos altos e afastados em direção ao rosto, aproximando as escápulas. Trabalha a parte superior das costas, a parte posterior dos ombros e melhora a postura."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["lats"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1733","source":"https://wger.de/en/exercise/1733/view/","name":"Agachamento isométrico até a falha","portuguese":true,"instructions":["**Definição:**","O agachamento isométrico até a falha é uma variação do agachamento em que você mantém uma posição estática, em um ângulo específico, sustentando a posição até os músculos não conseguirem mais manter a contração."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["glutes","quadriceps"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1737","source":"https://wger.de/en/exercise/1737/view/","name":"Barra fixa assistida","portuguese":true,"instructions":["Barra fixa com assistência de máquina (contrapesos)."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["biceps","lats"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1741","source":"https://wger.de/en/exercise/1741/view/","name":"Barra fixa em L","portuguese":true,"instructions":["Exercício na barra fixa em que as pernas ficam estendidas à frente, formando um L; treina tanto a parte superior do corpo quanto o core."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["lats"],"secondaryMuscles":["biceps","abdominals"],"equipment":""},{"id":"wger-1742","source":"https://wger.de/en/exercise/1742/view/","name":"Alavanca traseira na barra fixa","portuguese":true,"instructions":["Suspenso na barra fixa, com o rosto voltado para baixo e os braços estendidos."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":"body only"},{"id":"wger-1745","source":"https://wger.de/en/exercise/1745/view/","name":"Elevação frontal na polia com barra pequena","portuguese":true,"instructions":["A elevação frontal com barra pequena na polia isola os deltoides anteriores (frente dos ombros) ao fornecer tensão constante: você fica de costas para uma polia baixa, segura a barra com pegada pronada e a eleva à frente até a altura dos ombros, com os braços levemente flexionados, evitando balançar o corpo e mantendo o core firme para um movimento controlado na subida e na descida. Use uma carga leve a moderada, com repetições lentas e controladas, para sentir o músculo trabalhar em vez do impulso.","**Para executar:**","**Preparação:** prenda uma barra reta pequena em uma polia baixa e ajuste a carga para leve ou moderada.","**Posição inicial:** fique de costas para a máquina, segurando a barra com pegada pronada (palmas para baixo) na altura do quadril, braços estendidos mas não travados, pés na largura dos ombros, core firme e ombros para trás e para baixo.","**A subida:** expire e eleve a barra lentamente à frente, mantendo leve flexão nos cotovelos, até as mãos chegarem à altura dos ombros (ou pouco abaixo).","**A pausa:** faça uma breve pausa no topo, contraindo os deltoides anteriores.","**A descida:** inspire e desça a barra lenta e controladamente até a posição inicial, mantendo a tensão."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["shoulders"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1751","source":"https://wger.de/en/exercise/1751/view/","name":"Puxada entre as pernas na polia","portuguese":true,"instructions":["A **puxada entre as pernas na polia** é um exercício para a parte inferior do corpo que trabalha glúteos e posteriores de coxa usando o movimento de dobradiça de quadril. Para executá-la, prenda uma corda na polia mais baixa, fique de costas para a máquina com a corda entre as pernas e dê um passo à frente para criar tensão. Mantendo as costas retas e os joelhos levemente flexionados, empurre o quadril para trás como se quisesse fechar uma porta atrás de você, até sentir um alongamento profundo nos posteriores de coxa.","Para completar a repetição, leve o quadril à frente com força para voltar à posição em pé, contraindo bem os glúteos no topo. É essencial lembrar que este **não é um agachamento**: os joelhos não devem flexionar profundamente e os braços devem ficar estendidos e relaxados, servindo apenas de gancho para a corda. O movimento mantém tensão constante nos glúteos e gera menos sobrecarga na lombar do que o terra tradicional."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["glutes"],"secondaryMuscles":["hamstrings","calves","quadriceps"],"equipment":""},{"id":"wger-1754","source":"https://wger.de/en/exercise/1754/view/","name":"Elevação lateral 45 graus","portuguese":true,"instructions":["Elevação com halteres em um ângulo intermediário entre a elevação frontal e a elevação lateral."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":"dumbbell"},{"id":"wger-1773","source":"https://wger.de/en/exercise/1773/view/","name":"Supino inclinado na máquina Legend","portuguese":true,"instructions":["Supino inclinado na máquina LeverEdge. Ajuste o banco, destrave e empurre até estender os braços."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"equipment":""},{"id":"wger-1774","source":"https://wger.de/en/exercise/1774/view/","name":"Mergulho na cadeira","portuguese":true,"instructions":["**Posição inicial:** sente-se na borda da frente de uma cadeira, com as costas retas e as mãos segurando a borda frontal. Ainda segurando a borda da cadeira, com os braços estendidos, levante o quadril e ande um pouco para a frente, de modo que ele fique a alguns centímetros da cadeira.","**Execução:**","1. Desça o corpo lentamente, mantendo as costas retas, até os braços formarem um ângulo reto.","2. Suba o corpo novamente até a posição inicial, com os braços estendidos.","3. Repita."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["triceps"],"secondaryMuscles":["shoulders","chest"],"equipment":""},{"id":"wger-1777","source":"https://wger.de/en/exercise/1777/view/","name":"Flexão com déficit","portuguese":true,"instructions":["Faça a flexão com as mãos apoiadas em blocos ou pegadores, o que permite descer mais do que a linha das mãos na fase excêntrica."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["chest"],"secondaryMuscles":["triceps"],"equipment":""},{"id":"wger-1779","source":"https://wger.de/en/exercise/1779/view/","name":"Rotação com barra ancorada","portuguese":true,"instructions":["Comece com a barra ancorada na posição vertical, empurrando-a para cima com os ombros até que fique acima de você. A partir dessa posição, leve a barra para o lado para trabalhar o abdômen e retorne à posição inicial."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":["shoulders","abdominals"],"equipment":"barbell"},{"id":"Barbell_Full_Squat","source":"https://wger.de/en/exercise/1801/view/","name":"Agachamento completo com barra","portuguese":true,"instructions":["- O agachamento completo com barra é um **exercício composto** que **recruta vários grupos musculares** da parte inferior do corpo, entre eles quadríceps, posteriores de coxa e glúteos.","- A execução correta é essencial para maximizar os resultados e prevenir lesões, o que inclui manter os pés na largura dos ombros, gerar tensão no corpo inteiro, controlar a descida e preservar a profundidade adequada e o posicionamento dos joelhos.","- Movimentos auxiliares como agachamento frontal, agachamento goblet, agachamento dividido e agachamento dividido búlgaro ajudam a melhorar o desempenho no agachamento completo, por trabalharem grupos musculares específicos e aperfeiçoarem a técnica.","- Para **alcançar novos recordes pessoais** no agachamento, aumente a carga de forma gradual ao longo do tempo, varie as faixas de repetições e as séries para estimular o crescimento muscular e **priorize o descanso e a recuperação** entre as sessões de treino."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}},{"id":"wger-1807","source":"https://wger.de/en/exercise/1807/view/","name":"Elevação lateral na polia por trás do corpo","portuguese":true,"instructions":["A elevação lateral há muito tempo é um exercício básico para construir deltoides arredondados, e os praticantes usam desde halteres e elásticos até máquinas e variações unilaterais para fazê-los crescer."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["shoulders"],"secondaryMuscles":[],"equipment":""},{"id":"Reverse_Hyperextension","source":"https://wger.de/en/exercise/1809/view/","name":"Hiperextensão reversa","portuguese":true,"instructions":["Deite-se de bruços em um banco, com as pernas para fora da borda.","1. Flexione o quadril de modo que as coxas fiquem na vertical, dobrando os joelhos ao mesmo tempo para que as canelas fiquem na horizontal.","2. Estenda as pernas até ficarem retas, com as pontas dos pés apontando para trás na horizontal.","3. Volte à posição inicial e repita."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}},{"id":"wger-1823","source":"https://wger.de/en/exercise/1823/view/","name":"Concha","portuguese":true,"instructions":["**Posição:** Deite-se de lado com o cotovelo e o antebraço apoiados no chão e as pernas levemente flexionadas.","**Execução:** Eleve o joelho de cima mantendo os pés unidos, como uma concha se abrindo, e depois volte lentamente à posição inicial. Mantenha o core estável e o quadril alinhado."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["glutes","abdominals"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1824","source":"https://wger.de/en/exercise/1824/view/","name":"Tate press com halteres","portuguese":true,"instructions":["1. **Preparação:** Deite-se de costas com um halter em cada mão e estenda os braços para cima, sobre o peito, como se estivesse na fase alta do supino com halteres.","2. **Posição inicial:** Posicione os halteres encostados ou bem próximos um do outro, com pegada pronada (palmas voltadas para os pés e polegares apontados um para o outro).","3. **Descida:** Sem mover os braços nem os ombros, flexione os cotovelos e abra-os para as laterais, descendo as extremidades internas dos halteres na direção do centro do peito.","4. **Toque e pausa:** Encoste os halteres suavemente no peito, sem apoiar o peso no corpo, mantendo tensão constante no tríceps.","5. **Pressão:** Estenda os cotovelos com força para devolver os halteres à posição inicial, concentrando-se em empurrar os dedos mínimos para o céu para maximizar o recrutamento do tríceps.","Vídeo: https://www.youtube.com/watch?v=IgSjoXbpy1M&t=2"],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["triceps"],"secondaryMuscles":["shoulders","chest"],"equipment":"dumbbell"},{"id":"wger-1825","source":"https://wger.de/en/exercise/1825/view/","name":"Elevação posterior com apoio no peito","portuguese":true,"instructions":["**Posição em Y:** Ajuste um banco inclinado a 30–45 graus e deite-se de bruços com o peito apoiado, mantendo a cabeça neutra ou olhando levemente para baixo para evitar tensão no pescoço.","**Pegada:** Segure halteres leves com pegada neutra ou com o polegar para cima (polegar apontando para o teto).","**Movimento:** Com os cotovelos estendidos ou levemente flexionados, eleve os halteres para cima e para fora, formando um Y, concentrando-se em mover os ombros e as escápulas, não apenas os braços.","**Posição alta:** Aperte as escápulas e alcance o mais alto possível, mantendo os braços angulados em Y.","**Controle:** Desça os halteres lentamente até a posição inicial."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["shoulders"],"secondaryMuscles":[],"equipment":"dumbbell"},{"id":"wger-1826","source":"https://wger.de/en/exercise/1826/view/","name":"Abertura de elástico com rotação externa","portuguese":true,"instructions":["Fique em pé com os pés na largura dos ombros, peito aberto e ombros para trás.","Segure a faixa elástica com as duas mãos, com as palmas para cima ou voltadas uma para a outra, dependendo do tipo de elástico.","Flexione os cotovelos a 90 graus e mantenha os braços colados ao tronco.","O elástico deve ter alguma tensão na posição inicial, com as mãos mais próximas à frente do abdômen.","**Gire para fora:** Mantendo os cotovelos junto ao corpo, afaste lentamente as mãos, esticando o elástico.","**Contração:** Aperte as escápulas para baixo e para trás enquanto gira as mãos para fora.","**Amplitude:** Gire as mãos o máximo que conseguir com conforto, sem deixar os cotovelos saírem do tronco.","**Pausa:** Segure a posição final por 1–2 segundos para maximizar o recrutamento muscular.","**Retorno:** Retorne lentamente, com controle, à posição inicial."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["shoulders"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1827","source":"https://wger.de/en/exercise/1827/view/","name":"Pressão abdominal contra os joelhos","portuguese":true,"instructions":["Deite-se de costas com joelhos e quadris flexionados a 90 graus, na posição de mesa.","Coloque as mãos sobre as coxas, logo acima dos joelhos, e empurre as mãos contra os joelhos o mais forte que puder, enquanto usa o abdômen para puxar os joelhos na direção das mãos.","Mantenha por 10 segundos com esforço máximo; o abdômen deve tremer."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["abdominals"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1828","source":"https://wger.de/en/exercise/1828/view/","name":"Retração abdominal","portuguese":true,"instructions":["Deite-se de costas com os joelhos flexionados. Puxe suavemente o umbigo em direção à coluna, sem mover o quadril e sem prender a respiração."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["abdominals"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1829","source":"https://wger.de/en/exercise/1829/view/","name":"Agachamento e desenvolvimento com barra ancorada","portuguese":true,"instructions":["**Posição da barra:** ancore uma das pontas da barra em um suporte apropriado ou em um canto firme.","**Base:** Fique de frente para a barra com os pés um pouco mais afastados que a largura dos ombros e as pontas dos pés viradas para fora em 10–35 graus, o que permite melhor movimento pélvico e profundidade.","**Pegada:** Segure a extremidade livre da barra com as duas mãos (dedos entrelaçados ou sobrepostos) na altura do meio do peito, logo abaixo da clavícula.","**Descida:** Contraia o core e sente-se para trás no agachamento, mantendo o peito aberto e o peso nos calcanhares, até as coxas ficarem pelo menos paralelas ao chão; uma boa referência é quando os cotovelos encostam na parte superior das coxas ou do lado de dentro dos joelhos.","**Postura:** Mantenha as costas planas e a coluna neutra durante todo o movimento.","**Impulso:** Suba impulsionando com força pelos calcanhares e use o impulso das pernas para lançar o peso para cima.","**Extensão:** Em um movimento fluido, pressione a barra acima da cabeça até estender totalmente os braços; no topo, os bíceps devem ficar próximos das orelhas.","**Inclinação:** Ao chegar ao alto do desenvolvimento, incline-se levemente para frente, em direção à barra, para favorecer a rotação adequada das escápulas e evitar a hiperextensão da lombar.","Desça a barra lentamente até a altura do peito, com controle, antes de iniciar imediatamente a próxima repetição."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["shoulders","glutes","quadriceps"],"secondaryMuscles":["hamstrings","abdominals"],"equipment":"barbell"},{"id":"wger-1830","source":"https://wger.de/en/exercise/1830/view/","name":"Afundo para trás com barra","portuguese":true,"instructions":["1. Fique de pé com os pés na largura do quadril, segurando uma barra apoiada na parte superior das costas.","2. Mantenha as costas retas, o peito aberto e o core contraído.","3. Dê um passo para trás com uma perna e desça o corpo flexionando os dois joelhos, até o joelho de trás quase encostar no chão.","4. Empurre com o pé de trás para voltar à posição inicial.","5. Repita o movimento com a outra perna, alternando os lados pelo número de repetições desejado."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["quadriceps"],"secondaryMuscles":[],"equipment":"barbell"},{"id":"wger-1831","source":"https://wger.de/en/exercise/1831/view/","name":"Supino declinado na Hammer","portuguese":true,"instructions":["1. Sente-se ereto na máquina Hammer de supino declinado, com as escápulas aproximadas e os calcanhares firmes no chão, abaixo dos joelhos.","2. O apoio das costas deve manter contato com a cabeça, os ombros e o glúteo o tempo todo.","3. Segure as alças com pegada pronada, um pouco mais aberta que a largura dos ombros e logo abaixo do peito.","4. Mantendo o core firme, respirando para o abdômen e contraindo a musculatura abdominal, empurre com as palmas para estender os cotovelos, mantendo-os a 45 graus do tronco.","5. Depois de estender totalmente os braços, volte à posição inicial."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"equipment":""},{"id":"wger-1833","source":"https://wger.de/en/exercise/1833/view/","name":"Flexão de isquiotibiais com deslizador no chão","portuguese":true,"instructions":["Deite-se de costas com os calcanhares sobre deslizadores de chão ou toalhas. Eleve o quadril formando uma ponte e deslize os calcanhares na direção dos glúteos, mantendo o quadril elevado. Volte lentamente à posição inicial sem perder a ponte de quadril."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["hamstrings"],"secondaryMuscles":["calves","glutes"],"equipment":""},{"id":"wger-1835","source":"https://wger.de/en/exercise/1835/view/","name":"Alongamento de rotação externa","portuguese":true,"instructions":["1. Sente-se com os pés pressionados um contra o outro e um dos joelhos elevado e aberto para a lateral do corpo.","2. Apoie o cotovelo sobre o joelho elevado, flexione-o a 90 graus e aponte a mão diretamente para frente, segurando a barra ou o halter.","3. Mantenha o ombro deprimido e retraído e eleve a mão até o antebraço ficar na vertical, como se fosse acenar para alguém como um robô.","4. Desça a mão à posição original e repita."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["shoulders"],"secondaryMuscles":[],"equipment":"barbell"},{"id":"wger-1838","source":"https://wger.de/en/exercise/1838/view/","name":"Mobilidade de ombro com elástico","portuguese":true,"instructions":["1. Prenda uma faixa elástica em um ponto firme atrás de você. Afaste-se e segure a faixa com a mão, de modo que ela fique tensionada.","2. Execute os movimentos de mobilidade e rotação do ombro mostrados no vídeo: https://www.youtube.com/watch?v=zdwEWchSjrI"],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["shoulders","chest"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1840","source":"https://wger.de/en/exercise/1840/view/","name":"Alongamento de isquiotibiais com perna flexionada","portuguese":true,"instructions":["Deitado de costas, com uma perna estendida no chão, segure a outra perna flexionada pelo joelho ou pela parte de trás da coxa e traga-a em direção ao peito, mantendo o joelho dobrado para alongar os isquiotibiais. Segure a posição respirando de forma relaxada e depois troque de lado. Vídeo de referência: https://www.youtube.com/watch?v=CrF2iMnn09w"],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":""},{"id":"wger-1842","source":"https://wger.de/en/exercise/1842/view/","name":"Concha com elástico","portuguese":true,"instructions":["**Posição:** Deite-se de lado com o cotovelo e o antebraço apoiados no chão e as pernas levemente flexionadas. Passe um elástico dobrado entre as coxas, logo acima do joelho.","**Execução:** Eleve o joelho de cima mantendo os pés unidos, como uma concha se abrindo, e depois volte lentamente à posição inicial. Mantenha o core estável e o quadril alinhado."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["glutes","abdominals"],"secondaryMuscles":["quadriceps"],"equipment":""},{"id":"wger-1843","source":"https://wger.de/en/exercise/1843/view/","name":"Alongamento borboleta","portuguese":true,"instructions":["1. Sente-se com as solas dos pés levemente pressionadas uma contra a outra.","2. Com as mãos, puxe os pés lentamente para dentro, na direção da virilha, e segure pelo tempo necessário."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":""},{"id":"wger-1844","source":"https://wger.de/en/exercise/1844/view/","name":"Alongamento do sapo","portuguese":true,"instructions":["1. Fique de quatro, apoiado nas mãos e nos joelhos.","2. Afaste os joelhos para fora e desça o tronco até apoiar os antebraços no chão.","3. Sem mover os cotovelos nem os joelhos, comece a balançar para frente e para trás, tentando aproximar o glúteo dos pés."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["glutes"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1846","source":"https://wger.de/en/exercise/1846/view/","name":"Posição de cavalo (abertura lateral)","portuguese":true,"instructions":["1. Fique em pé como no agachamento, com os pés bem afastados e as pontas dos pés levemente voltadas para fora.","2. Desça suavemente num agachamento profundo e amplo — o quadril deve ficar abaixo da linha dos joelhos.","3. Segure de 3 a 5 segundos.","4. Suba com controle e repita conforme necessário."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["glutes"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1852","source":"https://wger.de/en/exercise/1852/view/","name":"Isometria em L (variação)","portuguese":true,"instructions":["Sentado no chão com as pernas juntas e os braços ao lado do corpo, empurre o corpo para fora do chão com as mãos, mantendo a mesma posição sentada, de modo que as pernas fiquem estendidas e os pés não toquem o solo.","Segure pelo tempo que for necessário."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["lats","chest","abdominals"],"secondaryMuscles":["quadriceps","triceps"],"equipment":""},{"id":"wger-1853","source":"https://wger.de/en/exercise/1853/view/","name":"Isometria em L com apoio dos pés","portuguese":true,"instructions":["Igual à isometria em L, mas permitindo que os pés toquem o chão para sustentar parte do peso das pernas."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["lats","chest","abdominals"],"secondaryMuscles":["quadriceps","triceps"],"equipment":""},{"id":"wger-1854","source":"https://wger.de/en/exercise/1854/view/","name":"Liberação de panturrilha com rolo","portuguese":true,"instructions":["Deslize as panturrilhas lentamente sobre o rolo de espuma."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["calves"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1855","source":"https://wger.de/en/exercise/1855/view/","name":"Liberação de posterior de coxa com rolo","portuguese":true,"instructions":["Deslize o posterior das coxas lentamente sobre o rolo de espuma."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":""},{"id":"wger-1856","source":"https://wger.de/en/exercise/1856/view/","name":"Liberação de tibial anterior com rolo","portuguese":true,"instructions":["Deslize o rolo de espuma lentamente sobre o tibial anterior, na parte da frente da canela, com pressão moderada e movimentos de vai e vem."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":""},{"id":"wger-1857","source":"https://wger.de/en/exercise/1857/view/","name":"Liberação de trato iliotibial com rolo","portuguese":true,"instructions":["Deslize o rolo de espuma lentamente sobre o trato iliotibial, na lateral da coxa, com pressão moderada e movimentos de vai e vem."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["quadriceps"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1858","source":"https://wger.de/en/exercise/1858/view/","name":"Liberação de quadríceps com rolo","portuguese":true,"instructions":["Deslize o rolo de espuma lentamente sobre o quadríceps, com pressão moderada e movimentos de vai e vem."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["quadriceps"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1859","source":"https://wger.de/en/exercise/1859/view/","name":"Liberação de glúteo com rolo","portuguese":true,"instructions":["Deslize o rolo de espuma lentamente sobre o glúteo, com pressão moderada e movimentos de vai e vem."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["glutes"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1860","source":"https://wger.de/en/exercise/1860/view/","name":"Liberação de adutores com rolo","portuguese":true,"instructions":["Deslize o rolo de espuma lentamente sobre os adutores, na parte interna da coxa, com pressão moderada e movimentos de vai e vem."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":""},{"id":"wger-1863","source":"https://wger.de/en/exercise/1863/view/","name":"Rotação de quadril deitado","portuguese":true,"instructions":["Deite-se de costas com os braços estendidos para os lados e os joelhos flexionados, pernas juntas.","Leve lentamente os dois joelhos para um lado, mantendo os ombros e os braços apoiados no chão. Você deve sentir o alongamento no quadril, nos glúteos e na lombar.","Segure por um instante, volte os joelhos ao centro e repita do outro lado."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":""},{"id":"wger-1864","source":"https://wger.de/en/exercise/1864/view/","name":"Círculos de tornozelo","portuguese":true,"instructions":["Sentado ou deitado, eleve o pé e desenhe círculos lentos com o tornozelo, nos dois sentidos, mantendo o movimento apenas na articulação. Repita com o outro pé."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":""},{"id":"wger-1865","source":"https://wger.de/en/exercise/1865/view/","name":"Mobilidade de tornozelo com elástico","portuguese":true,"instructions":["Prenda um elástico em um ponto baixo atrás de você, por exemplo na base de um rack, e passe-o pela frente do tornozelo, logo acima do pé.","Fique em posição semiajoelhada com o pé do elástico à frente, de modo que o elástico puxe o tornozelo para trás.","Mantendo o calcanhar no chão, leve o joelho à frente sobre a ponta do pé e volte com controle. Repita algumas vezes e troque de lado."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":""},{"id":"wger-1867","source":"https://wger.de/en/exercise/1867/view/","name":"Alongamento de flexores do quadril","portuguese":true,"instructions":["Em posição de afundo ajoelhado, com um joelho no chão e o outro pé à frente, mantenha o tronco ereto, contraia o glúteo e leve o quadril à frente até sentir o alongamento na parte da frente da coxa. Segure e depois troque de lado."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":""},{"id":"wger-1877","source":"https://wger.de/en/exercise/1877/view/","name":"Retração escapular com elástico","portuguese":true,"instructions":["Prenda uma das pontas do elástico na parede, num batente ou apoio similar, na altura do ombro. Encaixe o braço na alça, na altura do tríceps. Afaste-se até o elástico ficar esticado. Puxe o cotovelo e o ombro para trás contra a resistência do elástico."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["shoulders"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1879","source":"https://wger.de/en/exercise/1879/view/","name":"Elevação em Y com halteres no banco inclinado","portuguese":true,"instructions":["1. Ajuste um banco inclinado em 45 graus e sente-se de frente para o banco, com o peito apoiado na almofada e um halter em cada mão, com as palmas voltadas uma para a outra.","2. Fixe bem os pés no chão para estabilidade e deixe os braços pendidos naturalmente, com leve flexão nos cotovelos.","3. Contraia o abdômen e mantenha a coluna reta durante todo o movimento.","4. Eleve os braços à frente e para fora, formando a letra Y, mantendo o movimento controlado e os cotovelos levemente flexionados.","5. Suba até os braços ficarem aproximadamente paralelos ao chão e alinhados com as orelhas.","6. Faça uma breve pausa no topo do movimento para envolver bem a musculatura do ombro e desça lentamente os braços até a posição inicial.","7. Faça o movimento de forma lenta e controlada tanto na subida quanto na descida, para maximizar o recrutamento dos deltoides e dos músculos de suporte.","8. Repita pelo número de repetições desejado, mantendo a execução correta o tempo todo."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["shoulders"],"secondaryMuscles":[],"equipment":"dumbbell"},{"id":"wger-1881","source":"https://wger.de/en/exercise/1881/view/","name":"Extensão de punho com halteres","portuguese":true,"instructions":["Segure dois halteres com pegada pronada e apoie os antebraços sobre os joelhos.","Deixe os punhos fletirem totalmente e depois estenda os punhos."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":"dumbbell"},{"id":"wger-1882","source":"https://wger.de/en/exercise/1882/view/","name":"Elevação lateral na polia alta","portuguese":true,"instructions":["Fique em pé ao lado da máquina de polia com o pino ajustado na altura da cintura.","Pegue a alça do lado oposto com a mão mais distante da polia, mantendo a palma da mão voltada para dentro.","Mantenha o abdômen contraído, o peito elevado e os ombros relaxados. Mantenha uma leve flexão no cotovelo durante toda a elevação.","Eleve o braço lateralmente até o cotovelo alcançar a altura do ombro, mantendo o punho alinhado ao cotovelo.","Faça uma breve pausa no topo e desça lentamente a alça de volta ao lado do corpo, com controle. Repita pelo número de repetições desejado."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["shoulders"],"secondaryMuscles":["lats"],"equipment":""},{"id":"wger-1889","source":"https://wger.de/en/exercise/1889/view/","name":"Elevação de pernas no banco declinado","portuguese":true,"instructions":["- **Preparação:** Deite-se num banco declinado com a cabeça na parte alta e segure as alças.","- **Início:** Estenda as pernas totalmente, mantendo-as levemente elevadas para contrair o abdômen.","- **Elevação:** Suba as pernas em direção ao teto usando o abdômen, e não o impulso.","- **Contração:** Faça uma pausa e contraia o abdômen inferior no topo.","- **Retorno:** Desça as pernas lentamente até a posição inicial, com controle."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["abdominals"],"secondaryMuscles":[],"equipment":""},{"id":"Clean_and_Press","source":"https://wger.de/en/exercise/1901/view/","name":"Arremesso e desenvolvimento","portuguese":true,"instructions":["- **Primeira puxada:** Tire a barra do chão até a altura dos joelhos empurrando com as pernas, mantendo o ângulo das costas constante.","- **Posição de força:** Quando a barra chegar à metade da coxa, faça um encolhimento explosivo e estenda o quadril para gerar impulso vertical.","- **Giro rápido dos cotovelos:** Na fase de recepção, gire os cotovelos rapidamente por baixo da barra para formar um apoio sobre os deltoides frontais.","- **Desenvolvimento vertical:** Empurre a barra em linha reta; a cabeça deve avançar levemente quando a barra passar pela testa, até a extensão total dos braços."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"}},{"id":"wger-1906","source":"https://wger.de/en/exercise/1906/view/","name":"Ponte de quadril","portuguese":true,"instructions":["Fique na posição de ponte, apoiado nos calcanhares, e comece a estender as pernas unilateralmente.","Mantenha o quadril estendido o máximo possível."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["glutes","abdominals"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1908","source":"https://wger.de/en/exercise/1908/view/","name":"Superman borboleta","portuguese":true,"instructions":["Deite-se de bruços, entrelace os dedos atrás da cabeça e comece a elevar a cabeça, subindo os cotovelos o máximo que conseguir."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":""},{"id":"wger-1909","source":"https://wger.de/en/exercise/1909/view/","name":"Roda de pernas","portuguese":true,"instructions":["Deite-se de costas e eleve as pernas na perpendicular, mantendo os joelhos juntos.","Comece a fazer pequenos círculos em uma direção com os dois joelhos, com amplitude bem curta, concentrando no abdômen e mantendo as costas em contato com o chão."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["abdominals"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1910","source":"https://wger.de/en/exercise/1910/view/","name":"Superman ajoelhado","portuguese":true,"instructions":["- Ajoelhado, empurre um pé para trás até a perna ficar totalmente estendida, com o pé alto e projetado para trás como se estivesse sendo puxado.","- Estenda o braço à frente, mantendo o ombro bem elevado.","Exercício unilateral e de isometria estática."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["hamstrings"],"secondaryMuscles":["abdominals"],"equipment":""},{"id":"wger-1911","source":"https://wger.de/en/exercise/1911/view/","name":"Prancha gato","portuguese":true,"instructions":["Em quatro apoios, eleve os joelhos do chão bem pouco. Arqueie as costas para fora e empurre a partir dos ombros, imitando um gato que se faz grande."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["quadriceps","abdominals"],"secondaryMuscles":["shoulders"],"equipment":""},{"id":"wger-1912","source":"https://wger.de/en/exercise/1912/view/","name":"Rotação de core","portuguese":true,"instructions":["Sente-se inclinando o tronco para trás, eleve os pés do chão com os joelhos flexionados e comece a girar para a esquerda e para a direita, tocando o chão com as mãos a cada movimento."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["quadriceps","abdominals"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1914","source":"https://wger.de/en/exercise/1914/view/","name":"Isometria nas paralelas","portuguese":true,"instructions":["A isometria nas barras paralelas é um exercício estático de membros superiores feito nas barras de mergulho. Em vez de subir e descer como no mergulho tradicional, você mantém uma posição fixa sob tensão."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["chest"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1918","source":"https://wger.de/en/exercise/1918/view/","name":"Supino máquina Legend","portuguese":true,"instructions":["Máquina de supino carregada com anilhas da linha LeverEdge, da Legend Fitness."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"equipment":""},{"id":"wger-1919","source":"https://wger.de/en/exercise/1919/view/","name":"Alongamento extremo de peitoral","portuguese":true,"instructions":["Alongamento profundo e carregado para o peitoral, normalmente feito ao final do treino de peito."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":""},{"id":"wger-1920","source":"https://wger.de/en/exercise/1920/view/","name":"Alongamento extremo de ombro","portuguese":true,"instructions":["Alongamento profundo e carregado para os deltoides, feito após os movimentos de empurrar."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":""},{"id":"wger-1921","source":"https://wger.de/en/exercise/1921/view/","name":"Alongamento extremo de dorsal","portuguese":true,"instructions":["Alongamento profundo e carregado para o grande dorsal, feito após os movimentos de puxar."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":""},{"id":"wger-1924","source":"https://wger.de/en/exercise/1924/view/","name":"Abdominal máquina 3008","portuguese":true,"instructions":["Indicado especificamente para a máquina de abdominal modelo 3008 da gym80."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["abdominals"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1925","source":"https://wger.de/en/exercise/1925/view/","name":"Encolhimento com barra Silverback","portuguese":true,"instructions":["1. Fique em pé com os pés na largura dos ombros, segurando a barra à frente com as duas mãos, um pouco além da largura dos ombros.","2. Incline o tronco no quadril com leve flexão dos joelhos, mantendo as costas retas.","3. Contraia as escápulas, como se tentasse encostar uma na outra.","4. Solte o encolhimento."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":"barbell"},{"id":"wger-1927","source":"https://wger.de/en/exercise/1927/view/","name":"Puxada alta supinada","portuguese":true,"instructions":["A **puxada alta com pegada invertida** (mais conhecida como **puxada alta supinada**) é uma variação do exercício padrão que usa pegada supinada, com as mãos na largura dos ombros. Essa posição desloca mais ênfase para a **parte inferior do dorsal** e aumenta a participação do **bíceps**, geralmente permitindo maior amplitude e uma contração mais profunda na parte baixa do movimento."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["lats"],"secondaryMuscles":["biceps","abdominals"],"equipment":"body only"},{"id":"wger-1929","source":"https://wger.de/en/exercise/1929/view/","name":"Barra fixa assistida (variação)","portuguese":true,"instructions":["**A barra fixa assistida** é um exercício composto de puxada vertical feito em máquina com plataforma de contrapeso ou com elásticos de resistência. Ela reproduz a mecânica da barra fixa tradicional, mas reduz o peso total que você precisa levantar, o que a torna uma ótima ferramenta para construir força funcional e aprimorar a técnica."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["lats"],"secondaryMuscles":["shoulders","biceps","abdominals"],"equipment":""},{"id":"wger-1931","source":"https://wger.de/en/exercise/1931/view/","name":"Rosca com halteres","portuguese":true,"instructions":["**A rosca com halteres** é um exercício clássico de isolamento para os braços. Diferente da rosca martelo, envolve a rotação dos punhos (supinação) durante a subida, o que permite a contração completa do bíceps."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["biceps"],"secondaryMuscles":["shoulders","abdominals"],"equipment":"dumbbell"},{"id":"wger-1933","source":"https://wger.de/en/exercise/1933/view/","name":"Abdominal supra (variação)","portuguese":true,"instructions":["**O abdominal supra** é um exercício clássico de isolamento do core feito no chão ou no colchonete. Diferente do abdominal completo, tem amplitude menor: você só tira os ombros e a parte alta das costas do chão, mantendo a lombar bem apoiada no solo."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["abdominals"],"secondaryMuscles":[],"equipment":""},{"id":"wger-1935","source":"https://wger.de/en/exercise/1935/view/","name":"Agachamento com cinto","portuguese":true,"instructions":["Agachamento com cinto: variação feita com um cinto preso a uma máquina de carga ou plataforma, de modo que o peso é sustentado nos quadris e não na coluna. Trabalha principalmente quadríceps e glúteos, com bem menos fadiga lombar do que o agachamento com barra. Use amplitude completa, mantenha o tronco ereto e empurre pelo meio do pé."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":["glutes","quadriceps"],"secondaryMuscles":["hamstrings"],"equipment":""},{"id":"wger-1936","source":"https://wger.de/en/exercise/1936/view/","name":"Crucifixo inverso na polia (unilateral)","portuguese":true,"instructions":["**Crucifixo inverso na polia (unilateral):** fique de lado para a polia, com a alça na altura dos ombros. Com o cotovelo levemente flexionado, puxe a alça para fora e para trás num arco amplo, de modo que o braço se afaste do corpo. Mantenha o tronco parado e concentre o trabalho no deltoide posterior. Use **carga leve a moderada** e repetições controladas."],"credit":{"author":"jptjptjptjpt","license":"CC-BY-SA 4","url":"https://creativecommons.org/licenses/by-sa/4.0/deed.en"},"images":[],"primaryMuscles":[],"secondaryMuscles":[],"equipment":""}];
